INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('fa3d47d5-1973-518a-ae86-c5513df88f12', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 12, 12, 'The fire on the altar shall be kept burning on it, it shall not go out; and the priest shall burn wood on it every morning: and he shall lay the burnt offering in order upon it, and shall burn on it the fat of the peace offerings.'),
  ('70fa9c80-ca0e-5e6d-adad-c4018827fd1c', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 13, 13, 'Fire shall be kept burning on the altar continually; it shall not go out.'),
  ('a8aa1da8-c50e-5504-a78d-982974aba20a', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 14, 14, '"''This is the law of the meal offering: the sons of Aaron shall offer it before Yahweh, before the altar.'),
  ('238987f6-2bba-5403-a236-ed9c9fa36a3a', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 15, 15, 'He shall take from there his handful of the fine flour of the meal offering, and of its oil, and all the frankincense which is on the meal offering, and shall burn it on the altar for a pleasant aroma, as its memorial, to Yahweh.'),
  ('2f37da02-dc54-50ca-af5c-ef28ad4051cf', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 16, 16, 'That which is left of it Aaron and his sons shall eat. It shall be eaten without yeast in a holy place. They shall eat it in the court of the Tent of Meeting'),
  ('e5f0cfd7-313b-57e2-a205-717d910775e0', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 17, 17, 'It shall not be baked with yeast. I have given it as their portion of my offerings made by fire. It is most holy, as the sin offering, and as the trespass offering.'),
  ('774b7813-8418-5410-a026-e065d2b6910f', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 18, 18, 'Every male among the children of Aaron shall eat of it, as their portion forever throughout your generations, from the offerings of Yahweh made by fire. Whoever touches them shall be holy.''"'),
  ('129fc970-9956-566b-a316-24d7407a874d', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 19, 19, 'Yahweh spoke to Moses, saying,'),
  ('7081cfae-fb12-50bc-a0f6-d0cf4b74f002', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 20, 20, '"This is the offering of Aaron and of his sons, which they shall offer to Yahweh in the day when he is anointed: the tenth part of an ephah of fine flour for a meal offering perpetually, half of it in the morning, and half of it in the evening.'),
  ('aab95add-b5a0-50b3-a2b9-cbb646051225', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 21, 21, 'It shall be made with oil in a griddle. When it is soaked, you shall bring it in. You shall offer the meal offering in baked pieces for a pleasant aroma to Yahweh.'),
  ('76ec3d60-5fbd-54a8-a2a4-53ae104459f4', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 22, 22, 'The anointed priest that will be in his place from among his sons shall offer it. By a statute forever, it shall be wholly burnt to Yahweh.'),
  ('5fbf2ec0-0e1a-50fa-ac7f-78df1ef164b8', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 23, 23, 'Every meal offering of a priest shall be wholly burned. It shall not be eaten."'),
  ('4f6f9608-c236-51d2-a666-2dea6ab49dc4', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 24, 24, 'Yahweh spoke to Moses, saying,'),
  ('c17ac00b-325b-53d9-a64a-2726327fe4ff', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 25, 25, '"Speak to Aaron and to his sons, saying, ''This is the law of the sin offering: in the place where the burnt offering is killed, the sin offering shall be killed before Yahweh. It is most holy.'),
  ('d564b87c-c426-56a9-a751-b11e971ca0e6', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 26, 26, 'The priest who offers it for sin shall eat it. It shall be eaten in a holy place, in the court of the Tent of Meeting.'),
  ('6da194fb-b390-569b-a25c-cb9885259cb6', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 27, 27, 'Whatever shall touch its flesh shall be holy. When there is any of its blood sprinkled on a garment, you shall wash that on which it was sprinkled in a holy place.'),
  ('63b6ec25-42ff-5210-a209-5dd905bbfe4b', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 28, 28, 'But the earthen vessel in which it is boiled shall be broken; and if it is boiled in a bronze vessel, it shall be scoured, and rinsed in water.'),
  ('938eed48-7608-5dba-ab5b-2b3fdd00bc29', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 29, 29, 'Every male among the priests shall eat of it: it is most holy.'),
  ('c46e0278-f031-5235-a10e-2ef6554a7817', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 30, 30, 'No sin offering, of which any of the blood is brought into the Tent of Meeting to make atonement in the Holy Place, shall be eaten: it shall be burned with fire.'),
  ('6b6eaba9-66c3-591f-aa56-e7c9910d72db', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 1, 1, '"''This is the law of the trespass offering. It is most holy.'),
  ('585bd553-26a8-57cd-aee5-81c59d2df9ea', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 2, 2, 'In the place where they kill the burnt offering, he shall kill the trespass offering; and its blood he shall sprinkle around on the altar.'),
  ('52067e49-2895-58d7-a1c6-f04159cf2cd4', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 3, 3, 'He shall offer all of its fat: the fat tail, and the fat that covers the innards,'),
  ('4e048942-32dc-577f-a1f5-04a1e6ab2c21', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 4, 4, 'and the two kidneys, and the fat that is on them, which is by the loins, and the cover on the liver, with the kidneys, shall he take away;'),
  ('64567429-7cc1-5978-a176-1a2b41021b92', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 5, 5, 'and the priest shall burn them on the altar for an offering made by fire to Yahweh: it is a trespass offering.'),
  ('0de99490-a2d6-5f40-ab87-05469f21d6bf', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 6, 6, 'Every male among the priests may eat of it. It shall be eaten in a holy place. It is most holy.'),
  ('498b62b0-3a5c-53a4-af0c-393aae23fa69', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 7, 7, '"''As is the sin offering, so is the trespass offering; there is one law for them. The priest who makes atonement with them shall have it.'),
  ('91f9d1d6-01c9-5df4-a6bc-3b40002749a5', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 8, 8, 'The priest who offers any man''s burnt offering, even the priest shall have for himself the skin of the burnt offering which he has offered.'),
  ('2b3d8169-6ac4-5546-acf6-56e3f6951109', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 9, 9, 'Every meal offering that is baked in the oven, and all that is dressed in the pan, and on the griddle, shall be the priest''s who offers it.'),
  ('f9c6bb93-29a8-5011-a9ff-d865c932d212', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 10, 10, 'Every meal offering, mixed with oil or dry, belongs to all the sons of Aaron, one as well as another.'),
  ('0714bac0-274b-5e3d-a5f1-285d06036b5e', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 11, 11, '"''This is the law of the sacrifice of peace offerings, which one shall offer to Yahweh.'),
  ('dcdca80c-a5b8-59bf-ad4a-8de3e3a93ed7', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 12, 12, 'If he offers it for a thanksgiving, then he shall offer with the sacrifice of thanksgiving unleavened cakes mixed with oil, and unleavened wafers anointed with oil, and cakes mixed with oil.'),
  ('22da105e-47bf-57ad-aa64-d438546fa043', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 13, 13, 'With cakes of leavened bread he shall offer his offering with the sacrifice of his peace offerings for thanksgiving.'),
  ('88c4c243-15f6-5b28-a347-50b539500175', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 14, 14, 'Of it he shall offer one out of each offering for a heave offering to Yahweh. It shall be the priest''s who sprinkles the blood of the peace offerings.'),
  ('916fb176-6d8b-51e8-aff8-2f035d7b4348', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 15, 15, 'The flesh of the sacrifice of his peace offerings for thanksgiving shall be eaten on the day of his offering. He shall not leave any of it until the morning.'),
  ('1c660e33-4a9f-5887-a476-6de63201aa56', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 16, 16, '"''But if the sacrifice of his offering is a vow, or a freewill offering, it shall be eaten on the day that he offers his sacrifice; and on the next day what remains of it shall be eaten:'),
  ('ca71c967-ad1e-562a-af2d-ef57640169db', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 17, 17, 'but what remains of the flesh of the sacrifice on the third day shall be burned with fire.'),
  ('2558c7a1-1b4c-557f-a474-6b6a0211c3bd', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 18, 18, 'If any of the flesh of the sacrifice of his peace offerings is eaten on the third day, it will not be accepted, neither shall it be imputed to him who offers it. It will be an abomination, and the soul who eats any of it will bear his iniquity.'),
  ('19999fb0-3dec-50cd-a3ff-86b98696f0f5', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 19, 19, '"''The flesh that touches any unclean thing shall not be eaten. It shall be burned with fire. As for the flesh, everyone who is clean may eat it;'),
  ('09db4251-e332-5d84-a0d1-4ea8e0d233b6', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 20, 20, 'but the soul who eats of the flesh of the sacrifice of peace offerings, that belongs to Yahweh, having his uncleanness on him, that soul shall be cut off from his people.'),
  ('75d98f72-4e7a-58a4-ac55-9df85403bcfd', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 21, 21, 'When anyone touches any unclean thing, the uncleanness of man, or an unclean animal, or any unclean abomination, and eats some of the flesh of the sacrifice of peace offerings, which belong to Yahweh, that soul shall be cut off from his people.''"'),
  ('75865934-48f0-58f6-a41a-ab4b5735f9b9', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 22, 22, 'Yahweh spoke to Moses, saying,'),
  ('df19b5b2-eb10-5889-ae58-fea4ea3f953e', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 23, 23, '"Speak to the children of Israel, saying, ''You shall eat no fat, of bull, or sheep, or goat.'),
  ('5837ea96-e0ce-5c37-a273-a8a71d5d4679', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 24, 24, 'The fat of that which dies of itself, and the fat of that which is torn of animals, may be used for any other service, but you shall in no way eat of it.'),
  ('9e2aa595-f2fe-5286-af09-0f4a484550c1', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 25, 25, 'For whoever eats the fat of the animal, of which men offer an offering made by fire to Yahweh, even the soul who eats it shall be cut off from his people.'),
  ('66be4e6c-29fd-5e11-af46-7cb031e7dcf4', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 26, 26, 'You shall not eat any blood, whether it is of bird or of animal, in any of your dwellings.'),
  ('0651c33d-e868-5483-a277-0c263b081fc0', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 27, 27, 'Whoever it is who eats any blood, that soul shall be cut off from his people.''"'),
  ('5de223de-8686-5e6c-ada0-d63ac81b0f4a', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 28, 28, 'Yahweh spoke to Moses, saying,'),
  ('77913087-96ab-5b31-aad4-18174bb2d25e', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 29, 29, '"Speak to the children of Israel, saying, ''He who offers the sacrifice of his peace offerings to Yahweh shall bring his offering to Yahweh out of the sacrifice of his peace offerings.'),
  ('2138e1a1-0ca7-51bf-a252-2c9682e5fe2b', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 30, 30, 'With his own hands he shall bring the offerings of Yahweh made by fire. He shall bring the fat with the breast, that the breast may be waved for a wave offering before Yahweh.'),
  ('3aaca056-cdc9-5ddb-ad41-1cdb8089ef3f', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 31, 31, 'The priest shall burn the fat on the altar, but the breast shall be Aaron''s and his sons''.'),
  ('fd338921-01d6-5fc7-a5bf-f10bd7493d80', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 32, 32, 'The right thigh you shall give to the priest for a heave offering out of the sacrifices of your peace offerings.'),
  ('9231fad7-4ff1-50df-a60f-d6f10bd35123', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 33, 33, 'He among the sons of Aaron who offers the blood of the peace offerings, and the fat, shall have the right thigh for a portion.'),
  ('7cb8e4ed-d2ff-5743-a6d3-e2d170d2aca0', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 34, 34, 'For the waved breast and the heaved thigh I have taken from the children of Israel out of the sacrifices of their peace offerings, and have given them to Aaron the priest and to his sons as their portion forever from the children of Israel.''"'),
  ('30016f25-04a9-5463-aac2-b2daf300bb71', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 35, 35, 'This is the anointing portion of Aaron, and the anointing portion of his sons, out of the offerings of Yahweh made by fire, in the day when he presented them to minister to Yahweh in the priest''s office;'),
  ('3e7f167b-5333-5a31-a31a-8bf4b4c80edc', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 36, 36, 'which Yahweh commanded to be given them of the children of Israel, in the day that he anointed them. It is their portion forever throughout their generations.'),
  ('15b21cb1-3d0b-5e5e-a365-d3e5ff98b00a', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 37, 37, 'This is the law of the burnt offering, of the meal offering, and of the sin offering, and of the trespass offering, and of the consecration, and of the sacrifice of peace offerings;'),
  ('f2806a6f-4950-5534-a54b-af0888481407', '25e495be-76c4-5180-a3bb-b42ca2ec6e5f', NULL, 38, 38, 'which Yahweh commanded Moses in Mount Sinai, in the day that he commanded the children of Israel to offer their offerings to Yahweh, in the wilderness of Sinai.'),
  ('fd6146d9-82ff-501b-a871-cac8218522fd', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('0d80c9bb-4ba4-5108-a095-2dab6e6a1563', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 2, 2, '"Take Aaron and his sons with him, and the garments, and the anointing oil, and the bull of the sin offering, and the two rams, and the basket of unleavened bread;'),
  ('1ab736bc-ad4d-5ac2-a6a1-07f58b92474c', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 3, 3, 'and assemble all the congregation at the door of the Tent of Meeting."'),
  ('a43b0da8-975f-5629-a69d-267301f0bc8a', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 4, 4, 'Moses did as Yahweh commanded him; and the congregation was assembled at the door of the Tent of Meeting.'),
  ('e9e434c6-501f-5edd-a707-f6891a284622', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 5, 5, 'Moses said to the congregation, "This is the thing which Yahweh has commanded to be done."'),
  ('09b3f9f8-d6c7-5e1a-a2b6-c9b0865dc3f6', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 6, 6, 'Moses brought Aaron and his sons, and washed them with water.'),
  ('5729c8fb-c3a7-5042-a38e-96aa387eacd7', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 7, 7, 'He put the coat on him, tied the sash on him, clothed him with the robe, put the ephod on him, and he tied the skillfully woven band of the ephod on him, and fastened it to him with it.'),
  ('cef86edc-be95-5552-a1b5-8d2dae98dd7f', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 8, 8, 'He placed the breastplate on him; and in the breastplate he put the Urim and the Thummim.'),
  ('44e572cd-5371-58ab-af39-4efbfd254ea4', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 9, 9, 'He set the turban on his head; and on the turban, in front, he set the golden plate, the holy crown; as Yahweh commanded Moses.'),
  ('0732cab1-ca05-58b0-ae2c-8af39c5a1525', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 10, 10, 'Moses took the anointing oil, and anointed the tabernacle and all that was in it, and sanctified them.'),
  ('2af6f50d-ad73-5b20-aa00-d1fb09e904e3', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 11, 11, 'He sprinkled it on the altar seven times, and anointed the altar and all its vessels, and the basin and its base, to sanctify them.'),
  ('4e10c897-50aa-560d-a27e-bd0ef99b9d49', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 12, 12, 'He poured some of the anointing oil on Aaron''s head, and anointed him, to sanctify him.'),
  ('7da68f17-243c-5d83-ae22-ff32bec13902', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 13, 13, 'Moses brought Aaron''s sons, and clothed them with coats, and tied sashes on them, and put headbands on them; as Yahweh commanded Moses.'),
  ('4ff8b465-d54a-5e50-aeff-d814a95e5fda', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 14, 14, 'He brought the bull of the sin offering, and Aaron and his sons laid their hands on the head of the bull of the sin offering.'),
  ('8c5fc407-5d08-503e-aaf5-2c53d1e1a44b', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 15, 15, 'He killed it; and Moses took the blood, and put it around on the horns of the altar with his finger, and purified the altar, and poured out the blood at the base of the altar, and sanctified it, to make atonement for it.'),
  ('2859fb22-c149-5b72-ae16-5375951dada3', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 16, 16, 'He took all the fat that was on the innards, and the cover of the liver, and the two kidneys, and their fat; and Moses burned it on the altar.'),
  ('912abc80-b253-5778-af27-550182b444da', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 17, 17, 'But the bull, and its skin, and its flesh, and its dung, he burned with fire outside the camp; as Yahweh commanded Moses.'),
  ('a3a234a2-0da0-5ab7-a515-cb1741fd64d1', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 18, 18, 'He presented the ram of the burnt offering: and Aaron and his sons laid their hands on the head of the ram.'),
  ('ff8786e1-83ba-57ae-a514-3cc35d27a76f', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 19, 19, 'He killed it; and Moses sprinkled the blood around on the altar.'),
  ('20877e38-8fb5-5b1d-a2e7-1cdfd498c15b', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 20, 20, 'He cut the ram into its pieces; and Moses burned the head, and the pieces, and the fat.'),
  ('899b6802-39be-5ce2-a674-6dc25b643332', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 21, 21, 'He washed the innards and the legs with water; and Moses burned the whole ram on the altar. It was a burnt offering for a pleasant aroma. It was an offering made by fire to Yahweh; as Yahweh commanded Moses.'),
  ('59fa6630-15ae-5924-af36-af0a0402cd88', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 22, 22, 'He presented the other ram, the ram of consecration: and Aaron and his sons laid their hands on the head of the ram.'),
  ('9bd8c355-c036-5bc0-ae80-93be18fe2e34', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 23, 23, 'He killed it; and Moses took some of its blood, and put it on the tip of Aaron''s right ear, and on the thumb of his right hand, and on the great toe of his right foot.'),
  ('4cca3010-3961-5ca8-adb5-f952f093d262', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 24, 24, 'He brought Aaron''s sons; and Moses put some of the blood on the tip of their right ear, and on the thumb of their right hand, and on the great toe of their right foot; and Moses sprinkled the blood around on the altar.'),
  ('2e00fa7e-e420-58a8-a5a0-4ec21adb865f', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 25, 25, 'He took the fat, and the fat tail, and all the fat that was on the innards, and the cover of the liver, and the two kidneys, and their fat, and the right thigh;'),
  ('f6b8bd44-903b-5c2f-a08f-e6ccb16680d4', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 26, 26, 'and out of the basket of unleavened bread, that was before Yahweh, he took one unleavened cake, and one cake of oiled bread, and one wafer, and placed them on the fat, and on the right thigh.'),
  ('b82ed656-e60a-53aa-a734-11eb8ea9a8d3', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 27, 27, 'He put all these in Aaron''s hands and in his sons'' hands, and waved them for a wave offering before Yahweh.'),
  ('34c52026-eada-5e0a-aa3d-5452456a6224', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 28, 28, 'Moses took them from their hands, and burned them on the altar on the burnt offering. They were a consecration for a pleasant aroma. It was an offering made by fire to Yahweh.'),
  ('6ef55065-23f0-5bcf-acbe-3dc395276926', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 29, 29, 'Moses took the breast, and waved it for a wave offering before Yahweh. It was Moses'' portion of the ram of consecration, as Yahweh commanded Moses.'),
  ('ed7d5e3b-4ae6-543e-a6a3-742adffc1c11', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 30, 30, 'Moses took some of the anointing oil, and some of the blood which was on the altar, and sprinkled it on Aaron, on his garments, and on his sons, and on his sons'' garments with him, and sanctified Aaron, his garments, and his sons, and his sons'' garments with him.'),
  ('03427fc2-5fd1-5da8-a677-37f7eb03550e', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 31, 31, 'Moses said to Aaron and to his sons, "Boil the flesh at the door of the Tent of Meeting, and there eat it and the bread that is in the basket of consecration, as I commanded, saying, ''Aaron and his sons shall eat it.'''),
  ('c353a461-5025-51fa-a890-036182c64219', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 32, 32, 'What remains of the flesh and of the bread you shall burn with fire.'),
  ('1b09b228-48d2-53d8-afdd-85f4a794ba4c', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 33, 33, 'You shall not go out from the door of the Tent of Meeting seven days, until the days of your consecration are fulfilled: for he shall consecrate you seven days.'),
  ('9f0ce95b-4b51-5aac-a102-70d018684a97', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 34, 34, 'What has been done this day, so Yahweh has commanded to do, to make atonement for you.'),
  ('e3d6e652-16e3-5b20-a1fa-55596d0232c8', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 35, 35, 'You shall stay at the door of the Tent of Meeting day and night seven days, and keep Yahweh''s command, that you don''t die: for so I am commanded."'),
  ('9fbd1756-f0d5-512b-a9f1-ce5e45ef82c8', '7bd9edff-f1be-5e83-a14c-00ed4253afe2', NULL, 36, 36, 'Aaron and his sons did all the things which Yahweh commanded by Moses.'),
  ('8eea4b3f-7309-50a7-a74d-2ea0a342d0cd', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 1, 1, 'It happened on the eighth day, that Moses called Aaron and his sons, and the elders of Israel;'),
  ('84e7e58d-a7ff-57fb-a911-9c5417f298a5', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 2, 2, 'and he said to Aaron, "Take a calf from the herd for a sin offering, and a ram for a burnt offering, without blemish, and offer them before Yahweh.'),
  ('52c4d0a5-b98a-507d-a6cd-43dd2d30f1f6', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 3, 3, 'You shall speak to the children of Israel, saying, ''Take a male goat for a sin offering; and a calf and a lamb, both a year old, without blemish, for a burnt offering;'),
  ('5bd7d45f-a945-51d8-a12b-14fa211f18af', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 4, 4, 'and a bull and a ram for peace offerings, to sacrifice before Yahweh; and a meal offering mixed with oil: for today Yahweh appears to you.''"'),
  ('f5913541-ea35-5629-a7e8-187d0e6974fc', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 5, 5, 'They brought what Moses commanded before the Tent of Meeting: and all the congregation drew near and stood before Yahweh.'),
  ('ac840669-c0bf-578d-aa12-9858f7c0d5e1', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 6, 6, 'Moses said, "This is the thing which Yahweh commanded that you should do: and the glory of Yahweh shall appear to you."'),
  ('7cb6ca4d-dac9-5061-afc1-abc5e5158ac9', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 7, 7, 'Moses said to Aaron, "Draw near to the altar, and offer your sin offering, and your burnt offering, and make atonement for yourself, and for the people; and offer the offering of the people, and make atonement for them; as Yahweh commanded."'),
  ('bd16e18b-8e48-56c5-aa8b-f89c6802355f', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 8, 8, 'So Aaron drew near to the altar, and killed the calf of the sin offering, which was for himself.'),
  ('ec68d81a-fc1c-598c-a74b-24e65c5347e9', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 9, 9, 'The sons of Aaron presented the blood to him; and he dipped his finger in the blood, and put it on the horns of the altar, and poured out the blood at the base of the altar:'),
  ('a0ddffa7-79e3-5132-a887-e13e7de71c24', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 10, 10, 'but the fat, and the kidneys, and the cover from the liver of the sin offering, he burned upon the altar; as Yahweh commanded Moses.'),
  ('0054dfa8-3d19-5bb3-a805-21605a52b16f', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 11, 11, 'The flesh and the skin he burned with fire outside the camp.'),
  ('a3b3dbf7-e7ca-5e4c-a5d5-76c490599bde', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 12, 12, 'He killed the burnt offering; and Aaron''s sons delivered the blood to him, and he sprinkled it around on the altar.'),
  ('d13e97fb-7a76-5f59-ae24-eb8849a5e49a', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 13, 13, 'They delivered the burnt offering to him, piece by piece, and the head: and he burned them upon the altar.'),
  ('f91d7a4e-328c-5726-a719-27a12a045ec4', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 14, 14, 'He washed the innards and the legs, and burned them on the burnt offering on the altar.'),
  ('b3b35d7b-c9e6-5627-a579-82cc9d0b6216', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 15, 15, 'He presented the people''s offering, and took the goat of the sin offering which was for the people, and killed it, and offered it for sin, like the first.'),
  ('c4aa915b-e161-5f12-a56c-7749d7ea08a9', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 16, 16, 'He presented the burnt offering, and offered it according to the ordinance.'),
  ('297bc001-ba52-50c6-a544-280860d1f251', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 17, 17, 'He presented the meal offering, and filled his hand from there, and burned it upon the altar, besides the burnt offering of the morning.'),
  ('b6258b18-80d2-5263-a585-c2322b12ea92', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 18, 18, 'He also killed the bull and the ram, the sacrifice of peace offerings, which was for the people: and Aaron''s sons delivered to him the blood, which he sprinkled around on the altar,'),
  ('d5b6e1db-b3d9-5028-a435-8c5f624abcd0', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 19, 19, 'and the fat of the bull and of the ram, the fat tail, and that which covers the innards, and the kidneys, and the cover of the liver:'),
  ('bfd945e4-988b-57d9-a7e5-6fcb120f227f', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 20, 20, 'and they put the fat upon the breasts, and he burned the fat on the altar:'),
  ('be73fbf9-6448-5925-a10c-fbdc232c0b71', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 21, 21, 'and the breasts and the right thigh Aaron waved for a wave offering before Yahweh, as Moses commanded.'),
  ('a5daae28-105b-5088-a039-beb4aa24c0a3', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 22, 22, 'Aaron lifted up his hands toward the people, and blessed them; and he came down from offering the sin offering, and the burnt offering, and the peace offerings.'),
  ('a370683a-8d91-50d3-a91f-fe1ec6d2d81f', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 23, 23, 'Moses and Aaron went into the Tent of Meeting, and came out, and blessed the people: and the glory of Yahweh appeared to all the people.'),
  ('74a48093-f6b3-571e-ad91-7a90e4212887', 'c9b3877c-192f-5d51-a3f6-62ab9f40383d', NULL, 24, 24, 'There came forth fire from before Yahweh, and consumed the burnt offering and the fat upon the altar: and when all the people saw it, they shouted, and fell on their faces.'),
  ('13f8cf5c-8865-5b6f-a8de-cdf8a91c495b', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 1, 1, 'Nadab and Abihu, the sons of Aaron, each took his censer, and put fire in it, and laid incense on it, and offered strange fire before Yahweh, which he had not commanded them.'),
  ('fccb6945-83b4-5e01-a2c3-f2034e797505', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 2, 2, 'And fire came forth from before Yahweh, and devoured them, and they died before Yahweh.'),
  ('4cd994d4-d97d-50a2-a7c4-0b1e283556f1', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 3, 3, 'Then Moses said to Aaron, "This is what Yahweh spoke of, saying, ''I will show myself holy to those who come near me, and before all the people I will be glorified.''" Aaron held his peace.'),
  ('14bff35a-a675-582b-ab86-d8b653d314f6', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 4, 4, 'Moses called Mishael and Elzaphan, the sons of Uzziel the uncle of Aaron, and said to them, "Draw near, carry your brothers from before the sanctuary out of the camp."'),
  ('10708535-161a-55ce-a230-42ce9dcc5586', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 5, 5, 'So they drew near, and carried them in their coats out of the camp, as Moses had said.'),
  ('cb9fabf3-7119-59e6-ac79-8e2f5ae2d2e1', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 6, 6, 'Moses said to Aaron, and to Eleazar and to Ithamar, his sons, "Don''t let the hair of your heads go loose, neither tear your clothes; that you don''t die, and that he not be angry with all the congregation: but let your brothers, the whole house of Israel, bewail the burning which Yahweh has kindled.'),
  ('d69a9953-ab1b-548b-a2b4-8e5f72e0a1ae', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 7, 7, 'You shall not go out from the door of the Tent of Meeting, lest you die; for the anointing oil of Yahweh is on you." They did according to the word of Moses.'),
  ('660cda64-92be-594f-aca9-c3859d00aab1', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 8, 8, 'Yahweh spoke to Aaron, saying,'),
  ('c4ae8219-6704-54dd-af5c-f368dff2e732', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 9, 9, '"Drink no wine nor strong drink, you, nor your sons with you, when you go into the Tent of Meeting, that you don''t die: it shall be a statute forever throughout your generations:'),
  ('74cd23a4-5fd9-505c-a08d-2b62b5acf917', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 10, 10, 'and that you are to make a distinction between the holy and the common, and between the unclean and the clean;'),
  ('930ab055-15c6-55bb-ad82-9e86b83a7943', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 11, 11, 'and that you are to teach the children of Israel all the statutes which Yahweh has spoken to them by Moses."'),
  ('c88927a2-2937-551a-a767-594f2fdd3601', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 12, 12, 'Moses spoke to Aaron, and to Eleazar and to Ithamar, his sons who were left, "Take the meal offering that remains of the offerings of Yahweh made by fire, and eat it without yeast beside the altar; for it is most holy;'),
  ('d82cde54-fe65-5101-a19e-27384fc4d58c', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 13, 13, 'and you shall eat it in a holy place, because it is your portion, and your sons'' portion, of the offerings of Yahweh made by fire: for so I am commanded.'),
  ('e19760b6-36ea-5d94-ad84-6f6e5c1c6443', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 14, 14, 'The waved breast and the heaved thigh you shall eat in a clean place, you, and your sons, and your daughters with you: for they are given as your portion, and your sons'' portion, out of the sacrifices of the peace offerings of the children of Israel.'),
  ('7a53c574-65cb-56e8-aff5-3791a044a55f', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 15, 15, 'The heaved thigh and the waved breast they shall bring with the offerings made by fire of the fat, to wave it for a wave offering before Yahweh: and it shall be yours, and your sons'' with you, as a portion forever; as Yahweh has commanded."'),
  ('4b39bb1c-be84-5f3f-a3de-f8df34c70440', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 16, 16, 'Moses diligently inquired about the goat of the sin offering, and, behold, it was burned: and he was angry with Eleazar and with Ithamar, the sons of Aaron who were left, saying,'),
  ('68830c8f-c971-55af-a424-bc5d6b9d07b0', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 17, 17, '"Why haven''t you eaten the sin offering in the place of the sanctuary, since it is most holy, and he has given it you to bear the iniquity of the congregation, to make atonement for them before Yahweh?'),
  ('ee404559-113e-5361-aaf3-1520f17cdfe3', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 18, 18, 'Behold, its blood was not brought into the inner part of the sanctuary: you certainly should have eaten it in the sanctuary, as I commanded."'),
  ('4d1f4d6a-124d-581d-a17a-32dddae8219b', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 19, 19, 'Aaron spoke to Moses, "Behold, this day they have offered their sin offering and their burnt offering before Yahweh; and such things as these have happened to me: and if I had eaten the sin offering today, would it have been pleasing in the sight of Yahweh?"'),
  ('8ea00e59-6e55-541c-a8cb-d701551affab', 'a2262d2e-abcc-542c-a8f5-3c7345b6e716', NULL, 20, 20, 'When Moses heard that, it was pleasing in his sight.'),
  ('21731538-563a-573a-ae2c-934f2a3707e0', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying to them,'),
  ('a56bb833-a49c-5a0c-a7e9-7b415407e85c', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 2, 2, '"Speak to the children of Israel, saying, ''These are the living things which you may eat among all the animals that are on the earth.'),
  ('faf28583-8ded-5370-ac4c-47ef9a9b1a6e', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 3, 3, 'Whatever parts the hoof, and is cloven-footed, and chews the cud among the animals, that you may eat.'),
  ('25773ee9-1785-571e-aebc-9a9f70eaa1c9', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 4, 4, '"''Nevertheless these you shall not eat of those that chew the cud, or of those who part the hoof: the camel, because he chews the cud but doesn''t have a parted hoof, he is unclean to you.'),
  ('925b1819-465a-54c4-a33f-6d3df485f8b4', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 5, 5, 'The coney, because he chews the cud but doesn''t have a parted hoof, he is unclean to you.'),
  ('ccb4d6e3-b2a3-5d6f-aa40-aec77a3648f4', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 6, 6, 'The hare, because she chews the cud but doesn''t part the hoof, she is unclean to you.'),
  ('c82b5910-f943-5d96-a814-89c83d8a2948', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 7, 7, 'The pig, because he has a split hoof, and is cloven-footed, but doesn''t chew the cud, he is unclean to you.'),
  ('98d70020-7e30-5426-ae60-de265b08c0fd', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 8, 8, 'Of their flesh you shall not eat, and their carcasses you shall not touch; they are unclean to you.'),
  ('c18e51cc-94a7-5549-aa50-3fae0832a92c', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 9, 9, '"''These you may eat of all that are in the waters: whatever has fins and scales in the waters, in the seas, and in the rivers, that you may eat.'),
  ('5c587986-9a02-5b2a-a5d6-ca39106dd9e3', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 10, 10, 'All that don''t have fins and scales in the seas, and in the rivers, of all that move in the waters, and of all the living creatures that are in the waters, they are an abomination to you,'),
  ('f7e5b3f3-ab88-59d5-ac72-4098c0ea6fef', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 11, 11, 'and you detest them. You shall not eat of their flesh, and you shall detest their carcasses.'),
  ('7b6bed50-2f19-54eb-a257-30e3c6f463b3', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 12, 12, 'Whatever has no fins nor scales in the waters, that is an abomination to you.'),
  ('7fbb4deb-d1fd-5548-a8a5-da308b6e2397', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 13, 13, '"''These you shall detest among the birds; they shall not be eaten, they are an abomination: the eagle, and the vulture, and the black vulture,'),
  ('f45ad92e-ac9a-51e3-a5c6-ce9de263aa4e', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 14, 14, 'and the red kite, any kind of black kite,'),
  ('cf64fcb8-87f8-50c3-a51c-358dd7c7d0a3', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 15, 15, 'any kind of raven,'),
  ('f37139d8-a32a-506d-a063-4c571a081fb2', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 16, 16, 'the horned owl, the screech owl, and the gull, any kind of hawk,'),
  ('95191bfc-9b3e-54ed-a754-5ebec7e6be5c', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 17, 17, 'the little owl, the cormorant, the great owl,'),
  ('d0de6bad-512f-5564-a8b9-eee31fe9fcda', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 18, 18, 'the white owl, the desert owl, the osprey,'),
  ('d26060aa-8830-54ea-a53f-ba2f631c1f15', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 19, 19, 'the stork, any kind of heron, the hoopoe, and the bat.'),
  ('7ffbc66d-4e42-52ee-acc1-c64aee31ca2b', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 20, 20, '"''All flying insects that walk on all fours are an abomination to you.'),
  ('3ba9fd7a-77ac-5b25-a0a3-d795a65c246e', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 21, 21, 'Yet you may eat these: of all winged creeping things that go on all fours, which have legs above their feet, with which to hop on the earth.'),
  ('e0c10ad5-f62a-5ae3-a23a-8e519aee2467', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 22, 22, 'Even of these you may eat: any kind of locust, any kind of katydid, any kind of cricket, and any kind of grasshopper.'),
  ('0ac7c118-b7fe-5aee-ae83-a75ccfd451f9', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 23, 23, 'But all winged creeping things which have four feet, are an abomination to you.'),
  ('27aafdfb-91a8-5484-a08e-cf17ec4aa6c7', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 24, 24, '"''By these you will become unclean: whoever touches the carcass of them shall be unclean until the evening.'),
  ('4af1cd75-12b7-522c-ab0a-b87e25ff4a84', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 25, 25, 'Whoever carries any part of their carcass shall wash his clothes, and be unclean until the evening.'),
  ('f4a5bfaa-b09c-596b-ae7e-db9ae25642df', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 26, 26, '"''Every animal which parts the hoof, and is not cloven-footed, nor chews the cud, is unclean to you. Everyone who touches them shall be unclean.'),
  ('0d741b03-eeff-5818-a9b9-aeb34a8bba98', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 27, 27, 'Whatever goes on its paws, among all animals that go on all fours, they are unclean to you. Whoever touches their carcass shall be unclean until the evening.'),
  ('c104ef0c-50a3-57a5-a616-d2940feadc32', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 28, 28, 'He who carries their carcass shall wash his clothes, and be unclean until the evening. They are unclean to you.'),
  ('ed201381-e4ee-57c1-adb2-0b38f8ef3d93', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 29, 29, '"''These are they which are unclean to you among the creeping things that creep on the earth: the weasel, the rat, any kind of great lizard,'),
  ('c543a46e-45e3-54e6-ad30-fe78cd178a83', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 30, 30, 'the gecko, and the monitor lizard, the wall lizard, the skink, and the chameleon.'),
  ('4244da89-e8f6-5e45-a94b-fa4c884f089d', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 31, 31, 'These are they which are unclean to you among all that creep. Whoever touches them when they are dead, shall be unclean until the evening.'),
  ('6d14924d-3c50-52c0-a097-5e148d630ca4', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 32, 32, 'On whatever any of them falls when they are dead, it shall be unclean; whether it is any vessel of wood, or clothing, or skin, or sack, whatever vessel it is, with which any work is done, it must be put into water, and it shall be unclean until the evening; then it will be clean.'),
  ('8e7c5ed6-14db-57e9-a221-55d8889275e6', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 33, 33, 'Every earthen vessel, into which any of them falls, all that is in it shall be unclean, and you shall break it.'),
  ('5269e4dc-8237-55e3-a62d-594a3b0762b8', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 34, 34, 'All food which may be eaten, that on which water comes, shall be unclean; and all drink that may be drunk in every such vessel shall be unclean.'),
  ('22b65a87-540b-5009-a872-654a994b651a', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 35, 35, 'Everything whereupon part of their carcass falls shall be unclean; whether oven, or range for pots, it shall be broken in pieces: they are unclean, and shall be unclean to you.'),
  ('dc08fe1a-9be6-50e5-a95e-e4aae145e06b', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 36, 36, 'Nevertheless a spring or a cistern in which water is a gathered shall be clean: but that which touches their carcass shall be unclean.'),
  ('160d427d-7151-5e80-a82e-3b5996831591', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 37, 37, 'If part of their carcass falls on any sowing seed which is to be sown, it is clean.'),
  ('48fc3a91-9993-57cc-a077-d206a92157bb', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 38, 38, 'But if water is put on the seed, and part of their carcass falls on it, it is unclean to you.'),
  ('20547d01-b4b5-598d-a917-849e415f7cec', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 39, 39, '"''If any animal, of which you may eat, dies; he who touches its carcass shall be unclean until the evening.'),
  ('e56d22f8-149b-55b4-ad79-4c1d9cfb3175', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 40, 40, 'He who eats of its carcass shall wash his clothes, and be unclean until the evening. He also who carries its carcass shall wash his clothes, and be unclean until the evening.'),
  ('65536490-4f67-533c-a0ba-1324d91620f8', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 41, 41, '"''Every creeping thing that creeps on the earth is an abomination. It shall not be eaten.'),
  ('e5574c1a-b429-5d50-ab29-dc70ea828d88', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 42, 42, 'Whatever goes on its belly, and whatever goes on all fours, or whatever has many feet, even all creeping things that creep on the earth, them you shall not eat; for they are an abomination.'),
  ('366614d3-4b73-5915-a2b6-1a2a8bcb639f', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 43, 43, 'You shall not make yourselves abominable with any creeping thing that creeps, neither shall you make yourselves unclean with them, that you should be defiled thereby.'),
  ('322ad94f-2745-544b-a5c8-1238237c5b44', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 44, 44, 'For I am Yahweh your God. Sanctify yourselves therefore, and be holy; for I am holy: neither shall you defile yourselves with any kind of creeping thing that moves on the earth.'),
  ('1fc478db-e54c-5d39-aeff-4b802717b1cd', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 45, 45, 'For I am Yahweh who brought you up out of the land of Egypt, to be your God. You shall therefore be holy, for I am holy.'),
  ('faefdf7e-eb18-5af9-adba-812fb2cd9828', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 46, 46, '"''This is the law of the animal, and of the bird, and of every living creature that moves in the waters, and of every creature that creeps on the earth,'),
  ('c487148b-8ef3-5604-a614-4840aef84cda', '2efb1c54-8d5f-5c0d-a381-0628fc303a94', NULL, 47, 47, 'to make a distinction between the unclean and the clean, and between the living thing that may be eaten and the living thing that may not be eaten.''"'),
  ('77b087b5-a205-59d3-ade5-ed361328eac0', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('fbd77552-e600-5eb0-a283-46d35a7caf86', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 2, 2, '"Speak to the children of Israel, saying, ''If a woman conceives, and bears a male child, then she shall be unclean seven days; as in the days of her monthly period she shall be unclean.'),
  ('ef2d3b50-469d-5130-a5b0-00e4a77b2f01', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 3, 3, 'In the eighth day the flesh of his foreskin shall be circumcised.'),
  ('859726b2-1f2b-59fe-acae-65b92e16e7bb', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 4, 4, 'She shall continue in the blood of purification thirty-three days. She shall not touch any holy thing, nor come into the sanctuary, until the days of her purifying are completed.'),
  ('393b3be4-7111-55bf-ad65-4dbbc0676eae', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 5, 5, 'But if she bears a female child, then she shall be unclean two weeks, as in her period; and she shall continue in the blood of purification sixty-six days.'),
  ('142972ee-102a-569f-a60a-4f3240e4235f', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 6, 6, '"''When the days of her purification are completed, for a son, or for a daughter, she shall bring to the priest at the door of the Tent of Meeting, a year old lamb for a burnt offering, and a young pigeon, or a turtledove, for a sin offering:'),
  ('21e1ce5b-8f90-5249-a0b5-600cb5adf762', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 7, 7, 'and he shall offer it before Yahweh, and make atonement for her; and she shall be cleansed from the fountain of her blood. "''This is the law for her who bears, whether a male or a female.'),
  ('98b99800-f734-5749-a3f3-58fd10f83e6a', 'e2491fda-6502-5d61-a3ab-416580a451f7', NULL, 8, 8, 'If she cannot afford a lamb, then she shall take two turtledoves, or two young pigeons; the one for a burnt offering, and the other for a sin offering: and the priest shall make atonement for her, and she shall be clean.''"'),
  ('6acca584-cd41-5789-a971-3790bf85c7ea', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('b64b2cdb-3ca9-52d7-a453-102bda717152', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 2, 2, '"When a man shall have a rising in his body''s skin, or a scab, or a bright spot, and it becomes in the skin of his body the plague of leprosy, then he shall be brought to Aaron the priest, or to one of his sons, the priests:'),
  ('9b8b5461-9021-5a88-aa5f-5b1039ffbf9a', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 3, 3, 'and the priest shall examine the plague in the skin of the body: and if the hair in the plague has turned white, and the appearance of the plague is deeper than the body''s skin, it is the plague of leprosy; and the priest shall examine him, and pronounce him unclean.'),
  ('55364911-34aa-5978-ad9a-10b3f7c6ba6f', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 4, 4, 'If the bright spot is white in the skin of his body, and its appearance isn''t deeper than the skin, and its hair hasn''t turned white, then the priest shall isolate the infected person for seven days.'),
  ('4648fe38-f55e-5c07-a34e-6c385e5c9bfc', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 5, 5, 'The priest shall examine him on the seventh day, and, behold, if in his eyes the plague is arrested, and the plague hasn''t spread in the skin, then the priest shall isolate him for seven more days.'),
  ('b7de5dab-ed0f-5689-a7f0-c3ed9b780821', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 6, 6, 'The priest shall examine him again on the seventh day; and behold, if the plague has faded, and the plague hasn''t spread in the skin, then the priest shall pronounce him clean. It is a scab. He shall wash his clothes, and be clean.'),
  ('aedec8d3-92a4-5851-ad01-ede600ab0b1a', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 7, 7, 'But if the scab spreads on the skin, after he has shown himself to the priest for his cleansing, he shall show himself to the priest again.'),
  ('8d71d46b-1d5d-5047-aa16-76935c3b4535', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 8, 8, 'The priest shall examine him; and behold, if the scab has spread on the skin, then the priest shall pronounce him unclean. It is leprosy.'),
  ('389da23a-a0b7-54f4-a1f1-96bf18c2860d', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 9, 9, '"When the plague of leprosy is in a man, then he shall be brought to the priest;'),
  ('fcbc004e-2b79-5d9f-ab81-15c4ed152273', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 10, 10, 'and the priest shall examine him. Behold, if there is a white rising in the skin, and it has turned the hair white, and there is raw flesh in the rising,'),
  ('5a05d958-05db-52bd-a7a1-c5ba6751a1cb', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 11, 11, 'it is a chronic leprosy in the skin of his body, and the priest shall pronounce him unclean. He shall not isolate him, for he is unclean.'),
  ('c49bd8df-90a6-5693-a15e-e1805794fd25', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 12, 12, '"If the leprosy breaks out all over the skin, and the leprosy covers all the skin of the infected person from his head even to his feet, as far as it appears to the priest;'),
  ('b5d91a6f-4a9f-5e50-a64b-cd104d76f1fd', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 13, 13, 'then the priest shall examine him; and, behold, if the leprosy has covered all his flesh, he shall pronounce him clean of the plague. It has all turned white: he is clean.'),
  ('dd0da900-53cd-584a-a368-982de7e9a172', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 14, 14, 'But whenever raw flesh appears in him, he shall be unclean.'),
  ('a42d7b3d-5a87-5ec6-a18b-274438670df8', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 15, 15, 'The priest shall examine the raw flesh, and pronounce him unclean: the raw flesh is unclean. It is leprosy.'),
  ('2fb6f24b-713d-5a89-a3d3-45693921aac6', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 16, 16, 'Or if the raw flesh turns again, and is changed to white, then he shall come to the priest;'),
  ('6a66d224-36d5-50c8-aa92-920994797e91', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 17, 17, 'and the priest shall examine him; and, behold, if the plague has turned white, then the priest shall pronounce him clean of the plague. He is clean.'),
  ('fde8e200-8caf-5fda-ac43-e738576d7b24', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 18, 18, '"When the body has a boil on its skin, and it has healed,'),
  ('92d54959-d418-5fe4-af38-bbec419340be', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 19, 19, 'and in the place of the boil there is a white rising, or a bright spot, reddish-white, then it shall be shown to the priest;'),
  ('b53ab455-96b6-5ee4-a284-fa08e6a1370a', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 20, 20, 'and the priest shall examine it; and behold, if its appearance is lower than the skin, and its hair has turned white, then the priest shall pronounce him unclean. It is the plague of leprosy. It has broken out in the boil.'),
  ('4e9856c9-e644-59d5-a14f-53df19975909', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 21, 21, 'But if the priest examines it, and behold, there are no white hairs in it, and it isn''t deeper than the skin, but is dim, then the priest shall isolate him seven days.'),
  ('c15a361c-60a3-566e-af23-27919687c2df', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 22, 22, 'If it spreads in the skin, then the priest shall pronounce him unclean. It is a plague.'),
  ('ad1c9496-85b0-57dc-a91b-080ffef5188f', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 23, 23, 'But if the bright spot stays in its place, and hasn''t spread, it is the scar from the boil; and the priest shall pronounce him clean.'),
  ('ce1cf745-82b7-572b-a868-b8e3bbda92a1', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 24, 24, '"Or when the body has a burn from fire on its skin, and the raw flesh of the burn becomes a bright spot, reddish-white, or white,'),
  ('c452d958-a7c0-5415-a114-82893ea36e30', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 25, 25, 'then the priest shall examine it; and behold, if the hair in the bright spot has turned white, and its appearance is deeper than the skin; it is leprosy. It has broken out in the burning, and the priest shall pronounce him unclean. It is the plague of leprosy.'),
  ('abbdaaee-bb1d-5226-a406-31c627ba85cb', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 26, 26, 'But if the priest examines it, and behold, there is no white hair in the bright spot, and it isn''t lower than the skin, but is faded; then the priest shall isolate him seven days.'),
  ('e2d80aa8-1320-57d0-a362-14e3c2df1751', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 27, 27, 'The priest shall examine him on the seventh day. If it has spread in the skin, then the priest shall pronounce him unclean. It is the plague of leprosy.'),
  ('169f50cb-5808-527f-a25b-82aeefd75e85', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 28, 28, 'If the bright spot stays in its place, and hasn''t spread in the skin, but is faded, it is the swelling from the burn, and the priest shall pronounce him clean; for it is the scar from the burn.'),
  ('a345e833-c4a9-543e-a3ab-ec16c4cf01f7', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 29, 29, '"When a man or woman has a plague on the head or on the beard,'),
  ('f1df4699-47a8-5566-a039-90cf48f6642b', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 30, 30, 'then the priest shall examine the plague; and behold, if its appearance is deeper than the skin, and the hair in it is yellow and thin, then the priest shall pronounce him unclean: it is an itch, it is leprosy of the head or of the beard.'),
  ('241e2854-e617-5c40-a67e-ff052bba1caf', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 31, 31, 'If the priest examines the plague of itching, and behold, its appearance isn''t deeper than the skin, and there is no black hair in it, then the priest shall isolate him the person infected with itching seven days.'),
  ('8fd91913-4b24-5531-a236-2c43ef0ff632', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 32, 32, 'On the seventh day the priest shall examine the plague; and behold, if the itch hasn''t spread, and there is no yellow hair in it, and the appearance of the itch isn''t deeper than the skin,'),
  ('256836d3-3920-5882-ab25-1be48e85c76f', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 33, 33, 'then he shall be shaved, but he shall not shave the itch; and the priest shall shut him up who has the itch seven more days.'),
  ('ac5a8bbd-6cea-553c-a23e-a66481cac416', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 34, 34, 'On the seventh day, the priest shall examine the itch; and behold, if the itch hasn''t spread in the skin, and its appearance isn''t deeper than the skin, then the priest shall pronounce him clean. He shall wash his clothes, and be clean.'),
  ('0f0a3b61-3bb7-5888-a5c8-0c30976e15bc', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 35, 35, 'But if the itch spreads in the skin after his cleansing,'),
  ('bc0f4672-7c32-55ab-ab36-e48a3d2c3580', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 36, 36, 'then the priest shall examine him; and behold, if the itch has spread in the skin, the priest shall not look for the yellow hair; he is unclean.'),
  ('f36f2b1a-6da0-51a6-a3a4-973e9ece164d', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 37, 37, 'But if in his eyes the itch is arrested, and black hair has grown in it; the itch is healed, he is clean. The priest shall pronounce him clean.'),
  ('f77efc94-f720-5ed4-a8a8-0f80eebc9769', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 38, 38, '"When a man or a woman has bright spots in the skin of the body, even white bright spots;'),
  ('cfaf0c8b-6b0f-5655-ad08-5466ea3d2db9', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 39, 39, 'then the priest shall examine them; and behold, if the bright spots on the skin of their body are a dull white, it is a harmless rash, it has broken out in the skin; he is clean.'),
  ('b94c214b-812b-5b3e-ac33-3c1fcaa49817', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 40, 40, '"If a man''s hair has fallen from his head, he is bald. He is clean.'),
  ('443baae7-95e4-51ba-a72e-2db2c42bbf44', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 41, 41, 'If his hair has fallen off from the front part of his head, he is forehead bald. He is clean.'),
  ('a69d3bb8-797d-5709-ac88-ce9ed8cf1286', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 42, 42, 'But if there is in the bald head, or the bald forehead, a reddish-white plague; it is leprosy breaking out in his bald head, or his bald forehead.'),
  ('fad58443-a9cf-5c2f-a181-1402002e2d9c', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 43, 43, 'Then the priest shall examine him; and, behold, if the rising of the plague is reddish-white in his bald head, or in his bald forehead, like the appearance of leprosy in the skin of the flesh,'),
  ('0f2df654-f415-56ef-ac6d-4b3847a62be6', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 44, 44, 'he is a leprous man. He is unclean. The priest shall surely pronounce him unclean. His plague is on his head.'),
  ('d2e64607-ffcd-5fed-a691-e16d310a60bd', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 45, 45, '"The leper in whom the plague is shall wear torn clothes, and the hair of his head shall hang loose. He shall cover his upper lip, and shall cry, ''Unclean! Unclean!'''),
  ('7af08e98-9c34-5b48-a57e-d4904001d60c', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 46, 46, 'All the days in which the plague is in him he shall be unclean. He is unclean. He shall dwell alone. Outside of the camp shall be his dwelling.'),
  ('540ce642-c279-5a98-adfc-53a4213f19e9', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 47, 47, '"The garment also that the plague of leprosy is in, whether it is a woolen garment, or a linen garment;'),
  ('8900114e-c81a-5880-a964-9ed2ceac5262', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 48, 48, 'whether it is in warp, or woof; of linen, or of wool; whether in a skin, or in anything made of skin;'),
  ('06e5911f-d2bd-520d-afd4-77c2e3e6d975', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 49, 49, 'if the plague is greenish or reddish in the garment, or in the skin, or in the warp, or in the woof, or in anything made of skin; it is the plague of leprosy, and shall be shown to the priest.'),
  ('bc76b634-06b5-5692-a265-782ee6a9df4e', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 50, 50, 'The priest shall examine the plague, and isolate the plague seven days.'),
  ('6720fd03-40c0-5c8a-aa64-dc42c8c8eaf3', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 51, 51, 'He shall examine the plague on the seventh day. If the plague has spread in the garment, either in the warp, or in the woof, or in the skin, whatever use the skin is used for, the plague is a destructive mildew. It is unclean.'),
  ('83a661a1-e394-5b68-ab30-66c47ce01bad', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 52, 52, 'He shall burn the garment, whether the warp or the woof, in wool or in linen, or anything of skin, in which the plague is: for it is a destructive mildew. It shall be burned in the fire.'),
  ('610ac600-ba97-5d9f-a322-95d182437435', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 53, 53, '"If the priest examines it, and behold, the plague hasn''t spread in the garment, either in the warp, or in the woof, or in anything of skin;'),
  ('039e35a0-c740-567b-a757-6df414d6c831', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 54, 54, 'then the priest shall command that they wash the thing in which the plague is, and he shall isolate it seven more days.'),
  ('01d00435-5a1e-500d-aa41-abb8ca8158c0', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 55, 55, 'Then the priest shall examine it, after the plague is washed; and behold, if the plague hasn''t changed its color, and the plague hasn''t spread, it is unclean; you shall burn it in the fire. It is a mildewed spot, whether the bareness is inside or outside.'),
  ('5bae8ed9-5c98-5c17-a484-fd71738d77d3', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 56, 56, 'If the priest looks, and behold, the plague has faded after it is washed, then he shall tear it out of the garment, or out of the skin, or out of the warp, or out of the woof:'),
  ('f6697411-58a8-5b2e-a929-df101370d073', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 57, 57, 'and if it appears again in the garment, either in the warp, or in the woof, or in anything of skin, it is spreading. You shall burn with fire that in which the plague is.'),
  ('fa09dcf0-63b5-5b06-aca7-f81db2d0a625', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 58, 58, 'The garment, either the warp, or the woof, or whatever thing of skin it is, which you shall wash, if the plague has departed from them, then it shall be washed the second time, and it will be clean."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0bac710a-de5f-5da7-a7bc-683a3bdcb104', 'fdf5352a-69f3-528c-a488-c37d990427a9', NULL, 59, 59, 'This is the law of the plague of mildew in a garment of wool or linen, either in the warp, or the woof, or in anything of skin, to pronounce it clean, or to pronounce it unclean.'),
  ('f46c9f81-c4df-55ad-a95d-9c3eacea65f4', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('03f44f65-478d-5f53-a02b-17d41ea36d9d', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 2, 2, '"This shall be the law of the leper in the day of his cleansing. He shall be brought to the priest,'),
  ('47cb8083-687d-5fc0-afe9-423b41e40c72', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 3, 3, 'and the priest shall go forth out of the camp. The priest shall examine him, and behold, if the plague of leprosy is healed in the leper,'),
  ('ead3008b-280e-5637-a727-b457a6483fae', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 4, 4, 'then the priest shall command them to take for him who is to be cleansed two living clean birds, and cedar wood, and scarlet, and hyssop.'),
  ('723bdf0b-a638-5901-a82a-d4419131b75b', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 5, 5, 'The priest shall command them to kill one of the birds in an earthen vessel over running water.'),
  ('e246cecb-8204-5d0e-a63f-f33a1f01ea35', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 6, 6, 'As for the living bird, he shall take it, and the cedar wood, and the scarlet, and the hyssop, and shall dip them and the living bird in the blood of the bird that was killed over the running water.'),
  ('a0c5d9ac-3ff2-539c-a4a6-96d685b796f6', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 7, 7, 'He shall sprinkle on him who is to be cleansed from the leprosy seven times, and shall pronounce him clean, and shall let the living bird go into the open field.'),
  ('a28ac5e5-6669-5e00-af64-de25fc45ac49', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 8, 8, '"He who is to be cleansed shall wash his clothes, and shave off all his hair, and bathe himself in water; and he shall be clean. After that he shall come into the camp, but shall dwell outside his tent seven days.'),
  ('1f1adb83-6c61-5b96-adeb-a31241335679', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 9, 9, 'It shall be on the seventh day, that he shall shave all his hair off his head and his beard and his eyebrows, even all his hair he shall shave off. He shall wash his clothes, and he shall bathe his body in water, then he shall be clean.'),
  ('054cd4db-2443-5853-a565-6ede95d8823f', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 10, 10, '"On the eighth day he shall take two male lambs without blemish, and one ewe lamb a year old without blemish, and three tenths of an ephah of fine flour for a meal offering, mingled with oil, and one log of oil.'),
  ('832d7a54-c489-51c0-a683-94ef9fe23a0e', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 11, 11, 'The priest who cleanses him shall set the man who is to be cleansed, and those things, before Yahweh, at the door of the Tent of Meeting.'),
  ('e45cc66c-fa1f-5f60-a76b-3c6c7ff35f36', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 12, 12, '"The priest shall take one of the male lambs, and offer him for a trespass offering, with the log of oil, and wave them for a wave offering before Yahweh.'),
  ('6201484d-1349-5ef6-ab4b-0aa8d21e7a0d', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 13, 13, 'He shall kill the male lamb in the place where they kill the sin offering and the burnt offering, in the place of the sanctuary; for as the sin offering is the priest''s, so is the trespass offering. It is most holy.'),
  ('4f46a492-f17b-596d-ad52-83b8fd128ef7', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 14, 14, 'The priest shall take some of the blood of the trespass offering, and the priest shall put it on the tip of the right ear of him who is to be cleansed, and on the thumb of his right hand, and on the big toe of his right foot.'),
  ('f3fa6946-6005-51ab-a044-ec4292b4962a', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 15, 15, 'The priest shall take some of the log of oil, and pour it into the palm of his own left hand.'),
  ('6562fe60-be45-5ed7-a9de-9c76b7453961', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 16, 16, 'The priest shall dip his right finger in the oil that is in his left hand, and shall sprinkle some of the oil with his finger seven times before Yahweh.'),
  ('d71ecb89-055b-5182-a688-1bd2e7ac0619', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 17, 17, 'The priest shall put some of the rest of the oil that is in his hand on the tip of the right ear of him who is to be cleansed, and on the thumb of his right hand, and on the big toe of his right foot, upon the blood of the trespass offering.'),
  ('7bc0febe-d0c4-5054-a380-25512f754adc', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 18, 18, 'The rest of the oil that is in the priest''s hand he shall put on the head of him who is to be cleansed, and the priest shall make atonement for him before Yahweh.'),
  ('3708d807-8669-5902-aeb4-d92f18cd06f4', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 19, 19, '"The priest shall offer the sin offering, and make atonement for him who is to be cleansed because of his uncleanness: and afterward he shall kill the burnt offering;'),
  ('987e7d51-a49b-505e-a669-3e3ae015a04e', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 20, 20, 'and the priest shall offer the burnt offering and the meal offering on the altar. The priest shall make atonement for him, and he shall be clean.'),
  ('3ed8a624-edf6-57a0-a97c-049972770ea0', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 21, 21, '"If he is poor, and can''t afford so much, then he shall take one male lamb for a trespass offering to be waved, to make atonement for him, and one tenth of an ephah of fine flour mingled with oil for a meal offering, and a log of oil;'),
  ('2008059a-0017-569e-a6b8-ee60f64fdba0', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 22, 22, 'and two turtledoves, or two young pigeons, such as he is able to afford; and the one shall be a sin offering, and the other a burnt offering.'),
  ('038e3976-95af-500a-a0d7-d071e636c321', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 23, 23, '"On the eighth day he shall bring them for his cleansing to the priest, to the door of the Tent of Meeting, before Yahweh.'),
  ('17737e49-8bbf-5835-a91c-0da5b2126e5e', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 24, 24, 'The priest shall take the lamb of the trespass offering, and the log of oil, and the priest shall wave them for a wave offering before Yahweh.'),
  ('2c218685-f9af-576b-a6bf-172fe88fdf5e', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 25, 25, 'He shall kill the lamb of the trespass offering. The priest shall take some of the blood of the trespass offering and put it on the tip of the right ear of him who is to be cleansed, and on the thumb of his right hand, and on the big toe of his right foot.'),
  ('966fbab6-7871-54b8-a1ba-70c4f6f09c4a', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 26, 26, 'The priest shall pour some of the oil into the palm of his own left hand;'),
  ('a8fbecfd-1d88-5ba6-ae48-df8d266b27b6', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 27, 27, 'and the priest shall sprinkle with his right finger some of the oil that is in his left hand seven times before Yahweh.'),
  ('3a20127f-5cef-569c-aed6-00be487eabad', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 28, 28, 'Then the priest shall put some of the oil that is in his hand on the tip of the right ear of him who is to be cleansed, and on the thumb of his right hand, and on the big toe of his right foot, on the place of the blood of the trespass offering.'),
  ('b8e4eb68-2ef0-5d32-ae38-c4c59b88aff5', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 29, 29, 'The rest of the oil that is in the priest''s hand he shall put on the head of him who is to be cleansed, to make atonement for him before Yahweh.'),
  ('9237ac8b-35a7-5bfc-a994-658c7670590f', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 30, 30, 'He shall offer one of the turtledoves, or of the young pigeons, such as he is able to afford,'),
  ('56abc94e-8c0f-5704-a23f-801bf217d403', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 31, 31, 'even such as he is able to afford, the one for a sin offering, and the other for a burnt offering, with the meal offering. The priest shall make atonement for him who is to be cleansed before Yahweh."'),
  ('d56dde68-7cd0-537f-a99c-1e367c1fd7f4', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 32, 32, 'This is the law for him in whom is the plague of leprosy, who is not able to afford the sacrifice for his cleansing.'),
  ('dd692c0a-1d4c-5c6a-a7dc-76450b817a9f', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 33, 33, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('f77425fe-09a6-5ec2-a511-8a0fce4e48ad', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 34, 34, '"When you have come into the land of Canaan, which I give to you for a possession, and I put a spreading mildew in a house in the land of your possession,'),
  ('759ace31-32ff-5907-a978-a376c191cb1d', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 35, 35, 'then he who owns the house shall come and tell the priest, saying, ''There seems to me to be some sort of plague in the house.'''),
  ('2c93a793-749b-5764-af18-21c03aa7c9d1', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 36, 36, 'The priest shall command that they empty the house, before the priest goes in to examine the plague, that all that is in the house not be made unclean: and afterward the priest shall go in to inspect the house.'),
  ('fda10143-2319-5025-ab7a-7d86f109d678', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 37, 37, 'He shall examine the plague; and behold, if the plague is in the walls of the house with hollow streaks, greenish or reddish, and it appears to be deeper than the wall;'),
  ('abe1976b-70c8-5981-ae8a-4f3f53e2e587', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 38, 38, 'then the priest shall go out of the house to the door of the house, and shut up the house seven days.'),
  ('9eecb87b-efbd-5e18-aa5d-3fdb0cd04587', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 39, 39, 'The priest shall come again on the seventh day, and look. If the plague has spread in the walls of the house,'),
  ('92a2cac6-254a-5a9f-ac38-f0656604812a', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 40, 40, 'then the priest shall command that they take out the stones in which is the plague, and cast them into an unclean place outside of the city:'),
  ('957a3cf5-6dcf-592a-a04e-54f02dac9385', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 41, 41, 'and he shall cause the inside of the house to be scraped all over, and they shall pour out the mortar, that they scraped off, outside of the city into an unclean place.'),
  ('bb489a65-42a5-59ba-acca-07847ff40518', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 42, 42, 'They shall take other stones, and put them in the place of those stones; and he shall take other mortar, and shall plaster the house.'),
  ('1c4b8a29-fdfa-51a7-a126-0fb5362046f8', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 43, 43, '"If the plague comes again, and breaks out in the house, after he has taken out the stones, and after he has scraped the house, and after it was plastered;'),
  ('bfaf405f-c4c5-5e03-ae36-fb76dca10f49', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 44, 44, 'then the priest shall come in and look; and behold, if the plague has spread in the house, it is a destructive mildew in the house. It is unclean.'),
  ('47344c56-2a53-5184-a596-84d1032ea96a', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 45, 45, 'He shall break down the house, its stones, and its timber, and all the house''s mortar. He shall carry them out of the city into an unclean place.'),
  ('1ddd1047-0d6c-50fa-ad99-bd60c7d300ea', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 46, 46, '"Moreover he who goes into the house while it is shut up shall be unclean until the evening.'),
  ('bbda93e4-b0f5-5c3e-ad06-29488d7b82bd', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 47, 47, 'He who lies down in the house shall wash his clothes; and he who eats in the house shall wash his clothes.'),
  ('46c4904c-b832-5f14-a91e-6282ee50554d', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 48, 48, '"If the priest shall come in, and examine it, and behold, the plague hasn''t spread in the house, after the house was plastered, then the priest shall pronounce the house clean, because the plague is healed.'),
  ('a083091a-7a40-5a32-aabc-fff93d8ccbdc', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 49, 49, 'To cleanse the house he shall take two birds, and cedar wood, and scarlet, and hyssop.'),
  ('9242fc03-9b07-526d-a721-406c6869af5e', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 50, 50, 'He shall kill one of the birds in an earthen vessel over running water.'),
  ('f5bfc947-e506-5d63-a4cc-ce67efc0eeef', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 51, 51, 'He shall take the cedar wood, and the hyssop, and the scarlet, and the living bird, and dip them in the blood of the slain bird, and in the running water, and sprinkle the house seven times.'),
  ('9afdb2d0-f118-53bd-ae1e-5298486f8d6b', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 52, 52, 'He shall cleanse the house with the blood of the bird, and with the running water, with the living bird, with the cedar wood, with the hyssop, and with the scarlet;'),
  ('29a01021-af34-513f-a819-f59f78a58935', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 53, 53, 'but he shall let the living bird go out of the city into the open field. So shall he make atonement for the house; and it shall be clean."'),
  ('a393a3f4-0161-5418-a0e4-64f8ec74934d', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 54, 54, 'This is the law for any plague of leprosy, and for an itch,'),
  ('d5de52c7-7d11-5b93-ab9d-6524899d9a3a', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 55, 55, 'and for the destructive mildew of a garment, and for a house,'),
  ('44ea8773-3ab8-5033-a293-734d9e012729', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 56, 56, 'and for a rising, and for a scab, and for a bright spot;'),
  ('093d3206-a0c2-5c22-a59d-e2c7528b72ea', '1d778767-4a19-5bbd-a9ef-b25ec01e0d6f', NULL, 57, 57, 'to teach when it is unclean, and when it is clean. This is the law of leprosy.'),
  ('1ac66e7c-2926-5ed9-a0ef-1076c824ba65', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('db340c54-7e2f-59c0-a214-bcc7468c6a1b', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 2, 2, '"Speak to the children of Israel, and tell them, ''When any man has a discharge from his body, because of his discharge he is unclean.'),
  ('02c2994b-8eb9-5385-afd7-fb58c8e2bd3e', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 3, 3, 'This shall be his uncleanness in his discharge: whether his body runs with his discharge, or his body has stopped from his discharge, it is his uncleanness.'),
  ('947735b5-93a8-5d36-ad7d-1a1c9cc8ecb9', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 4, 4, '"''Every bed whereon he who has the discharge lies shall be unclean; and everything he sits on shall be unclean.'),
  ('77febe07-6dc8-5a97-a13f-83256697ec27', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 5, 5, 'Whoever touches his bed shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('b28f6c3f-4175-5258-a316-6b957e1468d5', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 6, 6, 'He who sits on anything whereon the man who has the discharge sat shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('8305d9f0-d065-5c7d-a770-bb794960ae2f', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 7, 7, '"''He who touches the body of him who has the discharge shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('812ef109-885e-593a-a9df-da3aaca2b268', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 8, 8, '"''If he who has the discharge spits on him who is clean, then he shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('373d3b1c-02df-52a3-a4cc-9f4918b83205', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 9, 9, '"''Whatever saddle he who has the discharge rides on shall be unclean.'),
  ('30037b30-3104-5672-a070-21a184bbb4e3', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 10, 10, 'Whoever touches anything that was under him shall be unclean until the evening. He who carries those things shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('012f9391-594c-582d-aba4-14c55370af89', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 11, 11, '"''Whoever he who has the discharge touches, without having rinsed his hands in water, he shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('f7b76b13-5cf5-5f4a-a369-e1bcfa7bcfa7', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 12, 12, '"''The earthen vessel, which he who has the discharge touches, shall be broken; and every vessel of wood shall be rinsed in water.'),
  ('5aade87e-0260-53b4-a49e-7a966c9ce3bc', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 13, 13, '"''When he who has a discharge is cleansed of his discharge, then he shall count to himself seven days for his cleansing, and wash his clothes; and he shall bathe his flesh in running water, and shall be clean.'),
  ('bb8eb9b3-643f-5b51-a991-3acf0a2156b1', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 14, 14, '"''On the eighth day he shall take two turtledoves, or two young pigeons, and come before Yahweh to the door of the Tent of Meeting, and give them to the priest:'),
  ('2494d4d6-7a2b-5961-aff5-a21fc490bf8e', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 15, 15, 'and the priest shall offer them, the one for a sin offering, and the other for a burnt offering. The priest shall make atonement for him before Yahweh for his discharge.'),
  ('e16ce275-b8d6-5f86-a241-c0c1f34ea38e', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 16, 16, '"''If any man has an emission of semen, then he shall bathe all his flesh in water, and be unclean until the evening.'),
  ('5c3770b7-dd39-54ae-ab66-60c4830bab1a', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 17, 17, 'Every garment, and every skin, whereon the semen is, shall be washed with water, and be unclean until the evening.'),
  ('2b26e52f-0e13-5019-a25b-f8dc0f109666', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 18, 18, 'If a man lies with a woman and there is an emission of semen, they shall both bathe themselves in water, and be unclean until the evening.'),
  ('fe7831e5-9de6-566b-a12c-1f478396626c', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 19, 19, '"''If a woman has a discharge, and her discharge in her flesh is blood, she shall be in her impurity seven days: and whoever touches her shall be unclean until the evening.'),
  ('5ff660fb-1a93-58d8-a6f6-7c6834fe417d', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 20, 20, '"''Everything that she lies on in her impurity shall be unclean. Everything also that she sits on shall be unclean.'),
  ('41d4393a-ccab-5d11-a425-aa9e703dff26', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 21, 21, 'Whoever touches her bed shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('ba0e05bb-2c99-5a95-a6e9-8ac6bd7b9130', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 22, 22, 'Whoever touches anything that she sits on shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('f1152caa-db0c-57b1-a951-b41f5c6d2368', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 23, 23, 'If it is on the bed, or on anything whereon she sits, when he touches it, he shall be unclean until the evening.'),
  ('2a2fb766-4e75-5c01-abfc-3e741f2f3e34', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 24, 24, '"''If any man lies with her, and her monthly flow is on him, he shall be unclean seven days; and every bed whereon he lies shall be unclean.'),
  ('e0f48c58-c0ce-5b64-ae98-082eac747b4c', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 25, 25, '"''If a woman has a discharge of her blood many days not in the time of her period, or if she has a discharge beyond the time of her period; all the days of the discharge of her uncleanness shall be as in the days of her period: she is unclean.'),
  ('3db13304-5583-5225-a3e2-d1214e2797f8', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 26, 26, 'Every bed whereon she lies all the days of her discharge shall be to her as the bed of her period: and everything whereon she sits shall be unclean, as the uncleanness of her period.'),
  ('97bac02d-4b0a-5cfd-a929-874dcc2050da', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 27, 27, 'Whoever touches these things shall be unclean, and shall wash his clothes, and bathe himself in water, and be unclean until the evening.'),
  ('cc424eeb-18c5-5671-add3-f78566f0c202', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 28, 28, '"''But if she is cleansed of her discharge, then she shall count to herself seven days, and after that she shall be clean.'),
  ('89db9ece-b586-549a-a068-9bb71fd28c19', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 29, 29, 'On the eighth day she shall take two turtledoves, or two young pigeons, and bring them to the priest, to the door of the Tent of Meeting.'),
  ('2b4e0dee-c6b0-5f42-a290-39da9485ea1b', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 30, 30, 'The priest shall offer the one for a sin offering, and the other for a burnt offering; and the priest shall make atonement for her before Yahweh for the uncleanness of her discharge.'),
  ('183346db-8934-5b3c-ae4e-ddfdc5b54421', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 31, 31, '"''Thus you shall separate the children of Israel from their uncleanness, so they will not die in their uncleanness, when they defile my tabernacle that is in their midst.''"'),
  ('704055b3-599e-5863-ac98-6d15a6c922a4', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 32, 32, 'This is the law of him who has a discharge, and of him who has an emission of semen, so that he is unclean thereby;'),
  ('b065f886-d67c-5e2a-ac12-ba6681c3a9cb', '869cace0-a663-5629-a10d-2e5268e04425', NULL, 33, 33, 'and of her who has her period, and of a man or woman who has a discharge, and of him who lies with her who is unclean.'),
  ('56602617-18b1-571e-a1af-2af37abda0aa', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 1, 1, 'Yahweh spoke to Moses, after the death of the two sons of Aaron, when they drew near before Yahweh, and died;'),
  ('56b45764-b28e-511a-a23e-9dbc65cbb93e', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 2, 2, 'and Yahweh said to Moses, "Tell Aaron your brother, not to come at all times into the Most Holy Place within the veil, before the mercy seat which is on the ark; lest he die: for I will appear in the cloud on the mercy seat.'),
  ('e91c1d17-61fa-5e77-af90-3a0e4ed80c87', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 3, 3, '"Herewith shall Aaron come into the sanctuary: with a young bull for a sin offering, and a ram for a burnt offering.'),
  ('11cfb139-bff5-5825-ad5a-6adc1b1a71a0', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 4, 4, 'He shall put on the holy linen coat, and he shall have the linen breeches on his body, and shall put on the linen sash, and he shall be clothed with the linen turban. They are the holy garments. He shall bathe his body in water, and put them on.'),
  ('fbfedf7e-cf93-544e-af91-9dd6da4a77df', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 5, 5, 'He shall take from the congregation of the children of Israel two male goats for a sin offering, and one ram for a burnt offering.'),
  ('2d144ab8-5474-507a-aa13-2e18ca48d385', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 6, 6, '"Aaron shall offer the bull of the sin offering, which is for himself, and make atonement for himself and for his house.'),
  ('54789c17-871d-52e1-a1f8-7b391b2088ef', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 7, 7, 'He shall take the two goats, and set them before Yahweh at the door of the Tent of Meeting.'),
  ('c34b1be6-17d0-5dfc-a8a3-8cca2cfa5ced', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 8, 8, 'Aaron shall cast lots for the two goats; one lot for Yahweh, and the other lot for the scapegoat.'),
  ('1c86fc1b-9fb9-553f-a1b2-142ee83b8b2c', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 9, 9, 'Aaron shall present the goat on which the lot fell for Yahweh, and offer him for a sin offering.'),
  ('102ead6d-a2c7-5684-a4e8-bd34608224a8', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 10, 10, 'But the goat, on which the lot fell for the scapegoat, shall be presented alive before Yahweh, to make atonement for him, to send him away for the scapegoat into the wilderness.'),
  ('eced4349-cbce-5ba5-a229-eb25a1529a6f', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 11, 11, '"Aaron shall present the bull of the sin offering, which is for himself, and shall make atonement for himself and for his house, and shall kill the bull of the sin offering which is for himself.'),
  ('4f2df99b-9fe4-54e1-a270-2587aee73cb7', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 12, 12, 'He shall take a censer full of coals of fire from off the altar before Yahweh, and two handfuls of sweet incense beaten small, and bring it within the veil:'),
  ('21ec541b-465b-503e-a465-3c7b0d4e19eb', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 13, 13, 'and he shall put the incense on the fire before Yahweh, that the cloud of the incense may cover the mercy seat that is on the testimony, so that he will not die.'),
  ('50bfbe3b-6761-5215-ac4c-b2bd0480cda9', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 14, 14, 'He shall take some of the blood of the bull, and sprinkle it with his finger on the mercy seat on the east; and before the mercy seat he shall sprinkle some of the blood with his finger seven times.'),
  ('3151fde8-a385-58cc-a076-690940421ef7', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 15, 15, '"Then he shall kill the goat of the sin offering, that is for the people, and bring his blood within the veil, and do with his blood as he did with the blood of the bull, and sprinkle it on the mercy seat, and before the mercy seat:'),
  ('88773645-4ec6-53dc-ac75-98204c6ea013', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 16, 16, 'and he shall make atonement for the Holy Place, because of the uncleanness of the children of Israel, and because of their transgressions, even all their sins; and so he shall do for the Tent of Meeting, that dwells with them in the midst of their uncleanness.'),
  ('fa9e08c1-9316-53be-a858-95ed6774de17', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 17, 17, 'No one shall be in the Tent of Meeting when he enters to make atonement in the Holy Place, until he comes out, and has made atonement for himself and for his household, and for all the assembly of Israel.'),
  ('bf26cc71-d98b-520c-ad08-4924321c52bf', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 18, 18, '"He shall go out to the altar that is before Yahweh and make atonement for it, and shall take some of the bull''s blood, and some of the goat''s blood, and put it around on the horns of the altar.'),
  ('340c6666-1a4e-5396-a5b2-36a3350b74a0', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 19, 19, 'He shall sprinkle some of the blood on it with his finger seven times, and cleanse it, and make it holy from the uncleanness of the children of Israel.'),
  ('8703f2f0-97ce-5924-a1f4-653d741407ec', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 20, 20, '"When he has made an end of atoning for the Holy Place, the Tent of Meeting, and the altar, he shall present the live goat.'),
  ('feafbef6-0d06-5ae7-a4d8-a67110e7ebb1', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 21, 21, 'Aaron shall lay both his hands on the head of the live goat, and confess over him all the iniquities of the children of Israel, and all their transgressions, even all their sins; and he shall put them on the head of the goat, and shall send him away into the wilderness by the hand of a man who is in readiness.'),
  ('c877cea8-6233-5677-ae76-3ce4507b3ea2', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 22, 22, 'The goat shall carry all their iniquities on himself to a solitary land, and he shall let the goat go in the wilderness.'),
  ('0933e996-d92a-552b-a23a-40e1640a9b3b', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 23, 23, '"Aaron shall come into the Tent of Meeting, and shall take off the linen garments, which he put on when he went into the Holy Place, and shall leave them there.'),
  ('8728f86e-4d98-55a3-a8c0-51a1f0bca890', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 24, 24, 'Then he shall bathe himself in water in a holy place, and put on his garments, and come out and offer his burnt offering and the burnt offering of the people, and make atonement for himself and for the people.'),
  ('8d275b73-6433-53f3-a399-148425ebbc30', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 25, 25, 'The fat of the sin offering he shall burn on the altar.'),
  ('8b4d2fb0-5535-5478-a6be-e4338f1b3b2a', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 26, 26, '"He who lets the goat go for the scapegoat shall wash his clothes, and bathe his flesh in water, and afterward he shall come into the camp.'),
  ('86f9a91a-3166-5286-a05a-b88275ed2445', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 27, 27, 'The bull for the sin offering, and the goat for the sin offering, whose blood was brought in to make atonement in the Holy Place, shall be carried forth outside the camp; and they shall burn their skins, their flesh, and their dung with fire.'),
  ('36d86d37-d814-529d-aaa9-270b94ecdd52', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 28, 28, 'He who burns them shall wash his clothes, and bathe his flesh in water, and afterward he shall come into the camp.'),
  ('5fb3c2df-c98b-5672-a9a0-1641166d5966', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 29, 29, '"It shall be a statute to you forever: in the seventh month, on the tenth day of the month, you shall afflict your souls, and shall do no kind of work, the native-born, or the stranger who lives as a foreigner among you:'),
  ('ec74da98-9b34-56b0-ab16-b69d7055a969', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 30, 30, 'for on this day shall atonement be made for you, to cleanse you; from all your sins you shall be clean before Yahweh.'),
  ('54b7779a-1472-57d4-a3a5-01e265fac9e0', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 31, 31, 'It is a Sabbath of solemn rest to you, and you shall afflict your souls; it is a statute forever.'),
  ('b467ed32-584a-5e49-a9f0-3dff825715f8', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 32, 32, 'The priest, who is anointed and who is consecrated to be priest in his father''s place, shall make the atonement, and shall put on the linen garments, even the holy garments.'),
  ('099f2a3f-cecc-5bcd-a110-2f63ad380d73', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 33, 33, 'Then he shall make atonement for the Holy Sanctuary; and he shall make atonement for the Tent of Meeting and for the altar; and he shall make atonement for the priests and for all the people of the assembly.'),
  ('841b7833-9da7-5893-a0d7-aa7b2980c7b6', '9a2af802-4bca-5b91-a933-b139a230b11f', NULL, 34, 34, '"This shall be an everlasting statute for you, to make atonement for the children of Israel once in the year because of all their sins." It was done as Yahweh commanded Moses.'),
  ('37506f3e-cdcf-5342-a6ca-f7ac0d9e7992', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('ff49cbaa-04be-5186-ac8a-75c90994c22a', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 2, 2, '"Speak to Aaron, and to his sons, and to all the children of Israel, and say to them: ''This is the thing which Yahweh has commanded,'),
  ('3af94a7c-eaca-5419-a9b7-28414a876e9d', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 3, 3, 'Whatever man there is of the house of Israel, who kills a bull, or lamb, or goat, in the camp, or who kills it outside the camp,'),
  ('2328e291-2b50-55ee-a655-80e775125daf', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 4, 4, 'and hasn''t brought it to the door of the Tent of Meeting, to offer it as an offering to Yahweh before the tabernacle of Yahweh: blood shall be imputed to that man. He has shed blood; and that man shall be cut off from among his people.'),
  ('df5c9c68-6d96-56ff-a2a0-b1e5352c2907', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 5, 5, 'This is to the end that the children of Israel may bring their sacrifices, which they sacrifice in the open field, that they may bring them to Yahweh, to the door of the Tent of Meeting, to the priest, and sacrifice them for sacrifices of peace offerings to Yahweh.'),
  ('09680b65-7a56-5893-a756-c0e03b09d814', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 6, 6, 'The priest shall sprinkle the blood on the altar of Yahweh at the door of the Tent of Meeting, and burn the fat for a pleasant aroma to Yahweh.'),
  ('f748b515-62c2-5769-aec4-5812f8650fd3', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 7, 7, 'They shall no more sacrifice their sacrifices to the goat idols, after which they play the prostitute. This shall be a statute forever to them throughout their generations.'''),
  ('4f5a626e-c088-56bb-adf3-4298cd706448', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 8, 8, '"You shall say to them, ''Any man there is of the house of Israel, or of the strangers who live as foreigners among them, who offers a burnt offering or sacrifice,'),
  ('9aee00e9-7afe-53eb-a434-fafded4ade30', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 9, 9, 'and doesn''t bring it to the door of the Tent of Meeting, to sacrifice it to Yahweh; that man shall be cut off from his people.'),
  ('3b1b630a-5157-58dc-ab7b-eb97c1944049', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 10, 10, '"''Any man of the house of Israel, or of the strangers who live as foreigners among them, who eats any kind of blood, I will set my face against that soul who eats blood, and will cut him off from among his people.'),
  ('b6e835c4-f595-5faf-acb8-8a8c9d4ec436', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 11, 11, 'For the life of the flesh is in the blood; and I have given it to you on the altar to make atonement for your souls: for it is the blood that makes atonement by reason of the life.'),
  ('ae936f87-465a-5ad1-a641-2c4f1be35d6e', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 12, 12, 'Therefore I have said to the children of Israel, "No person among you shall eat blood, neither shall any stranger who lives as a foreigner among you eat blood."'),
  ('0bc024a6-7ca9-530f-a248-c0df3a9c7b0f', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 13, 13, '"''Whatever man there is of the children of Israel, or of the strangers who live as foreigners among them, who takes in hunting any animal or bird that may be eaten; he shall pour out its blood, and cover it with dust.'),
  ('d52cc1bc-2bb6-5fb1-a574-5daf2354b947', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 14, 14, 'For as to the life of all flesh, its blood is with its life: therefore I said to the children of Israel, "You shall not eat the blood of any kind of flesh; for the life of all flesh is its blood. Whoever eats it shall be cut off."'),
  ('825d0eaa-c164-50c0-a5f2-d24401bab0d9', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 15, 15, '"''Every person that eats what dies of itself, or that which is torn by animals, whether he is native-born or a foreigner, he shall wash his clothes, and bathe himself in water, and be unclean until the evening: then he shall be clean.'),
  ('a5809a84-1c08-5cf2-ae63-dc973a14662a', 'f70ecc34-025d-5a3a-a525-ce8c5eb58834', NULL, 16, 16, 'But if he doesn''t wash them, or bathe his flesh, then he shall bear his iniquity.''"'),
  ('7d3ae307-424f-57f5-adaa-21ac1bbd0b3a', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 1, 1, 'Yahweh said to Moses,'),
  ('dece4293-49e6-5abf-a6cc-4e0e2fb8d115', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 2, 2, '"Speak to the children of Israel, and say to them, ''I am Yahweh your God.'),
  ('6f4a79c6-b795-5900-a48a-0d15bfc8057d', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 3, 3, 'You shall not do as they do in the land of Egypt, where you lived: and you shall not do as they do in the land of Canaan, where I am bringing you; neither shall you walk in their statutes.'),
  ('84201f56-165a-5b92-ac00-32fbcd01c163', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 4, 4, 'You shall do my ordinances, and you shall keep my statutes, and walk in them: I am Yahweh your God.'),
  ('3848c7f1-5742-59a5-ae79-e880d58af377', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 5, 5, 'You shall therefore keep my statutes and my ordinances; which if a man does, he shall live in them: I am Yahweh.'),
  ('b38b4caa-8fef-5d37-a3aa-17df90a43cd7', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 6, 6, '"''None of you shall approach anyone who are his close relatives, to uncover their nakedness: I am Yahweh.'),
  ('30116972-f683-5763-a913-b818b5e8e320', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 7, 7, '"''You shall not uncover the nakedness of your father, nor the nakedness of your mother: she is your mother. You shall not uncover her nakedness.'),
  ('5271fe2d-b546-58b8-a2bb-5b1eaa5e3f15', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 8, 8, '"''You shall not uncover the nakedness of your father''s wife: it is your father''s nakedness.'),
  ('6100e5e0-5f0c-5592-adc3-2980d55e2ce0', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 9, 9, '"''You shall not uncover the nakedness of your sister, the daughter of your father, or the daughter of your mother, whether born at home, or born abroad.'),
  ('227c5987-d02a-5907-a6c7-58ea18973890', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 10, 10, '"''You shall not uncover the nakedness of your son''s daughter, or of your daughter''s daughter, even their nakedness: for theirs is your own nakedness.'),
  ('fc683484-191c-589f-afb4-ac3e96fd7856', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 11, 11, '"''You shall not uncover the nakedness of your father''s wife''s daughter, conceived by your father, since she is your sister.'),
  ('9b8bef62-cba3-583f-a69f-8d509135d158', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 12, 12, '"''You shall not uncover the nakedness of your father''s sister: she is your father''s near kinswoman.'),
  ('4a9aaa85-81ed-5729-a11a-778697000d47', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 13, 13, '"''You shall not uncover the nakedness of your mother''s sister: for she is your mother''s near kinswoman.'),
  ('b23d3c2d-5a25-5b07-a60b-858deca9e47d', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 14, 14, '"''You shall not uncover the nakedness of your father''s brother, you shall not approach his wife: she is your aunt.'),
  ('44822f41-806d-505c-a9d1-e1d4b7206e09', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 15, 15, '"''You shall not uncover the nakedness of your daughter-in-law: she is your son''s wife. You shall not uncover her nakedness.'),
  ('462809e9-7378-5a0e-aee4-1032906ca3c6', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 16, 16, '"''You shall not uncover the nakedness of your brother''s wife: it is your brother''s nakedness.'),
  ('2d9ecf4c-7e56-5753-afe6-fedbd9113744', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 17, 17, '"''You shall not uncover the nakedness of a woman and her daughter. You shall not take her son''s daughter, or her daughter''s daughter, to uncover her nakedness; they are near kinswomen: it is wickedness.'),
  ('81eab903-0b65-5930-a8c7-992dca892123', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 18, 18, '"''You shall not take a wife to her sister, to be a rival, to uncover her nakedness, while her sister is yet alive.'),
  ('0e6a608c-6ff8-54a7-a647-f96c0051132b', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 19, 19, '"''You shall not approach a woman to uncover her nakedness, as long as she is impure by her uncleanness.'),
  ('7bb72eea-9454-57fa-a4ca-1e2ca1ccae5a', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 20, 20, '"''You shall not lie carnally with your neighbor''s wife, and defile yourself with her.'),
  ('bd2fd095-2a20-56e5-a265-5e31372d2510', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 21, 21, '"''You shall not give any of your children to sacrifice to Molech; neither shall you profane the name of your God: I am Yahweh.'),
  ('6aea9894-f4b2-535b-a76e-c072bcb55505', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 22, 22, '"''You shall not lie with a man, as with a woman. That is detestable.'),
  ('bbe9b394-df66-5370-a473-4d6118d80dac', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 23, 23, '"''You shall not lie with any animal to defile yourself with it; neither shall any woman give herself to an animal, to lie down with it: it is a perversion.'),
  ('57219727-9f27-59d3-abf5-5803baf80842', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 24, 24, '"''Don''t defile yourselves in any of these things: for in all these the nations which I am casting out before you were defiled.'),
  ('8fa87597-8d0c-5a90-af18-f6ba5be7d994', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 25, 25, 'The land was defiled: therefore I punished its iniquity, and the land vomited out her inhabitants.'),
  ('11687be8-8fd8-5005-af10-c84e30f2dcc4', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 26, 26, 'You therefore shall keep my statutes and my ordinances, and shall not do any of these abominations; neither the native-born, nor the stranger who lives as a foreigner among you;'),
  ('48021b64-4a2e-563c-ac13-2dbf1a9584bb', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 27, 27, '(for all these abominations have the men of the land done, that were before you, and the land became defiled);'),
  ('fd4b3ba6-2b51-5c40-a4c9-d1af8e8bf9b3', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 28, 28, 'that the land not vomit you out also, when you defile it, as it vomited out the nation that was before you.'),
  ('3556ca6f-0588-57c8-ac1b-e8756ff13f64', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 29, 29, '"''For whoever shall do any of these abominations, even the souls that do them shall be cut off from among their people.'),
  ('fc15ecae-deab-5d20-a4b7-e69a38cbf4bd', '4a89cbdc-f599-5f2e-ac05-08fde4d76975', NULL, 30, 30, 'Therefore you shall keep my requirements, that you do not practice any of these abominable customs, which were practiced before you, and that you do not defile yourselves with them: I am Yahweh your God.''"'),
  ('0b9f5c33-e2c5-5f9e-a7aa-443d741b2da4', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('6f35614a-8cef-55ec-a54f-28dbe10971d8', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 2, 2, '"Speak to all the congregation of the children of Israel, and tell them, ''You shall be holy; for I Yahweh your God am holy.'),
  ('1e313e67-2233-56b2-a4d7-9b2dd4cb1e0b', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 3, 3, '"''Each one of you shall respect his mother and his father. You shall keep my Sabbaths. I am Yahweh your God.'),
  ('4b209b26-66d3-51d7-a96f-b6df7be763bd', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 4, 4, '"''Don''t turn to idols, nor make molten gods for yourselves. I am Yahweh your God.'),
  ('de3ac916-a522-5ef8-a6b6-72b34c2eb845', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 5, 5, '"''When you offer a sacrifice of peace offerings to Yahweh, you shall offer it so that you may be accepted.'),
  ('9ebb984d-d950-533c-afa7-6a1655d2db24', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 6, 6, 'It shall be eaten the same day you offer it, and on the next day: and if anything remains until the third day, it shall be burned with fire.'),
  ('885c70d0-674f-5bba-a79d-2fc9edd1f9c7', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 7, 7, 'If it is eaten at all on the third day, it is an abomination. It will not be accepted;'),
  ('6088085e-048a-524a-afaa-c93cf609970e', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 8, 8, 'but everyone who eats it shall bear his iniquity, because he has profaned the holy thing of Yahweh, and that soul shall be cut off from his people.'),
  ('a12831ce-b784-5bc2-a3a2-79dabc4bc8d4', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 9, 9, '"''When you reap the harvest of your land, you shall not wholly reap the corners of your field, neither shall you gather the gleanings of your harvest.'),
  ('758b9bf5-052d-5ca2-a269-cb87f7852c6a', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 10, 10, 'You shall not glean your vineyard, neither shall you gather the fallen grapes of your vineyard; you shall leave them for the poor and for the foreigner. I am Yahweh your God.'),
  ('ac6a3e11-aeb8-5a54-a52c-e10901be1464', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 11, 11, '"''You shall not steal. "''You shall not lie. "''You shall not deceive one another.'),
  ('5d5886b3-364a-558e-acdc-0ff6fb5f0c66', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 12, 12, '"''You shall not swear by my name falsely, and profane the name of your God. I am Yahweh.'),
  ('09a39c87-a17b-553c-a621-8564771b5657', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 13, 13, '"''You shall not oppress your neighbor, nor rob him. "''The wages of a hired servant shall not remain with you all night until the morning.'),
  ('3927b62d-be11-5bb1-a6e6-ae74a73ab8d3', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 14, 14, '"''You shall not curse the deaf, nor put a stumbling block before the blind; but you shall fear your God. I am Yahweh.'),
  ('e1bd1a93-0a9a-5201-aa89-076bfdb290b7', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 15, 15, '"''You shall do no injustice in judgment: you shall not be partial to the poor, nor show favoritism to the great; but you shall judge your neighbor in righteousness.'),
  ('4b1098a7-a2e8-5aee-a055-6b2be58e7f5e', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 16, 16, '"''You shall not go up and down as a slanderer among your people. "''You shall not endanger the life of your neighbor. I am Yahweh.'),
  ('e1b926a7-44aa-50b1-a553-4e87c3f86790', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 17, 17, '"''You shall not hate your brother in your heart. You shall surely rebuke your neighbor, and not bear sin because of him.'),
  ('6af994fb-d72f-5301-a12f-fff61d490693', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 18, 18, '"''You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbor as yourself. I am Yahweh.'),
  ('e7ed8a2d-49ee-5f5b-a071-ac0331978116', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 19, 19, '"''You shall keep my statutes. "''You shall not crossbreed different kinds of animals. "''you shall not sow your field with two kinds of seed; "''neither shall there come upon on you a garment made of two kinds of material.'),
  ('94313a63-29e2-5e42-a9d3-d68e6423e72b', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 20, 20, '"''If a man lies carnally with a woman who is a slave girl, pledged to be married to another man, and not ransomed, or given her freedom; they shall be punished. They shall not be put to death, because she was not free.'),
  ('91270b60-856d-51a9-a1e5-b81a95224e6d', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 21, 21, 'He shall bring his trespass offering to Yahweh, to the door of the Tent of Meeting, even a ram for a trespass offering.'),
  ('9a959dea-21b0-5f20-a116-2e4d2ad8641b', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 22, 22, 'The priest shall make atonement for him with the ram of the trespass offering before Yahweh for his sin which he has committed: and the sin which he has committed shall be forgiven him.'),
  ('787e5ada-2377-5b14-a76a-c5352dae5e59', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 23, 23, '"''When you come into the land, and have planted all kinds of trees for food, then you shall count their fruit as forbidden. Three years shall they be forbidden to you. It shall not be eaten.'),
  ('866b1677-6c73-5c9c-a996-b1c7d41ff03d', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 24, 24, 'But in the fourth year all its fruit shall be holy, for giving praise to Yahweh.'),
  ('0a1c6415-93c5-5e60-a201-ab4593c8669a', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 25, 25, 'In the fifth year you shall eat its fruit, that it may yield its increase to you. I am Yahweh your God.'),
  ('185ba468-9e14-58db-acec-5fab07e665e0', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 26, 26, '"''You shall not eat any meat with the blood still in it; neither shall you use enchantments, nor practice sorcery.'),
  ('9f726cc8-c163-5939-a2b6-8c9e25e143f3', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 27, 27, '"''You shall not cut the hair on the sides of your heads, neither shall you clip off the edge of your beard.'),
  ('bb94adb4-e02f-5971-a91c-348e0d5c4c1b', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 28, 28, '"''You shall not make any cuttings in your flesh for the dead, nor tattoo any marks on you. I am Yahweh.'),
  ('91582158-5b8f-53c7-af61-96c419f97083', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 29, 29, '"''Don''t profane your daughter, to make her a prostitute; lest the land fall to prostitution, and the land become full of wickedness.'),
  ('6e87c754-43d1-5a0f-a697-1ae68a79ada0', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 30, 30, '"''You shall keep my Sabbaths, and reverence my sanctuary; I am Yahweh.'),
  ('8300cec8-fab6-5ec8-aa74-f8200821b1fa', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 31, 31, '"''Don''t turn to those who are mediums, nor to the wizards. Don''t seek them out, to be defiled by them. I am Yahweh your God.'),
  ('781024a2-2641-5f89-a182-7597e02b1eec', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 32, 32, '"''You shall rise up before the gray head, and honor the face of an old man, and you shall fear your God. I am Yahweh.'),
  ('28d620ce-c3a2-57fc-ad93-f1d25d65c0a9', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 33, 33, '"''If a stranger lives as a foreigner with you in your land, you shall not do him wrong.'),
  ('e4c906e8-9933-54b8-a7ba-58b1acf9a636', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 34, 34, 'The stranger who lives as a foreigner with you shall be to you as the native-born among you, and you shall love him as yourself; for you lived as foreigners in the land of Egypt. I am Yahweh your God.'),
  ('d222c6f1-9062-5b16-a696-4cc7b85decb2', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 35, 35, '"''You shall do no unrighteousness in judgment, in measures of length, of weight, or of quantity.'),
  ('bb8e0542-6772-57b0-ae88-75d3b4c1ea47', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 36, 36, 'You shall have just balances, just weights, a just ephah, and a just hin. I am Yahweh your God, who brought you out of the land of Egypt.'),
  ('128618a3-7fdd-58b3-aba9-d672543130a0', 'afbd8c14-f099-5309-a35f-11792b8e8b1d', NULL, 37, 37, '"''You shall observe all my statutes, and all my ordinances, and do them. I am Yahweh.''"'),
  ('397fb46a-5fff-599e-ae86-91a435c68ff2', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('06c221ab-d5bb-5995-adb0-c30a987994f7', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 2, 2, '"Moreover, you shall tell the children of Israel, ''Anyone of the children of Israel, or of the strangers who live as foreigners in Israel, who gives any of his seed to Molech; he shall surely be put to death. The people of the land shall stone him with stones.'),
  ('bfe0590d-d03d-54f4-aa49-d288b46d15be', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 3, 3, 'I also will set my face against that person, and will cut him off from among his people because he has given of his seed to Molech, to defile my sanctuary, and to profane my holy name.'),
  ('15543caf-7779-5a0d-a8ee-eb92e1c25f38', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 4, 4, 'If the people of the land all hide their eyes from that person, when he gives of his seed to Molech, and don''t put him to death;'),
  ('00dc2224-4de4-55b4-ac6b-7be5533717e1', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 5, 5, 'then I will set my face against that man, and against his family, and will cut him off, and all who play the prostitute after him, to play the prostitute with Molech, from among their people.'),
  ('ac4fd4ed-24a7-5c52-aba2-b91054aa4aa7', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 6, 6, '"''The person that turns to those who are mediums, and to the wizards, to play the prostitute after them, I will even set my face against that person, and will cut him off from among his people.'),
  ('71ede6e1-df4a-5761-a1bc-e7745c199860', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 7, 7, '"''Sanctify yourselves therefore, and be holy; for I am Yahweh your God.'),
  ('d2e802bd-69fe-5a0f-af7c-c8d7ece02981', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 8, 8, 'You shall keep my statutes, and do them. I am Yahweh who sanctifies you.'),
  ('25304bc5-9668-5e2e-adfd-1c834c6ad588', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 9, 9, '"''For everyone who curses his father or his mother shall surely be put to death: he has cursed his father or his mother; his blood shall be upon him.'),
  ('a1c67a63-b2aa-59c7-a632-890ee7baaed4', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 10, 10, '"''The man who commits adultery with another man''s wife, even he who commits adultery with his neighbor''s wife, the adulterer and the adulteress shall surely be put to death.'),
  ('e4f2d15a-f2f2-5e0b-a16b-0da6e3c358e3', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 11, 11, '"''The man who lies with his father''s wife has uncovered his father''s nakedness: both of them shall surely be put to death; their blood shall be upon them.'),
  ('77b7f260-1a83-53e1-ae6c-4732142ff3be', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 12, 12, '"''If a man lies with his daughter-in-law, both of them shall surely be put to death: they have committed a perversion; their blood shall be upon them.'),
  ('52f853e7-124d-574b-ad75-376e7c7b4149', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 13, 13, '"''If a man lies with a male, as with a woman, both of them have committed an abomination: they shall surely be put to death; their blood shall be upon them.'),
  ('4aeb37c2-511f-5ea3-a1f5-916d448001c2', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 14, 14, '"''If a man takes a wife and her mother, it is wickedness: they shall be burned with fire, both he and they; that there may be no wickedness among you.'),
  ('c31aaffa-992d-536e-ad6f-f8b81b409123', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 15, 15, '"''If a man lies with an animal, he shall surely be put to death; and you shall kill the animal.'),
  ('489d85b2-aa50-5fc0-a9b1-254175334f3f', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 16, 16, '"''If a woman approaches any animal, and lies down with it, you shall kill the woman, and the animal: they shall surely be put to death; their blood shall be upon them.'),
  ('12ad58f6-6dfa-5dbc-a2fd-959e101f555f', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 17, 17, '"''If a man takes his sister, his father''s daughter, or his mother''s daughter, and sees her nakedness, and she sees his nakedness; it is a shameful thing; and they shall be cut off in the sight of the children of their people: he has uncovered his sister''s nakedness; he shall bear his iniquity.'),
  ('2f718f39-13b4-5178-ad63-bedbae9529ce', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 18, 18, '"''If a man lies with a woman having her monthly period, and uncovers her nakedness; he has made naked her fountain, and she has uncovered the fountain of her blood: and both of them shall be cut off from among their people.'),
  ('f90b4a59-76f8-5f7f-accd-e5b157d74416', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 19, 19, '"''You shall not uncover the nakedness of your mother''s sister, nor of your father''s sister; for he has made naked his close relative: they shall bear their iniquity.'),
  ('d3e778f4-56f3-5653-acb6-9ef16c280749', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 20, 20, 'If a man lies with his uncle''s wife, he has uncovered his uncle''s nakedness: they shall bear their sin; they shall die childless.'),
  ('ea94cea2-5564-5b2f-a30b-5d86dde245d9', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 21, 21, '"''If a man takes his brother''s wife, it is an impurity: he has uncovered his brother''s nakedness; they shall be childless.'),
  ('7116f9ff-d999-5bae-a0c2-7682967c596f', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 22, 22, '"''You shall therefore keep all my statutes, and all my ordinances, and do them; that the land, where I am bringing you to dwell, may not vomit you out.'),
  ('a2f39c69-b12e-54be-a6d2-add32b21081d', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 23, 23, 'You shall not walk in the customs of the nation, which I am casting out before you: for they did all these things, and therefore I abhorred them.'),
  ('29c2fc9b-8f2f-53fa-a106-d8895bfb2bc8', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 24, 24, 'But I have said to you, "You shall inherit their land, and I will give it to you to possess it, a land flowing with milk and honey." I am Yahweh your God, who has separated you from the peoples.'),
  ('9c438196-5651-5288-a67f-31d86197b229', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 25, 25, '"''You shall therefore make a distinction between the clean animal and the unclean, and between the unclean fowl and the clean: and you shall not make yourselves abominable by animal, or by bird, or by anything with which the ground teems, which I have separated from you as unclean for you.'),
  ('7da5adb8-5732-559d-a9c9-28cfe9105d65', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 26, 26, 'You shall be holy to me: for I, Yahweh, am holy, and have set you apart from the peoples, that you should be mine.'),
  ('af4b1517-10fd-5e72-a422-d3b3d1e02238', 'c8635e1f-dd1c-5e9d-a475-ef5514c24482', NULL, 27, 27, '"''A man or a woman that is a medium, or is a wizard, shall surely be put to death: they shall stone them with stones; their blood shall be upon them.''"'),
  ('f9a0b8bb-3bce-5624-ac45-a06f246b0e98', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 1, 1, 'Yahweh said to Moses, "Speak to the priests, the sons of Aaron, and say to them, ''A priest shall not defile himself for the dead among his people;'),
  ('c537b62b-562e-588d-a02a-1f3f733a6cb0', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 2, 2, 'except for his relatives that are near to him: for his mother, for his father, for his son, for his daughter, for his brother,'),
  ('88ee6fcf-cce4-5206-a3fb-04dd5abee2c9', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 3, 3, 'and for his virgin sister who is near to him, who has had no husband; for her he may defile himself.'),
  ('dc7a6b69-6805-51c1-ad6f-e7f3215bda20', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 4, 4, 'He shall not defile himself, being a chief man among his people, to profane himself.'),
  ('10a540db-a89a-5854-acb7-1d1dc45a1f00', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 5, 5, '"''They shall not shave their heads, neither shall they shave off the corners of their beards, nor make any cuttings in their flesh.'),
  ('4f37e703-e957-55d8-aceb-dc905ecb826a', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 6, 6, 'They shall be holy to their God, and not profane the name of their God; for they offer the offerings of Yahweh made by fire, the bread of their God; therefore they shall be holy.'),
  ('3595f473-e448-520b-a033-868c25e653cd', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 7, 7, '"''They shall not marry a woman who is a prostitute, or profane; neither shall they marry a woman divorced from her husband: for he is holy to his God.'),
  ('aeddcf34-86d2-5aaa-af98-f7fcd3b7182a', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 8, 8, 'You shall sanctify him therefore; for he offers the bread of your God: he shall be holy to you: for I Yahweh, who sanctify you, am holy.'),
  ('309745bd-7f80-5512-a0d2-bd18bbeb950a', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 9, 9, '"''The daughter of any priest, if she profanes herself by playing the prostitute, she profanes her father: she shall be burned with fire.'),
  ('be190ba3-7295-537a-ae05-d794d4366fcf', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 10, 10, '"''He who is the high priest among his brothers, upon whose head the anointing oil is poured, and that is consecrated to put on the garments, shall not let the hair of his head hang loose, nor tear his clothes;'),
  ('5455409d-4ad4-50b2-a70e-49e65317f528', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 11, 11, 'neither shall he go in to any dead body, nor defile himself for his father, or for his mother;'),
  ('e018e4fd-f231-58a8-aabc-7d0bedcbe0c3', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 12, 12, 'neither shall he go out of the sanctuary, nor profane the sanctuary of his God; for the crown of the anointing oil of his God is upon him. I am Yahweh.'),
  ('52da9c82-456b-5663-a4a9-78b03bfba5e5', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 13, 13, '"''He shall take a wife in her virginity.'),
  ('67cb1c77-a42c-537c-a5aa-0f3ca2763e1c', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 14, 14, 'A widow, or one divorced, or a woman who has been defiled, or a prostitute, these he shall not marry: but a virgin of his own people shall he take as a wife.'),
  ('879a462d-d136-55a4-a2cf-76395528ae66', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 15, 15, 'He shall not profane his seed among his people: for I am Yahweh who sanctifies him.''"')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('798787c0-a927-5b3c-ad32-b53bd879a367', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 16, 16, 'Yahweh spoke to Moses, saying,'),
  ('4dd6f000-288c-52b4-a103-4bdeb69f0ea6', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 17, 17, '"Say to Aaron, ''None of your seed throughout their generations who has a blemish, may approach to offer the bread of his God.'),
  ('a7f2f500-711c-5586-a3ef-3c64c0e3daf2', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 18, 18, 'For whatever man he is that has a blemish, he shall not draw near: a blind man, or a lame, or he who has a flat nose, or any deformity,'),
  ('e13a54b4-f27f-5562-a6c7-f143e7e036e2', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 19, 19, 'or a man who has an injured foot, or an injured hand,'),
  ('518251b2-89b7-5cb7-a8e1-aa2f386fa241', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 20, 20, 'or hunchbacked, or a dwarf, or one who has a defect in his eye, or an itching disease, or scabs, or who has damaged testicles;'),
  ('23f37240-8ddd-5af8-a75d-1a7b3ff3fed1', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 21, 21, 'no man of the seed of Aaron the priest who has a blemish, shall come near to offer the offerings of Yahweh made by fire. Since he has a blemish, he shall not come near to offer the bread of his God.'),
  ('96121ac8-efe4-5902-a81e-fb01a72143d7', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 22, 22, 'He shall eat the bread of his God, both of the most holy, and of the holy.'),
  ('df69ae11-dbf5-5119-a3c6-ec51467f92b1', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 23, 23, 'He shall not come near to the veil, nor come near to the altar, because he has a blemish; that he may not profane my sanctuaries, for I am Yahweh who sanctifies them.''"'),
  ('b41df51d-3eb8-5f43-acaa-e5a94e9a8f1b', 'e2ceacd0-a756-5d98-a07b-3d9042f8d242', NULL, 24, 24, 'So Moses spoke to Aaron, and to his sons, and to all the children of Israel.'),
  ('6c7f5770-35a5-5df0-affa-96c741dc2665', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('6db7f16c-ce43-57ad-a6d3-21aa6945191f', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 2, 2, '"Tell Aaron and his sons to separate themselves from the holy things of the children of Israel, which they make holy to me, and that they not profane my holy name. I am Yahweh.'),
  ('45c1ef27-a9b3-53e9-a1e6-35365678493d', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 3, 3, '"Tell them, ''If anyone of all your seed throughout your generations approaches the holy things, which the children of Israel make holy to Yahweh, having his uncleanness on him, that soul shall be cut off from before me. I am Yahweh.'),
  ('ce05e964-952f-521c-a86a-23cc66e1e188', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 4, 4, '"''Whoever of the seed of Aaron is a leper or has an issue; he shall not eat of the holy things, until he is clean. Whoever touches anything that is unclean by the dead, or a man whose seed goes from him;'),
  ('a095f808-b18c-5bd0-a6b2-58d2ceae0435', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 5, 5, 'or whoever touches any creeping thing, whereby he may be made unclean, or a man of whom he may take uncleanness, whatever uncleanness he has;'),
  ('2ee05c21-b54a-5990-a9b3-c07cbc17b4d7', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 6, 6, 'the person that touches any such shall be unclean until the evening, and shall not eat of the holy things, unless he bathe his body in water.'),
  ('396f9e2c-8c9c-547b-a10a-d45b9386251d', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 7, 7, 'When the sun is down, he shall be clean; and afterward he shall eat of the holy things, because it is his bread.'),
  ('9a845ef4-2e99-5172-ae15-da29128391c6', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 8, 8, 'That which dies of itself, or is torn by animals, he shall not eat, defiling himself by it. I am Yahweh.'),
  ('114db2f1-ac62-57a4-a6d8-9d0500d1ed8b', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 9, 9, '"''They shall therefore follow my requirements, lest they bear sin for it, and die therein, if they profane it. I am Yahweh who sanctifies them.'),
  ('07bf2148-928b-5b1f-a6d0-c9a6a3c457c6', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 10, 10, '"''No stranger shall eat of the holy thing: a foreigner living with the priests, or a hired servant, shall not eat of the holy thing.'),
  ('babc7588-9e1e-5671-a400-0e70a499c3ea', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 11, 11, 'But if a priest buys a slave, purchased by his money, he shall eat of it; and such as are born in his house, they shall eat of his bread.'),
  ('54ea8b58-ee68-56fd-a6be-fbf3fbe1fcc8', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 12, 12, 'If a priest''s daughter is married to an outsider, she shall not eat of the heave offering of the holy things.'),
  ('baeb42f5-4379-58be-a20b-2cfb04343c9c', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 13, 13, 'But if a priest''s daughter is a widow, or divorced, and has no child, and has returned to her father''s house, as in her youth, she may eat of her father''s bread: but no stranger shall eat any of it.'),
  ('a5a87898-9a53-5ae3-a58e-650718381a25', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 14, 14, '"''If a man eats something holy unwittingly, then he shall add the fifth part of its value to it, and shall give the holy thing to the priest.'),
  ('add10391-cd84-5f7e-a30d-542a7ac5f290', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 15, 15, 'The priests shall not profane the holy things of the children of Israel, which they offer to Yahweh,'),
  ('d427fe5f-b71d-53ab-acfc-b4954e4a1ad2', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 16, 16, 'and so cause them to bear the iniquity that brings guilt, when they eat their holy things: for I am Yahweh who sanctifies them.''"'),
  ('692f327d-7729-5ac1-aaf2-b7b7d0ea4b87', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 17, 17, 'Yahweh spoke to Moses, saying,'),
  ('7fcaf1a4-218b-5106-a7aa-94c215937ca4', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 18, 18, '"Speak to Aaron, and to his sons, and to all the children of Israel, and say to them, ''Whoever is of the house of Israel, or of the foreigners in Israel, who offers his offering, whether it be any of their vows, or any of their freewill offerings, which they offer to Yahweh for a burnt offering;'),
  ('689a5128-9710-5207-a079-63800b7cab0a', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 19, 19, 'that you may be accepted, you shall offer a male without blemish, of the bulls, of the sheep, or of the goats.'),
  ('0407ed47-1c10-589c-a082-fbeb25f41a2c', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 20, 20, 'But whatever has a blemish, that you shall not offer: for it shall not be acceptable for you.'),
  ('d2221bf9-7542-5cd9-ad66-a2c2553b85a8', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 21, 21, 'Whoever offers a sacrifice of peace offerings to Yahweh to accomplish a vow, or for a freewill offering, of the herd or of the flock, it shall be perfect to be accepted; no blemish shall be therein.'),
  ('e6b0db72-0618-5a3f-a221-f2443a38aeee', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 22, 22, 'Blind, injured, maimed, having a wart, festering, or having a running sore, you shall not offer these to Yahweh, nor make an offering by fire of them on the altar to Yahweh.'),
  ('6bf95b8e-fb71-51b2-a07c-92354a569eb1', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 23, 23, 'Either a bull or a lamb that has any deformity or lacking in his parts, that you may offer for a freewill offering; but for a vow it shall not be accepted.'),
  ('640568b3-883e-5d74-a20b-69472e3435f7', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 24, 24, 'That which has its testicles bruised, crushed, broken, or cut, you shall not offer to Yahweh; neither shall you do thus in your land.'),
  ('3b5974cf-3d72-55c4-aeda-651f731a0618', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 25, 25, 'Neither shall you offer the bread of your God from the hand of a foreigner of any of these; because their corruption is in them. There is a blemish in them. They shall not be accepted for you.''"'),
  ('8fe64820-b1f6-588c-a994-84db16eb974c', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 26, 26, 'Yahweh spoke to Moses, saying,'),
  ('0c668a45-b39e-507a-a166-8371ad00f517', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 27, 27, '"When a bull, or a sheep, or a goat, is born, then it shall remain seven days with its mother; and from the eighth day and thenceforth it shall be accepted for the offering of an offering made by fire to Yahweh.'),
  ('ba281af5-3567-5801-a738-f6954830a0ff', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 28, 28, 'Whether it is a cow or ewe, you shall not kill it and its young both in one day.'),
  ('fb5d1e3a-7cb8-5c71-ac7c-a7ba6945ca8a', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 29, 29, '"When you sacrifice a sacrifice of thanksgiving to Yahweh, you shall sacrifice it so that you may be accepted.'),
  ('f4fc1745-27f9-5592-a37a-5e9e091ad52b', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 30, 30, 'It shall be eaten on the same day; you shall leave none of it until the morning. I am Yahweh.'),
  ('81483c16-560b-58d0-abff-9133b0ae577d', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 31, 31, '"Therefore you shall keep my commandments, and do them. I am Yahweh.'),
  ('441c8adb-a149-5670-a074-25b56e833dda', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 32, 32, 'You shall not profane my holy name, but I will be made holy among the children of Israel. I am Yahweh who makes you holy,'),
  ('b1223a06-c768-5911-abfb-5c170da20b2e', 'd3ee42cc-fe89-5f7e-aaeb-c7cca97c02c9', NULL, 33, 33, 'who brought you out of the land of Egypt, to be your God. I am Yahweh."'),
  ('fd62608b-0608-5f2c-af26-60c94794b4dc', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('522aaed7-969c-567e-af96-3639d62052fe', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 2, 2, '"Speak to the children of Israel, and tell them, ''The set feasts of Yahweh, which you shall proclaim to be holy convocations, even these are my set feasts.'),
  ('6239f8a9-6eeb-5711-aaf1-160586f25ead', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 3, 3, '"''Six days shall work be done: but on the seventh day is a Sabbath of solemn rest, a holy convocation; you shall do no kind of work. It is a Sabbath to Yahweh in all your dwellings.'),
  ('2301f3c3-268e-5edd-a514-df19d9d880fb', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 4, 4, '"''These are the set feasts of Yahweh, even holy convocations, which you shall proclaim in their appointed season.'),
  ('70db7349-4d04-5df0-a0d6-023e260f4fc9', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 5, 5, 'In the first month, on the fourteenth day of the month in the evening, is Yahweh''s Passover.'),
  ('ac23949d-cb1a-55a1-aa96-799612c48748', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 6, 6, 'On the fifteenth day of the same month is the feast of unleavened bread to Yahweh. Seven days you shall eat unleavened bread.'),
  ('a6bf1191-fd89-58b8-aa99-9970a0dbdd93', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 7, 7, 'In the first day you shall have a holy convocation. You shall do no regular work.'),
  ('0986e884-707f-518d-ad06-d108a24fd134', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 8, 8, 'But you shall offer an offering made by fire to Yahweh seven days. In the seventh day is a holy convocation: you shall do no regular work.''"'),
  ('1b388d31-f029-54bc-a740-b18d3b82f2f8', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 9, 9, 'Yahweh spoke to Moses, saying,'),
  ('734c05da-ad18-55f5-ad2f-8690dd6e8f7a', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 10, 10, '"Speak to the children of Israel, and tell them, ''When you have come into the land which I give to you, and shall reap its the harvest, then you shall bring the sheaf of the first fruits of your harvest to the priest:'),
  ('e576c181-0937-5d8e-ac57-f0a054f79f99', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 11, 11, 'and he shall wave the sheaf before Yahweh, to be accepted for you. On the next day after the Sabbath the priest shall wave it.'),
  ('4d41d0b0-e7d9-5e9a-ab0c-c10d924df6b5', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 12, 12, 'On the day when you wave the sheaf, you shall offer a male lamb without blemish a year old for a burnt offering to Yahweh.'),
  ('5d7809c8-19c2-5b78-aa97-4841bd87b1da', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 13, 13, 'The meal offering with it shall be two tenth parts of an ephah of fine flour mingled with oil, an offering made by fire to Yahweh for a pleasant aroma; and the drink offering with it shall be of wine, the fourth part of a hin.'),
  ('39773bf6-68d5-582e-a89e-9e2d9aca6b55', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 14, 14, 'You shall eat neither bread, nor roasted grain, nor fresh grain, until this same day, until you have brought the offering of your God. This is a statute forever throughout your generations in all your dwellings.'),
  ('3c2ffe39-06eb-5d19-ab15-d943e15cd9b8', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 15, 15, '"''You shall count from the next day after the Sabbath, from the day that you brought the sheaf of the wave offering; seven Sabbaths shall be completed:'),
  ('441b1a5f-f245-52b1-aa36-2c3d37dd1a51', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 16, 16, 'even to the next day after the seventh Sabbath you shall number fifty days; and you shall offer a new meal offering to Yahweh.'),
  ('f1751133-2236-502d-ad7b-c9ef759d4658', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 17, 17, 'You shall bring out of your habitations two loaves of bread for a wave offering made of two tenth parts of an ephah of fine flour. They shall be baked with yeast, for first fruits to Yahweh.'),
  ('4ebf269e-c75c-5d2b-a325-639abae58923', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 18, 18, 'You shall present with the bread seven lambs without blemish a year old, one young bull, and two rams. They shall be a burnt offering to Yahweh, with their meal offering, and their drink offerings, even an offering made by fire, of a sweet aroma to Yahweh.'),
  ('5621671e-2bd2-583a-aedb-f8bf9caf706a', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 19, 19, 'You shall offer one male goat for a sin offering, and two male lambs a year old for a sacrifice of peace offerings.'),
  ('6b5e99f5-a76c-593e-afba-5ec4d0e93748', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 20, 20, 'The priest shall wave them with the bread of the first fruits for a wave offering before Yahweh, with the two lambs. They shall be holy to Yahweh for the priest.'),
  ('b8800194-7f40-5130-a13f-1fa829ea464e', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 21, 21, 'You shall make proclamation on the same day: there shall be a holy convocation to you; you shall do no regular work. This is a statute forever in all your dwellings throughout your generations.'),
  ('145b6eaf-ccc1-5235-a997-7cfe09a64297', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 22, 22, '"''When you reap the harvest of your land, you shall not wholly reap into the corners of your field, neither shall you gather the gleanings of your harvest: you shall leave them for the poor, and for the foreigner. I am Yahweh your God.''"'),
  ('3539c7b6-8a77-557e-aabe-70b9a4688d0a', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 23, 23, 'Yahweh spoke to Moses, saying,'),
  ('91b19a36-4fac-58e1-ab09-11b29464dfbd', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 24, 24, '"Speak to the children of Israel, saying, ''In the seventh month, on the first day of the month, shall be a solemn rest to you, a memorial of blowing of trumpets, a holy convocation.'),
  ('f0fcaa8b-a38e-5258-a065-edd731054520', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 25, 25, 'You shall do no regular work; and you shall offer an offering made by fire to Yahweh.''"'),
  ('9c88e8c8-5174-5f4e-adae-18de01a66e08', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 26, 26, 'Yahweh spoke to Moses, saying,'),
  ('dc539eae-97f6-593c-a60a-39f754d95bca', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 27, 27, '"However on the tenth day of this seventh month is the day of atonement: it shall be a holy convocation to you, and you shall afflict yourselves; and you shall offer an offering made by fire to Yahweh.'),
  ('bd2e9d1f-d6d2-5356-add4-cf0079e24edf', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 28, 28, 'You shall do no kind of work in that same day; for it is a day of atonement, to make atonement for you before Yahweh your God.'),
  ('cbbb8a54-a193-5d49-af3b-f5999601ad4b', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 29, 29, 'For whoever it is who shall not deny himself in that same day; shall be cut off from his people.'),
  ('ddb9689d-4d15-5d1e-ac64-1d1fb2df9499', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 30, 30, 'Whoever it is who does any kind of work in that same day, that person I will destroy from among his people.'),
  ('f466bea8-d01a-53ca-a46d-7c17d41468da', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 31, 31, 'You shall do no kind of work: it is a statute forever throughout your generations in all your dwellings.'),
  ('8380a4f6-62fd-5563-abf9-4786531301d1', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 32, 32, 'It shall be a Sabbath of solemn rest for you, and you shall deny yourselves. In the ninth day of the month at evening, from evening to evening, you shall keep your Sabbath."'),
  ('f60e10f5-31ce-563e-ad2d-f10b902b011a', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 33, 33, 'Yahweh spoke to Moses, saying,'),
  ('fca3a5e8-b0f3-58cc-a14a-b92476912da6', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 34, 34, '"Speak to the children of Israel, and say, ''On the fifteenth day of this seventh month is the feast of tents for seven days to Yahweh.'),
  ('8b8ca5d0-76cb-53be-a326-70671493e7b1', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 35, 35, 'On the first day shall be a holy convocation: you shall do no regular work.'),
  ('4202447d-4aab-5c92-ae6c-15312b3ec203', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 36, 36, 'Seven days you shall offer an offering made by fire to Yahweh. On the eighth day shall be a holy convocation to you; and you shall offer an offering made by fire to Yahweh. It is a solemn assembly; you shall do no regular work.'),
  ('356a3029-a450-52c5-aded-513036c79d4f', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 37, 37, '"''These are the appointed feasts of Yahweh, which you shall proclaim to be holy convocations, to offer an offering made by fire to Yahweh, a burnt offering, and a meal offering, a sacrifice, and drink offerings, each on its own day;'),
  ('4ef41a2a-7624-57e8-a57f-e361a3edc5e8', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 38, 38, 'besides the Sabbaths of Yahweh, and besides your gifts, and besides all your vows, and besides all your freewill offerings, which you give to Yahweh.'),
  ('9fc61409-0323-5a2d-a5df-74b6367a6cda', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 39, 39, '"''So on the fifteenth day of the seventh month, when you have gathered in the fruits of the land, you shall keep the feast of Yahweh seven days: on the first day shall be a solemn rest, and on the eighth day shall be a solemn rest.'),
  ('b04f480b-3b3d-58a3-af28-d56b294916d7', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 40, 40, 'You shall take on the first day the fruit of goodly trees, branches of palm trees, and boughs of thick trees, and willows of the brook; and you shall rejoice before Yahweh your God seven days.'),
  ('36b709d6-69bd-57a3-a35c-29ee401645b1', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 41, 41, 'You shall keep it a feast to Yahweh seven days in the year: it is a statute forever throughout your generations; you shall keep it in the seventh month.'),
  ('139f5135-b304-57f1-a675-b185a193c53c', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 42, 42, 'You shall dwell in booths seven days. All who are native-born in Israel shall dwell in booths,'),
  ('b147ea86-1dfd-580c-aa30-fce9236736aa', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 43, 43, 'that your generations may know that I made the children of Israel to dwell in booths, when I brought them out of the land of Egypt. I am Yahweh your God.''"'),
  ('d05bf7e2-22d4-5e9c-a585-2af5ff99823f', '7ea7621c-df7a-5461-a559-fceeb7b75fd3', NULL, 44, 44, 'Moses declared to the children of Israel the appointed feasts of Yahweh.'),
  ('f9f2e8e8-1b0d-5f93-ae9c-58870bb5bb82', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('1acbf424-050a-55a8-a92a-5b99a409606f', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 2, 2, '"Command the children of Israel, that they bring to you pure olive oil beaten for the light, to cause a lamp to burn continually.'),
  ('8a79101b-70bf-5be3-a3c5-da6667b76b8f', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 3, 3, 'Outside of the veil of the Testimony, in the Tent of Meeting, shall Aaron keep it in order from evening to morning before Yahweh continually: it shall be a statute forever throughout your generations.'),
  ('ed7b6201-70c3-52ce-a442-a4c260afe4e2', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 4, 4, 'He shall keep in order the lamps on the pure gold lampstand before Yahweh continually.'),
  ('99cd96c9-6785-5e69-a826-b4dd4e34f2cd', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 5, 5, '"You shall take fine flour, and bake twelve cakes of it: two tenth parts of an ephah shall be in one cake.'),
  ('a5886bf3-1624-5fa6-ac6a-e939a1b323b3', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 6, 6, 'You shall set them in two rows, six on a row, on the pure gold table before Yahweh.'),
  ('1998c6ad-dae3-51dd-aa4d-f6406b74dcf0', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 7, 7, 'You shall put pure frankincense on each row, that it may be to the bread for a memorial, even an offering made by fire to Yahweh.'),
  ('73696924-9908-55d9-a80d-8766b92eb7d3', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 8, 8, 'Every Sabbath day he shall set it in order before Yahweh continually. It is on the behalf of the children of Israel an everlasting covenant.'),
  ('72dc8f34-9edb-5fe7-a797-0dcb14e5caac', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 9, 9, 'It shall be for Aaron and his sons; and they shall eat it in a holy place: for it is most holy to him of the offerings of Yahweh made by fire by a perpetual statute."'),
  ('c3f63968-675e-533a-ab07-f3cff6031b4d', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 10, 10, 'The son of an Israelite woman, whose father was an Egyptian, went out among the children of Israel; and the son of the Israelite woman and a man of Israel strove together in the camp.'),
  ('7d3831ee-2eaa-5731-a5b7-74494bb17c26', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 11, 11, 'The son of the Israelite woman blasphemed the Name, and cursed; and they brought him to Moses. His mother''s name was Shelomith, the daughter of Dibri, of the tribe of Dan.'),
  ('380852b2-4460-5ac5-acc9-cc042c59d618', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 12, 12, 'They put him in custody, until the will of Yahweh should be declared to them.'),
  ('a4a84933-65ed-5ad1-a717-bd997d283416', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 13, 13, 'Yahweh spoke to Moses, saying,'),
  ('9c4acfaa-2a78-5532-a48d-a87246c231f2', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 14, 14, '"Bring out of the camp him who cursed; and let all who heard him lay their hands on his head, and let all the congregation stone him.'),
  ('4c1544a4-0710-54ce-afcc-9b28f909572b', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 15, 15, 'You shall speak to the children of Israel, saying, ''Whoever curses his God shall bear his sin.'),
  ('e4c12f0d-1e54-5098-a92f-ed2320924a4a', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 16, 16, 'He who blasphemes the name of Yahweh, he shall surely be put to death; all the congregation shall certainly stone him: the foreigner as well as the native-born, when he blasphemes the Name, shall be put to death.'),
  ('d399e327-87db-5dda-a148-1d3634e2a1e7', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 17, 17, '"''He who strikes any man mortally shall surely be put to death.'),
  ('6e9ef9dc-335f-5eef-afce-253989de1b6f', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 18, 18, 'He who strikes an animal mortally shall make it good, life for life.'),
  ('d914c785-f023-58c4-a1e5-9a940634eb02', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 19, 19, 'If anyone injures his neighbor; as he has done, so shall it be done to him:'),
  ('d2911d05-4bb0-5263-ae7a-ba5833877ae7', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 20, 20, 'fracture for fracture, eye for eye, tooth for tooth; as he has injured someone, so shall it be done to him.'),
  ('4074240f-f324-551b-a3bb-c487f719ccc7', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 21, 21, 'He who kills an animal shall make it good; and he who kills a man shall be put to death.'),
  ('a9d05d52-fc2d-5ae4-a64d-7d2281f02db3', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 22, 22, 'You shall have one kind of law, for the foreigner as well as the native-born: for I am Yahweh your God.''"'),
  ('1419aefc-4fa9-5306-a2bf-1bd6b2354da2', '5c6a58d3-e9c3-5fd7-a2b0-4100db9346d0', NULL, 23, 23, 'Moses spoke to the children of Israel; and they brought forth him who had cursed out of the camp, and stoned him with stones. The children of Israel did as Yahweh commanded Moses.'),
  ('46e6e611-2a62-58b0-a454-904f11184890', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 1, 1, 'Yahweh said to Moses in Mount Sinai,'),
  ('cd3c725e-af5f-598a-a7aa-1872db1656b0', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 2, 2, '"Speak to the children of Israel, and tell them, ''When you come into the land which I give you, then the land shall keep a Sabbath to Yahweh.'),
  ('04ead2ec-b375-5b54-ae91-d788f8431e54', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 3, 3, 'Six years you shall sow your field, and six years you shall prune your vineyard, and gather in its fruits;'),
  ('3f4578a2-38cc-5aea-a41c-3b4d443a99e7', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 4, 4, 'but in the seventh year there shall be a Sabbath of solemn rest for the land, a Sabbath to Yahweh. You shall not sow your field or prune your vineyard.'),
  ('c6c5f0d9-9b5a-5371-ae23-5041e12c2a00', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 5, 5, 'What grows of itself in your harvest you shall not reap, and the grapes of your undressed vine you shall not gather. It shall be a year of solemn rest for the land.'),
  ('f2ddb345-1738-5b6c-a2fd-74b0737e1ef6', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 6, 6, 'The Sabbath of the land shall be for food for you; for yourself, for your servant, for your maid, for your hired servant, and for your stranger, who lives as a foreigner with you.'),
  ('7e71d181-49a5-558d-a8b3-8acb9c142d0f', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 7, 7, 'For your livestock also, and for the animals that are in your land, shall all its increase be for food.'),
  ('ec332655-db16-5f9e-ae84-b5efab2e8cd2', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 8, 8, '"''You shall count off seven Sabbaths of years, seven times seven years; and there shall be to you the days of seven Sabbaths of years, even forty-nine years.'),
  ('1a0a92a4-75c8-5a6f-ac94-462ce8a5781c', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 9, 9, 'Then you shall sound the loud trumpet on the tenth day of the seventh month. On the Day of Atonement you shall sound the trumpet throughout all your land.'),
  ('7a51c5d8-0c28-5373-abbf-f335bc88a47d', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 10, 10, 'You shall make the fiftieth year holy, and proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee to you; and each of you shall return to his own property, and each of you shall return to his family.'),
  ('28a6afd2-9dce-51fb-a8a8-185d10f20870', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 11, 11, 'That fiftieth year shall be a jubilee to you. In it you shall not sow, neither reap that which grows of itself, nor gather from the undressed vines.'),
  ('6d7ac5c8-8c97-5b3d-a27e-11b6e8b92b96', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 12, 12, 'For it is a jubilee; it shall be holy to you. You shall eat of its increase out of the field.'),
  ('dcfecefa-fadc-5df1-ab08-ef1ab702581a', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 13, 13, '"''In this Year of Jubilee each of you shall return to his property.'),
  ('1864e0e7-694f-5145-abd1-dc002be3d475', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 14, 14, '"''If you sell anything to your neighbor, or buy from your neighbor, you shall not wrong one another.'),
  ('c080e209-19ed-5bc3-a9c7-957b1d6c1f46', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 15, 15, 'According to the number of years after the Jubilee you shall buy from your neighbor. According to the number of years of the crops he shall sell to you.'),
  ('e7463235-91fa-5379-a60f-697c429b22dc', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 16, 16, 'According to the length of the years you shall increase its price, and according to the shortness of the years you shall diminish its price; for he is selling the number of the crops to you.'),
  ('d068beb6-4933-5f44-aac9-e54898f5e574', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 17, 17, 'You shall not wrong one another; but you shall fear your God: for I am Yahweh your God.'),
  ('c754fa73-b035-54a6-a492-765ff404a9c8', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 18, 18, '"''Therefore you shall do my statutes, and keep my ordinances and do them; and you shall dwell in the land in safety.'),
  ('935eedf3-a4c8-5f6f-a240-5abe21b06e30', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 19, 19, 'The land shall yield its fruit, and you shall eat your fill, and dwell therein in safety.'),
  ('0ac23ea3-6c79-5a96-a2ed-fa252e37e076', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 20, 20, 'If you said, "What shall we eat the seventh year? Behold, we shall not sow, nor gather in our increase;"'),
  ('8846b4db-3388-5b6a-a5c5-1ac0d6e26256', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 21, 21, 'then I will command my blessing on you in the sixth year, and it shall bring forth fruit for the three years.'),
  ('4f1e1e0a-3493-5303-aeae-46782d897108', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 22, 22, 'You shall sow the eighth year, and eat of the fruits, the old store; until the ninth year, until its fruits come in, you shall eat the old store.'),
  ('4c915332-ee0b-591d-a185-7f7bd7b36cba', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 23, 23, '"''The land shall not be sold in perpetuity, for the land is mine; for you are strangers and live as foreigners with me.'),
  ('8085c8e0-80ea-52cc-af6d-bf8b4aa136c4', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 24, 24, 'In all the land of your possession you shall grant a redemption for the land.'),
  ('38f27b37-a47c-55eb-abff-857eb944cb36', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 25, 25, '"''If your brother becomes poor, and sells some of his possessions, then his kinsman who is next to him shall come, and redeem that which his brother has sold.'),
  ('f622f8dd-463f-5228-aad7-40f7acdd582a', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 26, 26, 'If a man has no one to redeem it, and he becomes prosperous and finds sufficient means to redeem it;'),
  ('0d6cdf21-56c5-577f-a651-a56fb610bf4c', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 27, 27, 'then let him reckon the years since its sale, and restore the surplus to the man to whom he sold it; and he shall return to his property.'),
  ('96b7be04-4f9c-5661-a453-196cdf816ea6', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 28, 28, 'But if he isn''t able to get it back for himself, then what he has sold shall remain in the hand of him who has bought it until the Year of Jubilee: and in the Jubilee it shall be released, and he shall return to his property.'),
  ('7eab8ceb-9bcc-54b8-a631-c5cffb59b44e', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 29, 29, '"''If a man sells a dwelling house in a walled city, then he may redeem it within a whole year after it has been sold. For a full year he shall have the right of redemption.'),
  ('8f1ae158-99c3-5365-a884-866ed37d9c1a', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 30, 30, 'If it isn''t redeemed within the space of a full year, then the house that is in the walled city shall be made sure in perpetuity to him who bought it, throughout his generations. It shall not be released in the Jubilee.'),
  ('5ab70835-24b3-59e6-ab87-e842433fff66', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 31, 31, 'But the houses of the villages which have no wall around them shall be reckoned with the fields of the country: they may be redeemed, and they shall be released in the Jubilee.'),
  ('e32870a2-c1b7-520a-ade4-8dcb213f29d2', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 32, 32, '"''Nevertheless the cities of the Levites, the houses in the cities of their possession, the Levites may redeem at any time.'),
  ('b646a909-c80f-526b-ae6a-15459bb48362', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 33, 33, 'The Levites may redeem the house that was sold, and the city of his possession, and it shall be released in the Jubilee; for the houses of the cities of the Levites are their possession among the children of Israel.'),
  ('530ebaf1-9496-5acf-aa9f-53fefc6c625f', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 34, 34, 'But the field of the suburbs of their cities may not be sold; for it is their perpetual possession.'),
  ('cc4cd413-b777-52d0-a46d-6f90466be54f', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 35, 35, '"''If your brother has become poor, and his hand can''t support him among you; then you shall uphold him. He shall live with you like an alien and a temporary resident.'),
  ('2e41b673-a59c-52f7-a25b-150ebd306226', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 36, 36, 'Take no interest from him or profit, but fear your God; that your brother may live among you.'),
  ('d8ba6343-fbab-57b5-a150-65f39549c48d', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 37, 37, 'You shall not lend him your money at interest, nor give him your food for profit.'),
  ('fbfac85c-327b-527f-aa1b-6aea984cfaf4', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 38, 38, 'I am Yahweh your God, who brought you forth out of the land of Egypt, to give you the land of Canaan, and to be your God.'),
  ('0c5714fc-0b09-5a78-aa4c-96a8cecfd1b8', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 39, 39, '"''If your brother has grown poor among you, and sells himself to you; you shall not make him to serve as a slave.'),
  ('766dcc5c-984a-5530-a8c9-3edbfa91f437', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 40, 40, 'As a hired servant, and as a temporary resident, he shall be with you; he shall serve with you until the Year of Jubilee:'),
  ('7ebd8d8a-81fc-591b-a07c-dd6c1ec854f0', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 41, 41, 'then he shall go out from you, he and his children with him, and shall return to his own family, and to the possession of his fathers.'),
  ('93cfd870-1f11-5734-aaff-4ed1fdc92178', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 42, 42, 'For they are my servants, whom I brought forth out of the land of Egypt. They shall not be sold as slaves.'),
  ('06b8158d-2e5d-5a64-a53d-1b478eece589', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 43, 43, 'You shall not rule over him with harshness, but shall fear your God.'),
  ('99c4e875-f230-5604-a71e-064bd026b27c', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 44, 44, '"''As for your male and your female slaves, whom you may have; of the nations that are around you, from them you may buy male and female slaves.'),
  ('3e5d5da6-1d06-5277-aeef-24285fe622cf', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 45, 45, 'Moreover of the children of the aliens who live among you, of them you may buy, and of their families who are with you, which they have conceived in your land; and they will be your property.'),
  ('f6bdec89-16d6-555b-a955-84dc8a2cfd37', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 46, 46, 'You may make them an inheritance for your children after you, to hold for a possession; of them may you take your slaves forever: but over your brothers the children of Israel you shall not rule, one over another, with harshness.'),
  ('ca5fefe6-b559-590a-ae47-2f4d967a81b2', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 47, 47, '"''If an alien or temporary resident with you becomes rich, and your brother beside him has grown poor, and sells himself to the stranger or foreigner living among you, or to a member of the stranger''s family;'),
  ('832a2d85-9c1a-5f84-a3fd-c724aeb9a15c', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 48, 48, 'after he is sold he may be redeemed. One of his brothers may redeem him;'),
  ('06de46fe-4541-5de2-afb8-7105acbed295', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 49, 49, 'or his uncle, or his uncle''s son, may redeem him, or any who is a close relative to him of his family may redeem him; or if he has grown rich, he may redeem himself.'),
  ('91a06a92-5c65-5538-a493-b030ba1b9aa7', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 50, 50, 'He shall reckon with him who bought him from the year that he sold himself to him to the Year of Jubilee: and the price of his sale shall be according to the number of years; according to the time of a hired servant shall he be with him.'),
  ('afc17fde-2589-543a-afaa-918b7b8e3c70', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 51, 51, 'If there are yet many years, according to them he shall give back the price of his redemption out of the money that he was bought for.'),
  ('0c35f439-77c0-5c64-a035-315c0a304b3d', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 52, 52, 'If there remain but a few years to the year of jubilee, then he shall reckon with him; according to his years of service he shall give back the price of his redemption.'),
  ('cc95897f-46c9-5d0e-a257-23d9cd0971d5', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 53, 53, 'As a servant hired year by year shall he be with him: he shall not rule with harshness over him in your sight.'),
  ('8a646bda-304e-5e81-a930-8d8d92f28c8f', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 54, 54, 'If he isn''t redeemed by these means, then he shall be released in the Year of Jubilee, he, and his children with him.'),
  ('50fc78ea-37d0-51f4-a96f-d7a9d81e2af2', '6c62a7ca-cab7-58a1-a853-787399c76e74', NULL, 55, 55, 'For to me the children of Israel are servants; they are my servants whom I brought forth out of the land of Egypt. I am Yahweh your God.'),
  ('b7a418d0-04cb-5023-a623-c0d9efa93fb4', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 1, 1, '"''You shall make for yourselves no idols, neither shall you raise up an engraved image or a pillar, neither shall you place any figured stone in your land, to bow down to it: for I am Yahweh your God.'),
  ('6b5b6a8c-3750-546d-a4c6-5fef003ccf43', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 2, 2, '"''You shall keep my Sabbaths, and have reverence for my sanctuary. I am Yahweh.'),
  ('4af35888-0c7b-52ce-a132-6ae5541b85cd', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 3, 3, '"''If you walk in my statutes, and keep my commandments, and do them;'),
  ('6c4805a6-8e1f-5d01-a8e6-8fbb4274d600', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 4, 4, 'then I will give you your rains in their season, and the land shall yield its increase, and the trees of the field shall yield their fruit.'),
  ('12076458-0bd6-5e23-a1ff-803efb2d0d9a', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 5, 5, 'Your threshing shall reach to the vintage, and the vintage shall reach to the sowing time; and you shall eat your bread to the full, and dwell in your land safely.'),
  ('e7a9151f-06b0-5a10-ac30-86ca883523a3', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 6, 6, '"''I will give peace in the land, and you shall lie down, and no one will make you afraid; and I will remove evil animals out of the land, neither shall the sword go through your land.'),
  ('24728600-47c5-55f4-a4af-361babf0c34e', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 7, 7, 'You shall chase your enemies, and they shall fall before you by the sword.'),
  ('17ace97c-4cfe-58dc-a8a2-cdb01ad3c570', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 8, 8, 'Five of you shall chase a hundred, and a hundred of you shall chase ten thousand; and your enemies shall fall before you by the sword.'),
  ('42a27a4a-756b-5bba-a6ff-31ce534b23ef', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 9, 9, '"''I will have respect for you, and make you fruitful, and multiply you, and will establish my covenant with you.'),
  ('0ea61978-447a-569c-aae8-f93b6edff126', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 10, 10, 'You shall eat old store long kept, and you shall move out the old because of the new.'),
  ('7c0d9103-4b78-52ea-aff8-f5c971c7d23c', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 11, 11, 'I will set my tent among you: and my soul won''t abhor you.'),
  ('9aa1eed0-7075-5de9-a529-ee02e7156111', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 12, 12, 'I will walk among you, and will be your God, and you will be my people.'),
  ('c4b7af65-3ab2-5e84-a63c-7000367a9508', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 13, 13, 'I am Yahweh your God, who brought you forth out of the land of Egypt, that you should not be their slaves; and I have broken the bars of your yoke, and made you go upright.'),
  ('c2d106e9-d665-5f6a-a025-18c85ba68372', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 14, 14, '"''But if you will not listen to me, and will not do all these commandments;'),
  ('7736309e-016e-5958-a7e3-fcdd4f5e2d39', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 15, 15, 'and if you shall reject my statutes, and if your soul abhors my ordinances, so that you will not do all my commandments, but break my covenant;'),
  ('7c9df8e8-ef9b-58b4-a109-a0d379188d14', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 16, 16, 'I also will do this to you: I will appoint terror over you, even consumption and fever, that shall consume the eyes, and make the soul to pine away; and you will sow your seed in vain, for your enemies will eat it.'),
  ('82f8c54e-a5ef-56d4-aaf6-6f11bffc7382', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 17, 17, 'I will set my face against you, and you will be struck before your enemies. Those who hate you will rule over you; and you will flee when no one pursues you.'),
  ('65dbb63b-c898-5e03-a17f-5ea4365ab3bd', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 18, 18, '"''If you in spite of these things will not listen to me, then I will chastise you seven times more for your sins.'),
  ('61c98dc7-89fa-56ba-a2ab-264bfb93dba0', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 19, 19, 'I will break the pride of your power, and I will make your sky like iron, and your soil like brass;'),
  ('566178f9-ccc2-56ea-a327-f0fda08e62dc', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 20, 20, 'and your strength will be spent in vain; for your land won''t yield its increase, neither will the trees of the land yield their fruit.'),
  ('548ec906-bac9-5bef-a184-4d45b5eb46db', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 21, 21, '"''If you walk contrary to me, and won''t listen to me, then I will bring seven times more plagues on you according to your sins.'),
  ('cee3769c-0a45-5015-a30d-1802f6207644', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 22, 22, 'I will send the wild animals among you, which will rob you of your children, destroy your livestock, and make you few in number; and your roads will become desolate.'),
  ('ecebb361-a5a5-5661-a8c2-73f68640ae69', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 23, 23, '"''If by these things you won''t be reformed to me, but will walk contrary to me;'),
  ('61d48a8e-ab81-51f7-a8f7-3368bbe5b1be', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 24, 24, 'then I will also walk contrary to you; and I will strike you, even I, seven times for your sins.'),
  ('9a1eb4ba-8aea-5772-ac2d-f2a3461ca144', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 25, 25, 'I will bring a sword upon you, that will execute the vengeance of the covenant; and you will be gathered together within your cities: and I will send the pestilence among you; and you will be delivered into the hand of the enemy.'),
  ('485239a0-fe18-50c3-a1aa-aefcff1538dc', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 26, 26, 'When I break your staff of bread, ten women shall bake your bread in one oven, and they shall deliver your bread again by weight: and you shall eat, and not be satisfied.'),
  ('d7828663-6646-5350-a555-b3da5cb97d62', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 27, 27, '"''If you in spite of this won''t listen to me, but walk contrary to me;'),
  ('eaaf45f1-f7aa-57a3-aa8e-f95382aab8eb', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 28, 28, 'then I will walk contrary to you in wrath; and I also will chastise you seven times for your sins.'),
  ('323e5973-a704-5402-aaf7-b2525a5b6544', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 29, 29, 'You will eat the flesh of your sons, and you will eat the flesh of your daughters.'),
  ('085a5c4d-da12-528e-ab90-3f59d3ef5de7', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 30, 30, 'I will destroy your high places, and cut down your incense altars, and cast your dead bodies upon the bodies of your idols; and my soul will abhor you.'),
  ('b9c23115-34ca-52cf-a077-c21ee3296a99', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 31, 31, 'I will lay your cities waste, and will bring your sanctuaries to desolation, and I will not take delight in the sweet fragrance of your offerings.'),
  ('d568ab20-63df-5e66-a17b-f44dc61ed0a7', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 32, 32, 'I will bring the land into desolation; and your enemies that dwell therein will be astonished at it.'),
  ('fcc108b0-4b7a-5cfb-a6b1-63f6e45c4d85', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 33, 33, 'I will scatter you among the nations, and I will draw out the sword after you: and your land will be a desolation, and your cities shall be a waste.'),
  ('809447d9-ac1e-5121-a552-e55058ad8cd9', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 34, 34, 'Then the land will enjoy its sabbaths as long as it lies desolate and you are in your enemies'' land. Even then the land will rest and enjoy its sabbaths.'),
  ('c3eedd73-a733-5bdc-a673-eec3cdeee978', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 35, 35, 'As long as it lies desolate it shall have rest, even the rest which it didn''t have in your sabbaths, when you lived on it.'),
  ('c3ec5927-845c-5540-a11d-726c1c9817bb', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 36, 36, '"''As for those of you who are left, I will send a faintness into their hearts in the lands of their enemies: and the sound of a driven leaf will put them to flight; and they shall flee, as one flees from the sword; and they will fall when no one pursues.'),
  ('b911cd5d-e4a1-5b4b-a322-f2c41dda9575', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 37, 37, 'They will stumble over one another, as it were before the sword, when no one pursues: and you will have no power to stand before your enemies.'),
  ('741c4584-46be-5206-a072-66085529f167', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 38, 38, 'You will perish among the nations, and the land of your enemies will eat you up.'),
  ('37129d97-7753-5eff-ab7b-4b4be883d75e', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 39, 39, 'Those of you who are left will pine away in their iniquity in your enemies'' lands; and also in the iniquities of their fathers shall they pine away with them.'),
  ('85b506e7-3698-520a-afff-36e94d0dee87', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 40, 40, '"''If they confess their iniquity, and the iniquity of their fathers, in their trespass which they trespassed against me, and also that, because they walked contrary to me,'),
  ('d2c06122-fb84-5bfd-aec9-7d29219e22f2', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 41, 41, 'I also walked contrary to them, and brought them into the land of their enemies: if then their uncircumcised heart is humbled, and they then accept the punishment of their iniquity;'),
  ('fcfb8c4b-d9dd-5916-ab5e-0275d51a99dd', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 42, 42, 'then I will remember my covenant with Jacob; and also my covenant with Isaac, and also my covenant with Abraham; and I will remember the land.'),
  ('1e987ed3-b711-51ed-a077-e2297982aa57', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 43, 43, 'The land also will be left by them, and will enjoy its sabbaths while it lies desolate without them: and they will accept the punishment of their iniquity; because, even because they rejected my ordinances, and their soul abhorred my statutes.'),
  ('075f3e18-9fc2-5f49-a110-850ef0f0dfe9', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 44, 44, 'Yet for all that, when they are in the land of their enemies, I will not reject them, neither will I abhor them, to destroy them utterly, and to break my covenant with them; for I am Yahweh their God;'),
  ('4b0dcd5d-e50b-5628-acdc-e62a05012f1f', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 45, 45, 'but I will for their sake remember the covenant of their ancestors, whom I brought forth out of the land of Egypt in the sight of the nations, that I might be their God. I am Yahweh.''"'),
  ('b371ad1d-3c35-56fe-a93d-c5f28661bff9', 'c33c1a9a-97b1-5a24-a0d7-86d9a34d830f', NULL, 46, 46, 'These are the statutes, ordinances and laws, which Yahweh made between him and the children of Israel in Mount Sinai by Moses.'),
  ('c2d5ea54-05c1-5901-ac1d-a0c2c608c4dc', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('763239d1-9a13-5c60-afed-5096f2a9ada0', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 2, 2, '"Speak to the children of Israel, and say to them, ''When a man makes a vow, the persons shall be for Yahweh by your valuation.'),
  ('749e45eb-00ee-535b-a5d1-6586307fdac8', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 3, 3, 'Your valuation shall be of a male from twenty years old even to sixty years old, even your valuation shall be fifty shekels of silver, after the shekel of the sanctuary.'),
  ('341ee23c-fbb9-5463-a4b5-0b5579ba71bd', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 4, 4, 'If it is a female, then your valuation shall be thirty shekels.'),
  ('b051134c-eb6f-53c7-aabc-81a1df4665ad', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 5, 5, 'If the person is from five years old even to twenty years old, then your valuation shall be for a male twenty shekels, and for a female ten shekels.'),
  ('c038eef7-190f-587a-afef-028711fad326', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 6, 6, 'If the person is from a month old even to five years old, then your valuation shall be for a male five shekels of silver, and for a female your valuation shall be three shekels of silver.'),
  ('29681847-23cb-5257-acf2-8909b1c9e071', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 7, 7, 'If the person is from sixty years old and upward; if it is a male, then your valuation shall be fifteen shekels, and for a female ten shekels.'),
  ('3d9d51d4-4338-5594-ab0f-3b76e1dbabac', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 8, 8, 'But if he is poorer than your valuation, then he shall be set before the priest, and the priest shall value him; according to the ability of him who vowed shall the priest value him.'),
  ('00b40695-31c2-5171-a8e2-ecf92cb83297', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 9, 9, '"''If it is an animal, of which men offer an offering to Yahweh, all that any man gives of such to Yahweh becomes holy.'),
  ('510b45f7-abba-5a95-aa82-b3b35f41a53a', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 10, 10, 'He shall not alter it, nor change it, a good for a bad, or a bad for a good: and if he shall at all change animal for animal, then both it and that for which it is changed shall be holy.'),
  ('d77c436c-fc5b-5529-a1d3-de80e3c3b158', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 11, 11, 'If it is any unclean animal, of which they do not offer as an offering to Yahweh, then he shall set the animal before the priest;'),
  ('30bb06d6-8c0e-585f-ac84-65151cb53ad4', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 12, 12, 'and the priest shall value it, whether it is good or bad. As you the priest values it, so shall it be.'),
  ('bb45a615-c5ef-5faf-ad68-8c7d3a80d111', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 13, 13, 'But if he will indeed redeem it, then he shall add the fifth part of it to its valuation.'),
  ('9f07b120-c9b4-5ac3-a82a-44313360f257', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 14, 14, '"''When a man dedicates his house to be holy to Yahweh, then the priest shall evaluate it, whether it is good or bad: as the priest shall evaluate it, so shall it stand.'),
  ('5c55bced-85c9-5d28-aabe-d61fd9088267', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 15, 15, 'If he who dedicates it will redeem his house, then he shall add the fifth part of the money of your valuation to it, and it shall be his.'),
  ('7cbe1ee4-f242-52ed-ac9b-bf633baa99e2', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 16, 16, '"''If a man dedicates to Yahweh part of the field of his possession, then your valuation shall be according to the seed for it: the sowing of a homer of barley shall be valued at fifty shekels of silver.'),
  ('3bc644f9-dc06-5bda-ac9d-f2e490d5db7b', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 17, 17, 'If he dedicates his field from the Year of Jubilee, according to your valuation it shall stand.'),
  ('3421a1a1-8407-5a30-a72d-0e9efbe2d497', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 18, 18, 'But if he dedicates his field after the Jubilee, then the priest shall reckon to him the money according to the years that remain to the Year of Jubilee; and an abatement shall be made from your valuation.'),
  ('4cf43ee6-46b3-5720-a28a-866d88187df3', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 19, 19, 'If he who dedicated the field will indeed redeem it, then he shall add the fifth part of the money of your valuation to it, and it shall remain his.'),
  ('f7d4dd6d-9abb-5119-a300-87df13a2c4c3', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 20, 20, 'If he will not redeem the field, or if he has sold the field to another man, it shall not be redeemed any more;'),
  ('a77b5781-198b-538c-a777-d7e5d36c2903', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 21, 21, 'but the field, when it goes out in the Jubilee, shall be holy to Yahweh, as a field devoted; it shall be owned by the priests.'),
  ('aba4b157-f787-5ab1-ab5d-35acbefb0eed', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 22, 22, '"''If he dedicates to Yahweh a field which he has bought, which is not of the field of his possession,'),
  ('c5a232fc-d364-5ea1-a6c7-e7abc31f492e', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 23, 23, 'then the priest shall reckon to him the worth of your valuation up to the Year of Jubilee; and he shall give your valuation on that day, as a holy thing to Yahweh.'),
  ('67a59782-84e4-5948-afc8-1ba08da14b4d', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 24, 24, 'In the Year of Jubilee the field shall return to him from whom it was bought, even to him to whom the possession of the land belongs.'),
  ('56697836-077c-545b-a1aa-17451baffdd4', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 25, 25, 'All your valuations shall be according to the shekel of the sanctuary: twenty gerahs to the shekel.'),
  ('73b91fef-cbc4-5f7c-a325-b643cb7b193b', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 26, 26, '"''Only the firstborn among animals, which is made a firstborn to Yahweh, no man may dedicate it; whether an ox or sheep, it is Yahweh''s.'),
  ('62173d1e-34f6-5e99-acf7-a9b95d10117e', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 27, 27, 'If it is an unclean animal, then he shall buy it back according to your valuation, and shall add to it the fifth part of it: or if it isn''t redeemed, then it shall be sold according to your valuation.'),
  ('fc3f1eaa-b606-59d0-af67-ae37229ec310', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 28, 28, '"''Notwithstanding, no devoted thing, that a man shall devote to Yahweh of all that he has, whether of man or animal, or of the field of his possession, shall be sold or redeemed: every devoted thing is most holy to Yahweh.'),
  ('7ca6beb9-fbd6-5c2e-a51c-6903e3e4a235', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 29, 29, '"''No one devoted, who shall be devoted from among men, shall be ransomed; he shall surely be put to death.'),
  ('601d72f2-8a3c-511e-ac30-c51ef205f461', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 30, 30, '"''All the tithe of the land, whether of the seed of the land or of the fruit of the trees, is Yahweh''s. It is holy to Yahweh.'),
  ('692cb713-a28c-55fc-a42d-2dea780aa61a', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 31, 31, 'If a man redeems anything of his tithe, he shall add a fifth part to it.'),
  ('5bdb953a-cb80-57d3-abf4-9d104aa58134', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 32, 32, 'All the tithe of the herds or the flocks, whatever passes under the rod, the tenth shall be holy to Yahweh.'),
  ('6ee1288f-1f38-585a-a523-78bdd65aa1e4', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 33, 33, 'He shall not search whether it is good or bad, neither shall he change it: and if he changes it at all, then both it and that for which it is changed shall be holy. It shall not be redeemed.''"'),
  ('2b2f9410-40bf-594a-ac31-4c85422ec155', '6cea9f72-b573-5f68-a59a-f366088f60e0', NULL, 34, 34, 'These are the commandments which Yahweh commanded Moses for the children of Israel on Mount Sinai.'),
  ('14821e36-00f7-5aa0-a874-f7f643049352', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 1, 1, 'Yahweh spoke to Moses in the wilderness of Sinai, in the Tent of Meeting, on the first day of the second month, in the second year after they had come out of the land of Egypt, saying,'),
  ('588df8ed-2679-5926-a258-28a152b4ca53', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 2, 2, '"Take a census of all the congregation of the children of Israel, by their families, by their fathers'' houses, according to the number of the names, every male, one by one;'),
  ('d68059bf-6626-58a6-a046-9873c86ef8bc', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 3, 3, 'from twenty years old and upward, all who are able to go out to war in Israel. You and Aaron shall number them by their divisions.'),
  ('dea02bfe-b419-566f-a74a-a51fed50b2c3', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 4, 4, 'With you there shall be a man of every tribe; everyone head of his fathers'' house.'),
  ('1df5704f-dc76-5421-a64b-7f36474c2834', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 5, 5, 'These are the names of the men who shall stand with you: Of Reuben: Elizur the son of Shedeur.'),
  ('a520fd6d-5f35-5a4d-ac2f-35561385abd8', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 6, 6, 'Of Simeon: Shelumiel the son of Zurishaddai.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ff03504c-1511-5972-a74b-d9c150ae586a', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 7, 7, 'Of Judah: Nahshon the son of Amminadab.'),
  ('b4bdda25-e2cc-51e9-af75-85ac52004b81', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 8, 8, 'Of Issachar: Nethanel the son of Zuar.'),
  ('dd24a1cd-6ee0-5c04-a38c-8aa0a500ac9e', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 9, 9, 'Of Zebulun: Eliab the son of Helon.'),
  ('79a1f47f-29df-5e36-a79e-823bde1181b7', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 10, 10, 'Of the children of Joseph: Of Ephraim: Elishama the son of Ammihud. Of Manasseh: Gamaliel the son of Pedahzur.'),
  ('613ae8f1-8e74-59ef-a6ac-23213bc0b2c1', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 11, 11, 'Of Benjamin: Abidan the son of Gideoni.'),
  ('22fe8da5-7332-5be7-a4c0-195487ba4cf5', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 12, 12, 'Of Dan: Ahiezer the son of Ammishaddai.'),
  ('172b966d-9219-5560-afdc-fc8a0a809b51', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 13, 13, 'Of Asher: Pagiel the son of Ochran.'),
  ('d436adf5-d756-581e-ad12-ecb108c5b0d3', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 14, 14, 'Of Gad: Eliasaph the son of Deuel.'),
  ('7caa0e84-ffb1-5aac-a51c-f0bfac5f2eb6', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 15, 15, 'Of Naphtali: Ahira the son of Enan."'),
  ('8c3dc5fd-f4ae-5129-a08e-7d713540268b', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 16, 16, 'These are those who were called of the congregation, the princes of the tribes of their fathers; they were the heads of the thousands of Israel.'),
  ('5c872e0c-b60c-5595-ada7-b4052467941d', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 17, 17, 'Moses and Aaron took these men who are mentioned by name.'),
  ('a764f130-35df-5631-a8f0-462f1bf74685', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 18, 18, 'They assembled all the congregation together on the first day of the second month; and they declared their ancestry by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, one by one.'),
  ('821abd44-3cd6-59e9-a9a4-5377b7535e29', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 19, 19, 'As Yahweh commanded Moses, so he numbered them in the wilderness of Sinai.'),
  ('1e11334e-6cd3-52ea-ae65-ef9b8e57affd', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 20, 20, 'The children of Reuben, Israel''s firstborn, their generations, by their families, by their fathers'' houses, according to the number of the names, one by one, every male from twenty years old and upward, all who were able to go out to war;'),
  ('c62d33ed-19d2-5b90-a31f-dbf248b35d86', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 21, 21, 'those who were numbered of them, of the tribe of Reuben, were forty-six thousand five hundred.'),
  ('40788514-3a3e-5f4b-a9b0-48ff89b6bc72', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 22, 22, 'Of the children of Simeon, their generations, by their families, by their fathers'' houses, those who were numbered of it, according to the number of the names, one by one, every male from twenty years old and upward, all who were able to go out to war;'),
  ('9d423f47-2426-50bb-a314-53b18e110248', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 23, 23, 'those who were numbered of them, of the tribe of Simeon, were fifty-nine thousand three hundred.'),
  ('affa5238-ef89-59f3-a762-12bb2efbec7c', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 24, 24, 'Of the children of Gad, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('3fa6ab37-7ed3-5d00-aafe-f5203c1e4dac', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 25, 25, 'those who were numbered of them, of the tribe of Gad, were forty-five thousand six hundred fifty.'),
  ('f0da7365-5bc8-55d7-a3e2-edfde20aa33b', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 26, 26, 'Of the children of Judah, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('fe4c7646-4cad-5fa2-a3ed-64a91e8d003a', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 27, 27, 'those who were numbered of them, of the tribe of Judah, were sixty-four thousand six hundred.'),
  ('8f795bb3-fa30-5ea3-a340-e080dbd4c15a', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 28, 28, 'Of the children of Issachar, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('879f68d2-3f03-5349-a61f-f538a58cb199', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 29, 29, 'those who were numbered of them, of the tribe of Issachar, were fifty-four thousand four hundred.'),
  ('db3a2bc5-3487-5a00-a3b9-bb84bf363bfd', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 30, 30, 'Of the children of Zebulun, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('3ac60fbe-c85a-5ad0-a942-21aea6b8cd9a', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 31, 31, 'those who were numbered of them, of the tribe of Zebulun, were fifty-seven thousand four hundred.'),
  ('0da233cd-b36d-586b-a43f-e1283bb13e7b', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 32, 32, 'Of the children of Joseph, of the children of Ephraim, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('f6be9d9e-3816-5ba7-aec1-6adddf254db1', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 33, 33, 'those who were numbered of them, of the tribe of Ephraim, were forty thousand five hundred.'),
  ('87c55651-c5c6-564b-a1bd-1465d2a1cfd9', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 34, 34, 'Of the children of Manasseh, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('dcfb11c7-2eb0-5903-adf4-d98f15a846b0', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 35, 35, 'those who were numbered of them, of the tribe of Manasseh, were thirty-two thousand two hundred.'),
  ('c03867b4-b034-5930-a896-a7163a8a591f', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 36, 36, 'Of the children of Benjamin, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go out to war;'),
  ('05c04138-9a34-5274-ad95-4ef60c93b22e', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 37, 37, 'those who were numbered of them, of the tribe of Benjamin, were thirty-five thousand four hundred.'),
  ('f8668202-ea12-5e46-abca-9bffbd6271ec', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 38, 38, 'Of the children of Dan, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go forth to war;'),
  ('001c79cb-8ab5-51dc-ae52-36d16e5fa507', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 39, 39, 'those who were numbered of them, of the tribe of Dan, were sixty-two thousand seven hundred.'),
  ('1b85e919-f31e-5cb3-aa16-43be96e22471', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 40, 40, 'Of the children of Asher, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go forth to war;'),
  ('ab0a5ed2-95ba-5755-a9d0-fe55887c4ae9', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 41, 41, 'those who were numbered of them, of the tribe of Asher, were forty-one thousand five hundred.'),
  ('3af247bf-7f7e-5f98-a556-a1d216f52fc6', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 42, 42, 'Of the children of Naphtali, their generations, by their families, by their fathers'' houses, according to the number of the names, from twenty years old and upward, all who were able to go forth to war;'),
  ('52c964d4-3dae-5ea9-aa3b-a8a300ffb887', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 43, 43, 'those who were numbered of them, of the tribe of Naphtali, were fifty-three thousand four hundred.'),
  ('1a84b62b-add4-50a3-ab0c-8c42ea6261f5', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 44, 44, 'These are those who were numbered, whom Moses and Aaron numbered, and the princes of Israel, being twelve men: they were each one for his fathers'' house.'),
  ('e2a2adac-7ccb-5d41-a033-21dce7322aa2', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 45, 45, 'So all those who were numbered of the children of Israel by their fathers'' houses, from twenty years old and upward, all who were able to go out to war in Israel;'),
  ('b8cc68a5-83dc-5af4-a49d-5aebc927e432', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 46, 46, 'even all those who were numbered were six hundred three thousand five hundred fifty.'),
  ('f7d45437-55df-5463-a42c-688ef6f0912b', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 47, 47, 'But the Levites after the tribe of their fathers were not numbered among them.'),
  ('bb4ea430-b78c-5308-a6d4-c45457a61bb2', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 48, 48, 'For Yahweh spoke to Moses, saying,'),
  ('9f9dc2ae-abb3-549e-a723-a1ffec14cd81', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 49, 49, '"Only the tribe of Levi you shall not number, neither shall you take a census of them among the children of Israel;'),
  ('3c711b42-5007-51f0-ae77-b6a8b36ce7f3', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 50, 50, 'but appoint the Levites over the Tabernacle of the Testimony, and over all its furnishings, and over all that belongs to it. They shall carry the tabernacle, and all its furnishings; and they shall take care of it, and shall encamp around it.'),
  ('87fe166a-177e-55aa-a505-77060c9af03a', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 51, 51, 'When the tabernacle is to move, the Levites shall take it down; and when the tabernacle is to be set up, the Levites shall set it up. The stranger who comes near shall be put to death.'),
  ('47cc7566-14ff-5446-a66c-0fefbe176649', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 52, 52, 'The children of Israel shall pitch their tents, every man by his own camp, and every man by his own standard, according to their divisions.'),
  ('616da483-b04c-5728-a9de-054edaf8ab7d', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 53, 53, 'But the Levites shall encamp around the Tabernacle of the Testimony, that there may be no wrath on the congregation of the children of Israel: and the Levites shall be responsible for the Tabernacle of the Testimony."'),
  ('68c78e5a-56dc-56ed-a792-bb23f1c5aa6c', 'da4661b1-78f2-55c3-a623-79f61519a79b', NULL, 54, 54, 'Thus the children of Israel did. According to all that Yahweh commanded Moses, so they did.'),
  ('b0e22011-2edb-591d-a13b-a29ff958f25f', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('6acc5d56-5d80-5127-a6c4-898c4d0985b4', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 2, 2, '"The children of Israel shall encamp every man by his own standard, with the banners of their fathers'' houses: at a distance from the Tent of Meeting shall they encamp around it."'),
  ('a5b412a7-28f3-5054-a21a-2272f5e6717f', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 3, 3, 'Those who encamp on the east side toward the sunrise shall be of the standard of the camp of Judah, according to their divisions: and the prince of the children of Judah shall be Nahshon the son of Amminadab.'),
  ('4cbcfde2-9793-5be5-a608-798be7a57b4c', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 4, 4, 'His division, and those who were numbered of them, were seventy-four thousand six hundred.'),
  ('b0bba6e5-4668-536e-a28f-960c66da9c7e', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 5, 5, 'Those who encamp next to him shall be the tribe of Issachar: and the prince of the children of Issachar shall be Nethanel the son of Zuar.'),
  ('cbaddb99-a715-588b-a375-5b9d7079ebcc', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 6, 6, 'His division, and those who were numbered of it, were fifty-four thousand four hundred.'),
  ('58a26fa8-2ef5-5d54-a521-71fdf056f6be', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 7, 7, 'The tribe of Zebulun: and the prince of the children of Zebulun shall be Eliab the son of Helon.'),
  ('135a5948-a3c2-5d86-a70b-a7fd5e193a87', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 8, 8, 'His division, and those who were numbered of it, were fifty-seven thousand four hundred.'),
  ('139772da-985c-50df-a12e-3bc565583408', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 9, 9, 'All who were numbered of the camp of Judah were one hundred eighty-six thousand four hundred, according to their divisions. They shall set out first.'),
  ('e9d18c37-0a8d-5dd8-a421-cfd7fade2fb1', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 10, 10, '"On the south side shall be the standard of the camp of Reuben according to their divisions. The prince of the children of Reuben shall be Elizur the son of Shedeur.'),
  ('161e3bdc-5128-5db7-af40-7abdb67dbad9', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 11, 11, 'His division, and those who were numbered of it, were forty-six thousand five hundred.'),
  ('1eb99ebe-c51c-55c3-a649-074af5177346', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 12, 12, '"Those who encamp next to him shall be the tribe of Simeon. The prince of the children of Simeon shall be Shelumiel the son of Zurishaddai.'),
  ('fec42e28-deae-52b9-aa04-db657d324461', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 13, 13, 'His division, and those who were numbered of them, were fifty-nine thousand three hundred.'),
  ('81d5670c-7e05-523e-a162-614e7c2ce4ff', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 14, 14, '"The tribe of Gad: and the prince of the children of Gad shall be Eliasaph the son of Reuel.'),
  ('9b3089bb-09c6-5267-a364-93811c945dab', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 15, 15, 'His division, and those who were numbered of them, were forty-five thousand six hundred fifty.'),
  ('503658c7-9ea1-5139-a3c9-072e09c32836', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 16, 16, '"All who were numbered of the camp of Reuben were one hundred fifty-one thousand four hundred fifty, according to their armies. They shall set out second.'),
  ('26482383-26e1-5eb7-ad77-f0fbf165db51', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 17, 17, '"Then the Tent of Meeting shall set out, with the camp of the Levites in the midst of the camps. As they encamp, so shall they set out, every man in his place, by their standards.'),
  ('d5df7cac-a561-5764-ac5f-540a8f1397e2', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 18, 18, '"On the west side shall be the standard of the camp of Ephraim according to their divisions: and the prince of the children of Ephraim shall be Elishama the son of Ammihud.'),
  ('979cf878-7e5a-5c03-a7e8-f16c4b7125b0', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 19, 19, 'His division, and those who were numbered of them, were forty thousand five hundred.'),
  ('1fd0de8f-2dc0-5d1b-a7c2-e49bdf8339e7', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 20, 20, '"Next to him shall be the tribe of Manasseh: and the prince of the children of Manasseh shall be Gamaliel the son of Pedahzur.'),
  ('1d438ea9-037e-5d84-ae97-4d32a9f1220f', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 21, 21, 'His division, and those who were numbered of them, were thirty-two thousand two hundred.'),
  ('59a6d566-0441-5573-aa28-b0827934f715', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 22, 22, '"The tribe of Benjamin: and the prince of the children of Benjamin shall be Abidan the son of Gideoni.'),
  ('e7a762a0-be8c-588d-af31-56416c0e1cd5', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 23, 23, 'His army, and those who were numbered of them, were thirty-five thousand four hundred.'),
  ('72586b5b-6cb2-5448-a668-ea290a786ece', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 24, 24, '"All who were numbered of the camp of Ephraim were one hundred eight thousand one hundred, according to their divisions. They shall set out third.'),
  ('4f69ab6f-406e-5f7f-aea6-de2d31a59680', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 25, 25, '"On the north side shall be the standard of the camp of Dan according to their divisions: and the prince of the children of Dan shall be Ahiezer the son of Ammishaddai.'),
  ('73669918-1c4a-56e5-a75e-97d9d065039a', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 26, 26, 'His division, and those who were numbered of them, were sixty-two thousand seven hundred.'),
  ('c63e3665-b220-58f0-a68b-e6cd54022645', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 27, 27, '"Those who encamp next to him shall be the tribe of Asher: and the prince of the children of Asher shall be Pagiel the son of Ochran.'),
  ('59573810-7d88-5b81-a5af-241723b8b7b6', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 28, 28, 'His division, and those who were numbered of them, were forty-one thousand and five hundred.'),
  ('c78d0102-6f26-5c8d-af6e-70c9410fd00c', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 29, 29, '"The tribe of Naphtali: and the prince of the children of Naphtali shall be Ahira the son of Enan.'),
  ('9220282d-8947-55c6-a2d2-15d4f6ce7110', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 30, 30, 'His division, and those who were numbered of them, were fifty-three thousand four hundred.'),
  ('92a363ac-6bf8-5651-a0a5-82deb8dee371', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 31, 31, '"All who were numbered of the camp of Dan were one hundred fifty-seven thousand six hundred. They shall set out last by their standards."'),
  ('f9e24b97-b045-52b5-a367-64a0d84dfbad', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 32, 32, 'These are those who were numbered of the children of Israel by their fathers'' houses. All who were numbered of the camps according to their armies were six hundred three thousand five hundred fifty.'),
  ('11a964fc-d7dd-59b7-ac04-8c5a4ea3b3a7', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 33, 33, 'But the Levites were not numbered among the children of Israel; as Yahweh commanded Moses.'),
  ('0a1f69e3-78a9-5580-a1bc-28867dd5e543', '2386d69f-e37a-547a-a229-2df30fde9c44', NULL, 34, 34, 'Thus the children of Israel did. According to all that Yahweh commanded Moses, so they encamped by their standards, and so they set out, everyone by their families, according to their fathers'' houses.'),
  ('7bd57e70-4832-53f4-aa71-04a5e983148b', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 1, 1, 'Now this is the history of the generations of Aaron and Moses in the day that Yahweh spoke with Moses in Mount Sinai.'),
  ('f53fccbf-fbe7-5958-a6d8-eb1aabe0a7e0', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 2, 2, 'These are the names of the sons of Aaron: Nadab the firstborn, and Abihu, Eleazar, and Ithamar.'),
  ('ba0fc736-4270-570e-a80b-278694040706', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 3, 3, 'These are the names of the sons of Aaron, the priests who were anointed, whom he consecrated to minister in the priest''s office.'),
  ('3098cb47-2e0b-536c-a50a-9fa397fef045', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 4, 4, 'Nadab and Abihu died before Yahweh, when they offered strange fire before Yahweh, in the wilderness of Sinai, and they had no children. Eleazar and Ithamar ministered in the priest''s office in the presence of Aaron their father.'),
  ('83277df4-aa0e-5f06-a7d8-90c6bad1b8d0', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 5, 5, 'Yahweh spoke to Moses, saying,'),
  ('f3e4ed61-809d-5893-aa11-f5fc8f3043b0', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 6, 6, '"Bring the tribe of Levi near, and set them before Aaron the priest, that they may minister to him.'),
  ('9a5f78c8-db7b-5c80-a6a8-31c2608378e9', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 7, 7, 'They shall keep his requirements, and the requirements of the whole congregation before the Tent of Meeting, to do the service of the tabernacle.'),
  ('26f969d6-cfe9-548d-aca4-97ff25e33c85', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 8, 8, 'They shall keep all the furnishings of the Tent of Meeting, and the obligations of the children of Israel, to do the service of the tabernacle.'),
  ('6dadd1e6-45d8-581c-a549-2cf31e46f094', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 9, 9, 'You shall give the Levites to Aaron and to his sons. They are wholly given to him on the behalf of the children of Israel.'),
  ('39e4283b-ea93-58f8-ab3b-3184af89dc8d', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 10, 10, 'You shall appoint Aaron and his sons, and they shall keep their priesthood. The stranger who comes near shall be put to death."'),
  ('2831740c-0832-5131-ae9e-c58d7ec8d623', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 11, 11, 'Yahweh spoke to Moses, saying,'),
  ('bc3887bc-5121-5b5d-a9d7-af4bdb5079a5', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 12, 12, '"Behold, I have taken the Levites from among the children of Israel instead of all the firstborn who open the womb among the children of Israel; and the Levites shall be mine:'),
  ('e92a164a-5a27-5380-a615-6831006d9d01', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 13, 13, 'for all the firstborn are mine. On the day that I struck down all the firstborn in the land of Egypt I made holy to me all the firstborn in Israel, both man and animal. They shall be mine. I am Yahweh."'),
  ('6afc5bf9-7091-520a-a456-826a7e8646bf', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 14, 14, 'Yahweh spoke to Moses in the wilderness of Sinai, saying,'),
  ('5482e83d-c951-50a3-a31e-544cb75d168a', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 15, 15, '"Count the children of Levi by their fathers'' houses, by their families. You shall count every male from a month old and upward."'),
  ('c612aba7-d609-5477-ac18-d90a1789e57f', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 16, 16, 'Moses numbered them according to the word of Yahweh, as he was commanded.'),
  ('563fbe99-e1c6-58c8-a08a-964b40f68d59', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 17, 17, 'These were the sons of Levi by their names: Gershon, and Kohath, and Merari.'),
  ('28d6e2b1-0ffb-5715-a8bc-88bd39d1caba', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 18, 18, 'These are the names of the sons of Gershon by their families: Libni and Shimei.'),
  ('7c62c09a-23f6-5219-adf6-8d6ab30480ab', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 19, 19, 'The sons of Kohath by their families: Amram, and Izhar, Hebron, and Uzziel.'),
  ('7b209153-89e6-583d-aa57-ec5f892b6b64', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 20, 20, 'The sons of Merari by their families: Mahli and Mushi. These are the families of the Levites according to their fathers'' houses.'),
  ('ab6f7f20-0973-57e6-a0d5-e5575abe4650', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 21, 21, 'Of Gershon was the family of the Libnites, and the family of the Shimeites: these are the families of the Gershonites.'),
  ('f4d98133-072f-5719-a0e9-7ecc045860ae', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 22, 22, 'Those who were numbered of them, according to the number of all the males, from a month old and upward, even those who were numbered of them were seven thousand five hundred.'),
  ('7b82d430-1903-556d-aea5-d3a7bf9b0491', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 23, 23, 'The families of the Gershonites shall encamp behind the tabernacle westward.'),
  ('2fdcf83e-f08f-5872-aaaf-7114f1eca9be', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 24, 24, 'The prince of the fathers'' house of the Gershonites shall be Eliasaph the son of Lael.'),
  ('071f12c7-5836-578c-ad43-dfdfadb1eab6', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 25, 25, 'The duty of the sons of Gershon in the Tent of Meeting shall be the tabernacle, and the tent, its covering, and the screen for the door of the Tent of Meeting,'),
  ('370d64db-6304-5b98-a8ae-711a6a0e2851', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 26, 26, 'and the hangings of the court, and the screen for the door of the court, which is by the tabernacle, and around the altar, and its cords for all of its service.'),
  ('e2c56f6b-b286-5677-a65b-52f0a5010ed6', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 27, 27, 'Of Kohath was the family of the Amramites, and the family of the Izharites, and the family of the Hebronites, and the family of the Uzzielites: these are the families of the Kohathites.'),
  ('9869747d-e60e-5f35-ad99-c1c283c1f473', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 28, 28, 'According to the number of all the males, from a month old and upward, there were eight thousand six hundred, keeping the requirements of the sanctuary.'),
  ('32a8d4f8-a022-5e2a-a535-f8005a1dcf55', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 29, 29, 'The families of the sons of Kohath shall encamp on the south side of the tabernacle.'),
  ('0ea3e96a-77cb-5562-a5e1-4f72dbb606af', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 30, 30, 'The prince of the fathers'' house of the families of the Kohathites shall be Elizaphan the son of Uzziel.'),
  ('f44e4af2-de5b-5c3a-a8d8-556d846a051e', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 31, 31, 'Their duty shall be the ark, the table, the lamp stand, the altars, the vessels of the sanctuary with which they minister, and the screen, and all its service.'),
  ('8a544432-d7e4-5806-a8ff-636f73434245', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 32, 32, 'Eleazar the son of Aaron the priest shall be prince of the princes of the Levites, with the oversight of those who keep the requirements of the sanctuary.'),
  ('30fe2ab7-75c3-57d8-aef4-8be6f8a36bac', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 33, 33, 'Of Merari was the family of the Mahlites, and the family of the Mushites. These are the families of Merari.'),
  ('9d1b0d96-31d6-5a95-a473-22105619daea', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 34, 34, 'Those who were numbered of them, according to the number of all the males, from a month old and upward, were six thousand two hundred.'),
  ('bcd267d2-e438-5f40-a894-011a141cb975', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 35, 35, 'The prince of the fathers'' house of the families of Merari was Zuriel the son of Abihail. They shall encamp on the north side of the tabernacle.'),
  ('e8b1203a-5731-599c-af59-bc6312ac0cc6', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 36, 36, 'The appointed duty of the sons of Merari shall be the tabernacle''s boards, its bars, its pillars, its sockets, all its instruments, all its service,'),
  ('af88f6bf-79f3-58d9-a4fa-6a706a413643', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 37, 37, 'the pillars of the court around it, their sockets, their pins, and their cords.'),
  ('622469d9-3529-57d4-af8c-8fb4e57d4574', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 38, 38, 'Those who encamp before the tabernacle eastward, in front of the Tent of Meeting toward the sunrise, shall be Moses, and Aaron and his sons, keeping the requirements of the sanctuary for the duty of the children of Israel. The stranger who comes near shall be put to death.'),
  ('78c4b1a6-fca4-57c0-aa15-32169fb22d19', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 39, 39, 'All who were numbered of the Levites, whom Moses and Aaron numbered at the commandment of Yahweh, by their families, all the males from a month old and upward, were twenty-two thousand.'),
  ('00fc2a75-e093-5449-aab2-6cd5368c71e8', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 40, 40, 'Yahweh said to Moses, "Number all the firstborn males of the children of Israel from a month old and upward, and take the number of their names.'),
  ('be4abefe-8ef0-57b7-aeda-dfbcabd24c69', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 41, 41, 'You shall take the Levites for me (I am Yahweh) instead of all the firstborn among the children of Israel; and the livestock of the Levites instead of all the firstborn among the livestock of the children of Israel."'),
  ('f0047c1a-ed52-5ebe-a667-c509ec6c2635', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 42, 42, 'Moses numbered, as Yahweh commanded him, all the firstborn among the children of Israel.'),
  ('9b578eeb-0f3f-5acb-a9d3-f9199cfb58fd', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 43, 43, 'All the firstborn males according to the number of names, from a month old and upward, of those who were numbered of them, were twenty-two thousand two hundred seventy-three.'),
  ('4b76c006-5015-5933-a601-28e2eda9a8eb', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 44, 44, 'Yahweh spoke to Moses, saying,'),
  ('b0b161bf-1615-58c5-a1c7-2eb712feeafc', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 45, 45, '"Take the Levites instead of all the firstborn among the children of Israel, and the livestock of the Levites instead of their livestock; and the Levites shall be mine. I am Yahweh.'),
  ('eae87fa5-fb35-51f9-a70e-a4794bcd26e3', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 46, 46, 'For the redemption of the two hundred seventy-three of the firstborn of the children of Israel, who exceed the number of the Levites,'),
  ('a3845e3d-dcbf-5f35-a433-8428405d91f6', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 47, 47, 'you shall take five shekels apiece for each one; after the shekel of the sanctuary you shall take them (the shekel is twenty gerahs):'),
  ('17d3051a-a619-5d58-a9f4-895b07ba92df', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 48, 48, 'and you shall give the money, with which the remainder of them is redeemed, to Aaron and to his sons."'),
  ('d67e9527-59d9-5f96-a62a-a4d28fb4029e', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 49, 49, 'Moses took the redemption money from those who exceeded the number of those who were redeemed by the Levites;'),
  ('ae703a2d-7660-574e-a0bb-d9f50c4f3ca9', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 50, 50, 'from the firstborn of the children of Israel he took the money, one thousand three hundred sixty-five shekels, after the shekel of the sanctuary:'),
  ('4df355c9-5f9a-5da9-aed6-1baaa0891bbd', '126301bb-c8f3-50f9-af6b-fdca9ff6b055', NULL, 51, 51, 'and Moses gave the redemption money to Aaron and to his sons, according to the word of Yahweh, as Yahweh commanded Moses.'),
  ('df60e587-10c5-5d1f-a844-120c836844b2', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('c9b45d9c-4330-5608-a466-d71a168ab1bd', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 2, 2, '"Take a census of the sons of Kohath from among the sons of Levi, by their families, by their fathers'' houses,'),
  ('4d02fb96-8934-532f-ad40-f51bb0581f22', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 3, 3, 'from thirty years old and upward even until fifty years old, all who enter into the service, to do the work in the Tent of Meeting.'),
  ('a69a1041-f8e6-5110-a367-c9e962a9cf11', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 4, 4, '"This is the service of the sons of Kohath in the Tent of Meeting, the most holy things.'),
  ('da4693d4-92be-5c19-a7b1-086a57616569', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 5, 5, 'When the camp moves forward, Aaron shall go in, and his sons, and they shall take down the veil of the screen, and cover the ark of the Testimony with it,'),
  ('e592df5a-4a29-537a-ac1e-d7c37e2161b7', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 6, 6, 'and shall put a covering of sealskin on it, and shall spread over it a cloth all of blue, and shall put in its poles.'),
  ('2f9826ca-ffe6-5079-a15b-e288aefce1e0', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 7, 7, '"On the table of show bread they shall spread a blue cloth, and put on it the dishes, the spoons, the bowls, and the cups with which to pour out; and the continual bread shall be on it.'),
  ('18ed35bf-6dbc-5815-a1e3-fd31a9720005', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 8, 8, 'They shall spread on them a scarlet cloth, and cover the same with a covering of sealskin, and shall put in its poles.'),
  ('d09b07b0-a1be-54c6-a8af-3902d7c334f5', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 9, 9, '"They shall take a blue cloth, and cover the lampstand of the light, and its lamps, and its snuffers, and its snuff dishes, and all its oil vessels, with which they minister to it.'),
  ('30e892ca-229f-52e4-accf-f401d90ffe4a', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 10, 10, 'They shall put it and all its vessels within a covering of sealskin, and shall put it on the frame.'),
  ('b6799664-b135-5d92-a98d-2b2ddbf32aef', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 11, 11, '"On the golden altar they shall spread a blue cloth, and cover it with a covering of sealskin, and shall put in its poles.'),
  ('0671f552-931f-51f9-a8e1-b3a8c92bb7d1', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 12, 12, '"They shall take all the vessels of ministry, with which they minister in the sanctuary, and put them in a blue cloth, and cover them with a covering of sealskin, and shall put them on the frame.'),
  ('c99be5f0-a78a-5632-a86a-917f0cbdf39c', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 13, 13, '"They shall take away the ashes from the altar, and spread a purple cloth on it.'),
  ('704dc7cc-56e5-5ba3-ab31-e5f08565795d', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 14, 14, 'They shall put on it all its vessels, with which they minister about it, the fire pans, the flesh hooks, the shovels, and the basins; all the vessels of the altar; and they shall spread on it a covering of sealskin, and put in its poles.'),
  ('1b01ac87-4111-5a65-a3dd-cdf059c94094', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 15, 15, '"When Aaron and his sons have finished covering the sanctuary, and all the furniture of the sanctuary, as the camp moves forward; after that, the sons of Kohath shall come to carry it: but they shall not touch the sanctuary, lest they die. These things are the burden of the sons of Kohath in the Tent of Meeting.'),
  ('d837e9a9-0a8a-5c2b-a95d-4cdc269f4d75', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 16, 16, '"The duty of Eleazar the son of Aaron the priest shall be the oil for the light, the sweet incense, the continual meal offering, and the anointing oil, the requirements of all the tabernacle, and of all that is in it, the sanctuary, and its furnishings."'),
  ('3c243937-09ff-5c31-a6ab-fcbe3dde692f', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 17, 17, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('4056b9b2-2995-58b6-a5ee-fd9290b67857', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 18, 18, '"Don''t cut off the tribe of the families of the Kohathites from among the Levites;'),
  ('79bf4e14-8da3-554e-a013-bacade81bcfd', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 19, 19, 'but thus do to them, that they may live, and not die, when they approach to the most holy things: Aaron and his sons shall go in, and appoint them everyone to his service and to his burden;'),
  ('dc8ff4ef-3346-58a4-aad8-18bd6b1d5b36', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 20, 20, 'but they shall not go in to see the sanctuary even for a moment, lest they die."'),
  ('73a20ddc-f620-529b-a065-cc74599c8a56', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 21, 21, 'Yahweh spoke to Moses, saying,'),
  ('cd963019-7a29-52e8-ac98-8fb34afe8d31', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 22, 22, '"Take a census of the sons of Gershon also, by their fathers'' houses, by their families;'),
  ('040f8671-79d8-516c-a88b-1202a120ecb2', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 23, 23, 'you shall count them from thirty years old and upward until fifty years old; all who enter in to wait on the service, to do the work in the Tent of Meeting.'),
  ('87139b03-2050-5555-a11d-c35a48214bb7', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 24, 24, '"This is the service of the families of the Gershonites, in serving and in bearing burdens:'),
  ('1d56c74e-8bae-5a1d-ad94-039f22f7e4da', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 25, 25, 'they shall carry the curtains of the tabernacle, and the Tent of Meeting, its covering, and the covering of sealskin that is above on it, and the screen for the door of the Tent of Meeting,'),
  ('bcc375aa-9208-5f82-a0d5-38c5b1c9d7dd', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 26, 26, 'and the hangings of the court, and the screen for the door of the gate of the court, which is by the tabernacle and around the altar, and their cords, and all the instruments of their service, and whatever shall be done with them. Therein shall they serve.'),
  ('fe5e3f90-ecb4-5c81-a360-6f7bf05b7705', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 27, 27, 'At the commandment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burden, and in all their service; and you shall appoint their duty to them in all their responsibilities.'),
  ('565b5903-52ba-5fc8-a489-5404e969d4a4', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 28, 28, 'This is the service of the families of the sons of the Gershonites in the Tent of Meeting: and their duty shall be under the hand of Ithamar the son of Aaron the priest.'),
  ('9f0cbcbb-41db-5c55-a9b0-1e306b4d7bdf', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 29, 29, '"As for the sons of Merari, you shall number them by their families, by their fathers'' houses;'),
  ('3b7d89b2-5c38-5f39-a2c3-771f7e99d1c8', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 30, 30, 'you shall count them from thirty years old and upward even to fifty years old, everyone who enters on the service, to do the work of the Tent of Meeting.'),
  ('ca9573b8-664e-5622-a020-5f213c51b7f6', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 31, 31, 'This is the duty of their burden, according to all their service in the Tent of Meeting: the tabernacle''s boards, its bars, its pillars, its sockets,'),
  ('356815f6-d771-5aa6-ad77-7ca1360ebc18', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 32, 32, 'and the pillars of the court around it, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name you shall appoint the instruments of the duty of their burden.'),
  ('c982a466-6f37-58fb-af6e-40b8f1c01836', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 33, 33, 'This is the service of the families of the sons of Merari, according to all their service, in the Tent of Meeting, under the hand of Ithamar the son of Aaron the priest."'),
  ('60d2bcf7-4309-5038-adbd-94e15093d6f7', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 34, 34, 'Moses and Aaron and the princes of the congregation numbered the sons of the Kohathites by their families, and by their fathers'' houses,'),
  ('25d18233-aefe-541d-a7ff-4e393d2644cb', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 35, 35, 'from thirty years old and upward even to fifty years old, everyone who entered into the service, for work in the Tent of Meeting.'),
  ('6e68dee8-9c5d-57dd-ad4d-05365e245b3e', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 36, 36, 'Those who were numbered of them by their families were two thousand seven hundred fifty.'),
  ('cf9fc2f8-b3f7-5dbf-a742-e12140d9a076', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 37, 37, 'These are those who were numbered of the families of the Kohathites, all who served in the Tent of Meeting, whom Moses and Aaron numbered according to the commandment of Yahweh by Moses.'),
  ('89069171-ad96-5e8a-aa00-af0c0fb178ac', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 38, 38, 'Those who were numbered of the sons of Gershon, their families, and by their fathers'' houses,'),
  ('96eeea9e-6f54-56bf-ae56-dae4958d33fd', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 39, 39, 'from thirty years old and upward even to fifty years old, everyone who entered into the service, for work in the Tent of Meeting,'),
  ('ef7233cd-512d-5ff5-acf7-3b020f0b677f', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 40, 40, 'even those who were numbered of them, by their families, by their fathers'' houses, were two thousand six hundred thirty.'),
  ('bf2262bb-3a60-571e-ae87-9235242f0168', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 41, 41, 'These are those who were numbered of the families of the sons of Gershon, all who served in the Tent of Meeting, whom Moses and Aaron numbered according to the commandment of Yahweh.'),
  ('92b84af5-1fc2-5e12-ad9e-d24b8b2948af', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 42, 42, 'Those who were numbered of the families of the sons of Merari, by their families, by their fathers'' houses,'),
  ('43b8ae38-3fb8-58b7-a80d-c743776aa753', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 43, 43, 'from thirty years old and upward even to fifty years old, everyone who entered into the service, for work in the Tent of Meeting,'),
  ('9e108934-6248-5ca4-a09a-ad1ab6c54a48', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 44, 44, 'even those who were numbered of them by their families, were three thousand two hundred.'),
  ('d0c8c6e6-77d0-5fe9-aba8-6e130597fa51', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 45, 45, 'These are those who were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the commandment of Yahweh by Moses.'),
  ('60e12833-3167-563a-ae9e-e13e6b6270c7', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 46, 46, 'All those who were numbered of the Levites, whom Moses and Aaron and the princes of Israel numbered, by their families, and by their fathers'' houses,'),
  ('cb1b5e70-b29d-5afd-a770-57c6868ddd18', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 47, 47, 'from thirty years old and upward even to fifty years old, everyone who entered in to do the work of service, and the work of bearing burdens in the Tent of Meeting,'),
  ('bb2bd547-0e5c-5cae-a568-759a3eb40b1b', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 48, 48, 'even those who were numbered of them, were eight thousand five hundred eighty.'),
  ('9fed5d74-a97b-59ab-a790-8efc934b96d9', '35a9a986-1d0e-5bc4-ad21-833f52418d55', NULL, 49, 49, 'According to the commandment of Yahweh they were numbered by Moses, everyone according to his service, and according to his burden. Thus were they numbered by him, as Yahweh commanded Moses.'),
  ('d48fcf1c-0e61-5378-af06-9e9df7670d8d', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('300f0ca7-e657-5882-a528-f4a8a43c7378', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 2, 2, '"Command the children of Israel that they put out of the camp every leper, and everyone who has an issue, and whoever is unclean by the dead.'),
  ('0c584393-9127-56e5-a967-952454e4d639', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 3, 3, 'Both you shall put male and female outside of the camp; that they not defile their camp, in the midst of which I dwell."'),
  ('99b43a10-d5f0-5d13-abfa-01a0b0a4e950', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 4, 4, 'The children of Israel did so, and put them out outside of the camp; as Yahweh spoke to Moses, so did the children of Israel.'),
  ('636f1a20-7ed4-57ba-a253-8e0e02032338', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 5, 5, 'Yahweh spoke to Moses, saying,'),
  ('c60e5d10-efab-5ccd-a575-f2b0ca19ca4a', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 6, 6, '"Speak to the children of Israel: ''When a man or woman commits any sin that men commit, so as to trespass against Yahweh, and that soul is guilty;'),
  ('ae65edee-8dbb-5661-a063-4046baff503b', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 7, 7, 'then he shall confess his sin which he has done, and he shall make restitution for his guilt in full, and add to it the fifth part of it, and give it to him in respect of whom he has been guilty.'),
  ('6c5ade7f-a4f3-5097-a630-9d35f7c9895d', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 8, 8, 'But if the man has no kinsman to whom restitution may be made for the guilt, the restitution for guilt which is made to Yahweh shall be the priest''s; besides the ram of the atonement, by which atonement shall be made for him.'),
  ('a6a3e853-299e-5ad6-a452-77f08b0d6611', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 9, 9, 'Every heave offering of all the holy things of the children of Israel, which they present to the priest, shall be his.'),
  ('0af37f0f-3d4f-5714-a39f-0d5fb4b0f105', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 10, 10, 'Every man''s holy things shall be his: whatever any man gives the priest, it shall be his.''"'),
  ('a8fe4ae7-7fe4-5250-a07e-85a797d1c07d', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 11, 11, 'Yahweh spoke to Moses, saying,'),
  ('8a4dce89-790c-5732-ac0d-148fed5b8b2a', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 12, 12, '"Speak to the children of Israel, and tell them: ''If any man''s wife goes astray, and is unfaithful to him,'),
  ('524de738-fa6d-5961-abb8-ec2bcef4a30b', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 13, 13, 'and a man lies with her carnally, and it is hidden from the eyes of her husband, and is kept close, and she is defiled, and there is no witness against her, and she isn''t taken in the act;'),
  ('afc80a7a-8f00-509f-ab87-1f6087c83e91', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 14, 14, 'and the spirit of jealousy comes on him, and he is jealous of his wife, and she is defiled: or if the spirit of jealousy comes on him, and he is jealous of his wife, and she isn''t defiled:'),
  ('c184d6d9-9b86-519b-ab21-0a12a82bca38', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 15, 15, 'then the man shall bring his wife to the priest, and shall bring her offering for her: the tenth part of an ephah of barley meal. He shall pour no oil on it, nor put frankincense on it, for it is a meal offering of jealousy, a meal offering of memorial, bringing iniquity to memory.'),
  ('cfb5caca-51fb-5ef7-a4a6-32d4106c092f', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 16, 16, 'The priest shall bring her near, and set her before Yahweh;'),
  ('8740b6de-dabc-59ce-a678-46f15f684687', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 17, 17, 'and the priest shall take holy water in an earthen vessel; and of the dust that is on the floor of the tabernacle the priest shall take, and put it into the water.'),
  ('164cc1e4-45dd-50bc-a0f2-fc94697adbdd', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 18, 18, 'The priest shall set the woman before Yahweh, and let the hair of the woman''s head go loose, and put the meal offering of memorial in her hands, which is the meal offering of jealousy. The priest shall have in his hand the water of bitterness that brings a curse.'),
  ('098e1d4c-bc4c-53c3-af16-166fe80cd6b0', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 19, 19, 'The priest shall cause her to swear, and shall tell the woman, "If no man has lain with you, and if you haven''t gone aside to uncleanness, being under your husband, be free from this water of bitterness that brings a curse.'),
  ('453794cc-8b21-5664-ad12-2f6a0f7e0b58', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 20, 20, 'But if you have gone astray, being under your husband, and if you are defiled, and some man has lain with you besides your husband:"'),
  ('74c8aad8-4b67-571f-ad65-a7355ca12db8', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 21, 21, 'then the priest shall cause the woman to swear with the oath of cursing, and the priest shall tell the woman, "Yahweh make you a curse and an oath among your people, when Yahweh allows your thigh to fall away, and your body to swell;'),
  ('652ec46e-3b5e-5d70-ac2f-4d27fb6440b6', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 22, 22, 'and this water that brings a curse will go into your bowels, and make your body swell, and your thigh fall away." The woman shall say, "Amen, Amen."'),
  ('63ad4a9a-c18e-5a61-a0fd-9d9b888d9d3c', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 23, 23, '"''The priest shall write these curses in a book, and he shall blot them out into the water of bitterness.'),
  ('39adb045-f21b-5573-a5f8-cdebdbe18897', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 24, 24, 'He shall make the woman drink the water of bitterness that causes the curse; and the water that causes the curse shall enter into her and become bitter.'),
  ('04a316dc-709e-5777-acb2-a7505e711a5e', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 25, 25, 'The priest shall take the meal offering of jealousy out of the woman''s hand, and shall wave the meal offering before Yahweh, and bring it to the altar.'),
  ('7bf2d642-cd63-5fe3-ad8c-be0d2511912a', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 26, 26, 'The priest shall take a handful of the meal offering, as its memorial, and burn it on the altar, and afterward shall make the woman drink the water.'),
  ('f9893764-5cb6-5809-ad3e-110457e1b11c', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 27, 27, 'When he has made her drink the water, then it shall happen, if she is defiled, and has committed a trespass against her husband, that the water that causes the curse will enter into her and become bitter, and her body will swell, and her thigh will fall away: and the woman will be a curse among her people.'),
  ('4a992e83-1802-56db-a4da-c4902bbddcda', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 28, 28, 'If the woman isn''t defiled, but is clean; then she shall be free, and shall conceive seed.'),
  ('f828c420-30a4-5e6d-a8ee-8460a650643f', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 29, 29, '"''This is the law of jealousy, when a wife, being under her husband, goes astray, and is defiled;'),
  ('68595225-8c0e-5780-abc7-c1a4e4223b07', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 30, 30, 'or when the spirit of jealousy comes on a man, and he is jealous of his wife; then he shall set the woman before Yahweh, and the priest shall execute on her all this law.'),
  ('56c826a6-01e5-567a-ab4f-715eadaf575c', 'c5035139-041c-5cbb-a24e-277c8787c0e4', NULL, 31, 31, 'The man shall be free from iniquity, and that woman shall bear her iniquity.''"'),
  ('43106380-6f2d-5d71-ace2-be7bfe875ca7', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('fa75adc3-3c38-5bf3-a1c6-c8f89e57f7bf', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 2, 2, '"Speak to the children of Israel, and tell them: ''When either man or woman shall make a special vow, the vow of a Nazirite, to separate himself to Yahweh,'),
  ('dda88052-e77c-57e2-af40-276234fe1d8c', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 3, 3, 'he shall separate himself from wine and strong drink. He shall drink no vinegar of wine, or vinegar of fermented drink, neither shall he drink any juice of grapes, nor eat fresh grapes or dried.'),
  ('e6be4661-8125-5455-a591-14bb5a1c1bc3', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 4, 4, 'All the days of his separation he shall eat nothing that is made of the grapevine, from the seeds even to the skins.'),
  ('6388c0f3-5c86-5ccc-ad9d-d08df3091804', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 5, 5, '"''All the days of his vow of separation no razor shall come on his head, until the days are fulfilled, in which he separates himself to Yahweh. He shall be holy. He shall let the locks of the hair of his head grow long.'),
  ('11db7df9-c96d-56e4-a4ae-5de13c7119dd', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 6, 6, '"''All the days that he separates himself to Yahweh he shall not go near a dead body.'),
  ('4e656304-81f7-539d-a8ac-1214f47ecba5', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 7, 7, 'He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die; because his separation to God is on his head.'),
  ('b2e42f36-823a-5d30-a04d-6680494d01ac', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 8, 8, 'All the days of his separation he is holy to Yahweh.'),
  ('a9fce9bc-17b3-5fa6-a92f-1ddd9f36b92d', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 9, 9, '"''If any man dies very suddenly beside him, and he defiles the head of his separation; then he shall shave his head in the day of his cleansing. On the seventh day he shall shave it.'),
  ('b8e9322d-f72a-5fb2-acfb-8baf054709c7', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 10, 10, 'On the eighth day he shall bring two turtledoves or two young pigeons to the priest, to the door of the Tent of Meeting.'),
  ('bf9606a7-132d-55e8-ad6e-5d5259781fb1', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 11, 11, 'The priest shall offer one for a sin offering, and the other for a burnt offering, and make atonement for him, because he sinned by reason of the dead, and shall make his head holy that same day.'),
  ('573315bf-85fc-5864-af0e-91cfc285ee72', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 12, 12, 'He shall separate to Yahweh the days of his separation, and shall bring a male lamb a year old for a trespass offering; but the former days shall be void, because his separation was defiled.'),
  ('b2356763-c7b1-53af-a5bb-dd39530d6795', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 13, 13, '"''This is the law of the Nazirite: when the days of his separation are fulfilled, he shall be brought to the door of the Tent of Meeting,'),
  ('e384e642-7cdd-5160-a1d0-4b4f29e0bfad', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 14, 14, 'and he shall offer his offering to Yahweh, one male lamb a year old without blemish for a burnt offering, and one ewe lamb a year old without blemish for a sin offering, and one ram without blemish for peace offerings,'),
  ('8b0f5a7a-3f40-5278-a6a2-6781931546e5', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 15, 15, 'and a basket of unleavened bread, cakes of fine flour mixed with oil, and unleavened wafers anointed with oil, and their meal offering, and their drink offerings.'),
  ('5f353003-f62e-5f87-a0d4-f6c8445a5863', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 16, 16, 'The priest shall present them before Yahweh, and shall offer his sin offering, and his burnt offering.'),
  ('e0f1dbed-4cf4-5f48-a347-649ceb1d2295', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 17, 17, 'He shall offer the ram for a sacrifice of peace offerings to Yahweh, with the basket of unleavened bread. The priest shall offer also its meal offering, and its drink offering.'),
  ('00f18976-dbd3-518d-a30e-92bb866f8103', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 18, 18, 'The Nazirite shall shave the head of his separation at the door of the Tent of Meeting, and shall take the hair of the head of his separation, and put it on the fire which is under the sacrifice of peace offerings.'),
  ('8661f450-3391-52f1-a4c4-41af86146c8c', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 19, 19, 'The priest shall take the boiled shoulder of the ram, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them on the hands of the Nazirite, after he has shaved the head of his separation;'),
  ('0b8c9449-596d-5ce7-ac42-8f8e89eea54e', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 20, 20, 'and the priest shall wave them for a wave offering before Yahweh. This is holy for the priest, together with the breast that is waved and the thigh that is offered. After that the Nazirite may drink wine.'),
  ('315de29d-3dd9-5267-a778-b86281f4d89f', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 21, 21, '"''This is the law of the Nazirite who vows, and of his offering to Yahweh for his separation, besides that which he is able to get. According to his vow which he vows, so he must do after the law of his separation.''"'),
  ('5ae81022-7900-5556-a686-60990ebdec8b', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 22, 22, 'Yahweh spoke to Moses, saying,'),
  ('9ad59f2b-bf80-595d-aecd-38f8a7ba23ba', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 23, 23, '"Speak to Aaron and to his sons, saying, ''This is how you shall bless the children of Israel.'' You shall tell them,'),
  ('9c0c363e-b180-5920-a994-44a96cf1085a', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 24, 24, '''Yahweh bless you, and keep you.'),
  ('7dec1d9d-4a7d-5011-a877-4aa3024fc4d6', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 25, 25, 'Yahweh make his face to shine on you, and be gracious to you.'),
  ('c25d145d-aeae-5b02-a640-98b12030f4cc', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 26, 26, 'Yahweh lift up his face toward you, and give you peace.'''),
  ('d55263b6-301d-5d1d-a6ed-88962be8c16b', 'b546717a-349c-5e45-ac2b-11c63782b041', NULL, 27, 27, '"So they shall put my name on the children of Israel; and I will bless them."'),
  ('f1e45067-1a83-591f-a853-48a4eaa0ef6c', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 1, 1, 'It happened on the day that Moses had finished setting up the tabernacle, and had anointed it and sanctified it, with all its furniture, and the altar with all its vessels, and had anointed and sanctified them;'),
  ('53697ac1-e5e1-5308-a602-12e811dbd2c5', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 2, 2, 'that the princes of Israel, the heads of their fathers'' houses, offered. These were the princes of the tribes. These are they who were over those who were numbered:'),
  ('1e2dcdd1-60b2-5f68-a8f1-cdf9f78c33a0', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 3, 3, 'and they brought their offering before Yahweh, six covered wagons, and twelve oxen; a wagon for every two of the princes, and for each one an ox: and they presented them before the tabernacle.'),
  ('5830dc38-1561-501e-a26d-85a55c7e9c6b', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 4, 4, 'Yahweh spoke to Moses, saying,'),
  ('75653b21-c1bf-548b-afda-b0445fdc31c4', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 5, 5, '"Accept these from them, that they may be used in doing the service of the Tent of Meeting; and you shall give them to the Levites, to every man according to his service."'),
  ('f2c0f7b4-0fc3-59b9-a727-6a14557a1d89', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 6, 6, 'Moses took the wagons and the oxen, and gave them to the Levites.'),
  ('51f3e485-8b13-5280-a39f-32cc66b5ea6d', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 7, 7, 'He gave two wagons and four oxen to the sons of Gershon, according to their service:'),
  ('7a2cdea0-9b85-577c-a54d-9476c58fdeee', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 8, 8, 'and he gave four wagons and eight oxen to the sons of Merari, according to their service, under the direction of Ithamar the son of Aaron the priest.'),
  ('d0f02d6d-76cb-56fc-a968-eed96d358624', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 9, 9, 'But to the sons of Kohath he gave none, because the service of the sanctuary belonged to them; they carried it on their shoulders.'),
  ('48be09b2-08b1-5003-a396-6e7b1b13aa52', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 10, 10, 'The princes gave offerings for the dedication of the altar in the day that it was anointed, even the princes gave their offerings before the altar.')
